/// <summary>
/// 依目前資料庫中的會員、文物與縮小複製品建立可重複的本機展示資料。
/// </summary>
/// <remarks>
/// 這裡刻意使用 EF Core 實體與穩定識別碼，而不是把大量文章和商品名稱硬編在 SQL。
/// 這樣展示內容會跟著目前的文物資料變化，重跑時也不會因為亂數而失去關聯。
/// 這個命令只適合本機展示資料庫，不會建立 Schema，也不會刪除非本命令產生的資料。
/// </remarks>
public static class ShowcaseDataCommands
