        new("CATALOG", "器形比較", "CUSTOM", "自然科學博物館裡的一個形狀，讓我想到文物的比例", "去國立自然科學博物館看展時，注意到一個展示標本的比例關係，回家後竟然一直拿它和圖鑑裡的器形比較。兩者當然不是同一類東西，但把寬度、厚度和觀看距離拆開來想，讓我比較能理解尺寸資料。"),
        new("GENERAL", "參觀心得", "CUSTOM", "高雄歷史博物館的一段說明，我讀了兩次才記住", "在高雄市立歷史博物館看到一段不長的說明，第一次讀只留下大概的印象，走到下一個展櫃才發現自己其實沒有看懂。回頭再讀時，我把人名、地點和物件分開記，終於比較能說出它在講什麼。"),
