        new("CATALOG", "局部觀察", "CUSTOM", "器口的轉折比醒目的紋飾更早改變我的判斷", "我原本被表面紋飾吸引，後來把視線移到器口和腹部的連接處，才發現整個形狀和第一眼想的不一樣。把局部放大並沒有讓資料變得更肯定，卻讓我知道自己剛才漏看了哪裡。"),
        new("DISCOVERY", "保存狀態", "CUSTOM", "照片裡的陰影差點讓我誤判表面狀態", "整理參觀照片時，我差點把一塊深色陰影當成作品本身的紋理，直到換一張角度比較平的影像才發現那是燈光造成的。現在寫心得會順手標註拍攝方向，不再把單張照片的效果直接當成原貌。"),
        new("CATALOG", "尺寸比較", "CUSTOM", "把尺寸資料換成日常物品後，作品突然變得很具體", "只看幾公分的數字時，我對大小沒有太多感覺，後來拿家裡的杯子和書本比了一下，才知道自己原本想像得太大。這個小練習不能推定作品用途，但很適合先校正觀看時的尺度。"),
        new("GUIDE", "整理方法", "CUSTOM", "我現在會把現場筆記和回家查到的內容分成兩欄", "以前參觀時想到什麼就全部寫在同一頁，回家後常常分不清哪些是展場原文、哪些是自己的猜測。最近改成左邊記當下看到的內容，右邊再補查證結果，雖然慢一點，但回頭修改時清楚很多。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "兩件作品名稱很像，我先從編號而不是印象開始對照", "整理資料時遇到兩個名稱很接近的作品，若只看縮圖很容易以為是同一件。我先把外部編號和圖像位置抄下來，再逐項比對分類與尺寸，這樣最後留下的差異比較能被別人回查。"),
        new("CATALOG", "紋飾細節", "CUSTOM", "青瓷的顏色不是我原本以為的單一淺綠", "看青瓷照片時，第一眼只覺得是淺綠色，放大後才看到釉面不同位置有細微的深淺差。這些差異可能和光線、拍攝或保存狀態都有關，所以我先記錄看到的效果，沒有急著替材質下結論。"),
        new("CATALOG", "器形比較", "CUSTOM", "玉器穿孔的位置，讓我開始想像它原本怎麼被拿取", "這件玉器最先吸引我的是穿孔的位置，而不是表面的顏色。我試著從孔的方向和器物厚度思考它可能如何被固定或攜帶，但目前只把這些列為問題，還不把想像寫成確定用途。"),
        new("CATALOG", "局部觀察", "CUSTOM", "漆器邊緣的細線，縮圖真的很容易看不見", "縮圖裡看起來很整齊的漆器，放大後才發現邊緣有一段細線和主體紋樣不完全平行。它也許是製作留下的效果，也可能只是影像解析度造成的錯覺，我把原圖和放大圖一起留著，等找到更多角度再判斷。"),
        new("REVIEW", "展陳想像", "CUSTOM", "看畫作時退後一步，留白比我預想的更有存在感", "我在畫前站得太近時，只看到筆觸和顏色，退到通道邊才看見留白如何把視線帶往遠處。這次沒有把現場感覺直接寫成作品解讀，而是先留下觀看距離和第一印象，之後再回到資料慢慢對照。"),
        new("DISCOVERY", "材質與工藝", "CUSTOM", "青銅表面的光澤不能直接拿來判斷年代", "以前很容易把表面的亮暗和年代連在一起，最近看青銅器時先把光線、反光和可能的鏽蝕分開記錄。這樣寫起來比較保守，但至少不會因為照片看起來新或舊，就跳過真正需要查證的工藝資料。"),
        new("QUESTION", "資料判讀", "CUSTOM", "錢幣上的字我看得出來，背後的資料卻還沒讀懂", "看到錢幣正面的字樣時，我以為自己已經掌握重點，查到不同版本的資料後才發現還有書體、鑄造和流通背景等問題。現在先把能辨識的字記下來，再列出不確定的地方，免得一句看似完整的解釋遮住疑問。"),
        new("GUIDE", "觀看順序", "CUSTOM", "同一件作品先看文字還是先看圖，我試了兩種順序", "第一次我先讀完整說明再看影像，第二次則先不看文字，只記下自己注意到的形狀和色彩。兩次留下的重點差很多，現在比較喜歡把兩份筆記並排放，看看資料如何改變自己的第一印象。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "沒有看懂不代表沒有收穫，我把卡住的地方留下來了", "有一件作品我看了幾次還是說不出用途，原本想乾脆跳過，後來改記下它讓我卡住的原因。知道自己缺的是尺寸、同類比較還是來源資料，至少讓下一次查找有方向，也比較容易請教別人。"),
        new("GUIDE", "查證筆記", "CUSTOM", "參觀照片不再全部留著，我只保留能說明問題的幾張", "以前每次看展都拍很多照片，回家後反而找不到真正有用的那一張。這次先替每張照片加上展廳、角度和想確認的事情，最後只留下可以幫助回想或查證的影像，整理起來輕鬆很多。"),
        new("REVIEW", "光線影響", "CUSTOM", "同一個展櫃換一個時間看，顏色感覺真的不同", "上午和下午各看了一次同一個展櫃，表面顏色在不同光線下呈現不一樣的濃淡。我沒有把這個差異當成作品改變，而是把時間與站的位置記起來，提醒自己照片和現場感受都需要條件一起看。"),
        new("CATALOG", "尺寸比較", "CUSTOM", "小件作品也需要看比例，不能只說它很小", "我以前介紹小件作品時只會說很精巧，這次把長、寬和厚度一起讀，才發現真正影響觀看感覺的是比例。數字不會自動告訴我作品怎麼使用，但能先阻止一些太快的想像。"),
        new("GENERAL", "收藏脈絡", "CUSTOM", "從一個不熟的名稱開始查，最後找到一條自己的閱讀路線", "一開始只是被一個不熟悉的名稱吸引，沿著分類、年代和來源往下看，途中又遇到幾件相關作品。最後沒有得到一個很大的結論，卻整理出一條自己下次還走得回去的閱讀路線。"),
        new("DISCOVERY", "保存狀態", "CUSTOM", "作品看起來的痕跡，可能不是製作時就有的樣子", "我在照片裡看到幾道細痕，第一反應是把它當成工藝的一部分，後來查到保存和修復也可能留下類似效果。現在遇到不熟的表面細節時，會把原始觀察和原因推測分開，留給後續資料修正。"),
        new("QUESTION", "同類比較", "CUSTOM", "相近器形放在一起看，差異比單獨欣賞時明顯很多", "單獨看每件作品時，我只覺得它們都很像，排成一列後才看出器口、腹部和底足的變化。這次比較沒有先找誰比較漂亮，而是先找哪幾個欄位真的不同，討論起來比較不會只剩喜好。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "我把專有名詞換成自己的話，再附回原本的詞", "碰到不熟的名詞時，我先用自己能理解的句子記錄，再在後面附上資料中的原詞。這樣回頭看時不會只剩一串背過的名稱，也能在需要查來源時準確找到原本使用的說法。"),
        new("REVIEW", "近看心得", "CUSTOM", "最不起眼的角落，反而成了我今天記得最久的地方", "今天沒有停在最醒目的主體，而是花時間看展櫃角落一件比較小的作品。它沒有立刻給我一個故事，卻讓我注意到邊緣、底部和展示高度；離開後回想，這些條件反而比名稱更鮮明。"),
        new("GENERAL", "參觀心得", "CUSTOM", "第一次自己看展，我終於沒有急著把每件都看完", "以前和別人一起看展時，總覺得要把所有展櫃都走過才算完整。這次自己來，只挑幾件真正想理解的作品停留，其餘先記下名稱和位置，離開時雖然看的件數少，記得的內容卻多很多。"),
        new("CATALOG", "局部觀察", "CUSTOM", "一張側面影像補上了我一直缺少的形狀", "原本只看正面影像，對作品的厚度和轉折沒有概念，後來找到側面照片，才把之前想像中的平面輪廓修正過來。這次讓我知道，遇到看不懂的地方不一定要立刻猜，也可以先去找另一個觀看角度。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我回頭查了參觀時記下的資料，才發現自己抄錯一個字", "整理紙本筆記時，發現自己把一個名稱抄成了很像的另一個字，幸好還留著展櫃照片可以回頭核對。現在只要寫到不熟的名稱，就會把影像、原文和自己的轉寫一起保留，不再只依賴記憶。"),
        new("QUESTION", "開放提問", "CUSTOM", "有些尺寸資料寫待測量，我想知道大家會怎麼繼續閱讀", "遇到尺寸欄位寫著待測量的作品，我不想自己補一個看似合理的數字。想請教有經驗的人，這種情況下通常會先看哪些影像或來源；我目前會先把能確認的器形和名稱記好，等待更可靠的資料。"),
        new("REVIEW", "展陳想像", "CUSTOM", "展櫃高度會改變我先看到的是正面還是器口", "同一件作品在不同展櫃高度觀看，視線落點差很多。站得太低時我一直先看到正面，換到稍微高一點的位置才注意到器口，這讓我開始把展示條件也當成參觀心得的一部分記錄。"),
        new("GUIDE", "整理方法", "CUSTOM", "我替一次參觀留下三個下次可以接著查的問題", "今天沒有試著把所有資料整理成完整文章，只在最後留下三個明確問題：一個關於來源、一個關於尺寸、一個關於相近作品。這樣下次打開筆記時知道要從哪裡開始，不會又從模糊的印象重新摸索。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "和朋友各自介紹同一個展區，才知道我們看到的完全不同", "我和朋友在同一個展區各挑一件作品介紹，結果一個人記得表面顏色，另一個人記得作品旁的來源說明。這種差異沒有誰對誰錯，反而提醒我們分享時最好說明自己是從哪個角度開始看的。"),
        new("CATALOG", "器形比較", "CUSTOM", "把兩個看似相同的器口並排後，差異終於說得出來", "之前只會說兩件作品的器口很像，今天把影像並排，改從口沿厚薄、轉折角度和腹部距離描述，才真的能指出差異。把喜歡或不喜歡放到後面，討論就不會卡在形容詞。")
    ];

    private static readonly IReadOnlyList<CommunityStory> CommunityStoriesPartTwo =
    [
        new("EVENTS", "活動交流", "TEMPLATE", "第一次參加文物導讀，我最意外的是大家先不急著猜答案", "導讀一開始沒有直接公布作品背景，而是請大家先說自己看見了什麼。我原本以為這樣會拖慢進度，結果每個人注意到的地方都不同，輪到我發言時也比較敢把還沒想清楚的部分說出來。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動取消後我沒有刪掉原本的參觀計畫", "原本想參加的活動臨時取消，我先把通知和原定時間留著，再自己查了幾件可能會看到的作品。雖然沒有現場交流，這份計畫後來變成下次到館時的清單，也讓我知道自己最想補看的區域。"),
        new("EVENTS", "活動交流", "TEMPLATE", "如果要去南院參加活動，我會把集合位置先記成文字", "上次到南院時花了一點時間找入口，所以這次看到活動資訊先把館區、入口和報到時間抄在行程裡。地圖能幫我確認大方向，但真正到場前，我還是會保留清楚的文字位置和交通備註。"),
        new("EVENTS", "活動交流", "TEMPLATE", "工作坊裡每個人對同一個紋樣的說法都不一樣", "工作坊請我們觀察一段重複紋樣，再各自說明它帶來的感覺。有人先注意排列，有人先看轉角，我原本以為自己看得很清楚，聽完別人的描述才發現還有一個方向完全沒注意到。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動講義帶回家後，我重新分辨哪些是現場聽到的內容", "活動當天寫了很多箭頭和縮寫，回家隔天再看時，差點把自己的猜測當成講者的說明。這次我把講義原文、現場筆記和回家查到的內容分成三層，整理後反而比當天更接近自己的真正疑問。"),
        new("EVENTS", "活動交流", "TEMPLATE", "線上導讀結束後，我最想補看的不是主題作品", "線上導讀介紹了幾件焦點作品，但我最後記住的是講者提到的另一件小品。活動結束後回到圖鑑搜尋，才發現自己一直忽略它；有時候真正讓人想繼續查的，是說明裡一個沒有展開的小線索。"),
        new("EVENTS", "活動交流", "TEMPLATE", "帶第一次看展的朋友參加活動，時間安排要留鬆一點", "朋友第一次參加文物活動，我沒有把前後行程排得太滿，讓他可以在每個展櫃前停下來問問題。講者講到專有名詞時，我們就先用自己的話記下來，回家再一起找正式資料，整體比較不會有壓力。"),
        new("EVENTS", "活動交流", "TEMPLATE", "這場活動讓我改掉只拍主展品的習慣", "以前參加活動只會拍講者介紹的主展品，這次特別把展櫃標示、觀看角度和旁邊的比較作品也記下來。回家整理時才發現，那些看似不是主角的影像，反而幫我理解講解中的差異。"),
        new("GAME", "遊戲回顧", "CUSTOM", "昨晚鑑定遊戲那題，我太早被一個顏色帶走了", "遊戲開始時我先看到表面的顏色，就很快把答案往某個年代靠，後來才發現器形和尺寸根本沒有跟著支持這個猜測。揭曉後回到圖鑑，我把自己最早下結論的那一步寫下來，下一次想先忍住幾秒再看完整資料。"),
        new("GAME", "遊戲回顧", "CUSTOM", "同一題有人先看器形，有人先查來源，結果很有趣", "這回合結束後大家分享判斷順序，有人從器形開始，有人先看來源文字，也有人只記得一個很小的局部。最後不一定是最快回答的人最接近答案，但每個人的理由都能指出一個值得回圖鑑核對的地方。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我把三次答錯的原因整理成一張自己的練習表", "連續三次答錯後，我沒有只記住正確答案，而是把錯誤分成看漏細節、把相似作品混在一起，以及時間不夠三類。現在再遇到題目時，會先檢查是哪一種狀況，練習起來比一直背答案有效。"),
        new("GAME", "遊戲回顧", "CUSTOM", "新手玩鑑定遊戲時，我會先把看到的線索寫成短句", "第一次玩的朋友常常覺得要馬上說出完整故事，我會請他先把看到的形狀、顏色、尺寸或文字各寫成一句短句。這樣不必一開始就猜結論，時間到了也還留得住自己的推理過程。"),
        new("GAME", "遊戲回顧", "CUSTOM", "投票階段最難的不是選答案，而是先讀完別人的理由", "以前進入投票就只看哪個答案寫得最像故事，這次刻意先讀每個人的理由，再回頭對照題目提供的線索。最後投的仍然不是我最喜歡的文字，而是我覺得比較能回到圖鑑資料的那一個。"),
        new("GAME", "遊戲回顧", "CUSTOM", "有時間限制後，我才發現自己平常看展很依賴回頭重看", "遊戲裡不能一直把同一張圖放大，讓我發現平常看展時常常先憑感覺記住，之後再回頭補細節。這個習慣在遊戲裡很吃虧，所以我開始練習第一輪就先看整體，再挑真正有用的局部。"),
        new("GAME", "遊戲回顧", "CUSTOM", "回合揭曉後回到圖鑑，才知道我漏掉的是哪個欄位", "看到答案公布時，我只覺得自己猜錯了一個年代，回到圖鑑逐項比對後才發現真正漏掉的是作品分類。把回合記錄和正式資料放在一起看，比只記住誰答對更能幫助我下一次判斷。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我喜歡玩家寫出不確定的地方，討論才不會變成背答案", "這一回合有玩家直接寫出自己不確定的線索，反而讓後續討論比較容易開始。大家可以針對那個疑問補資料，而不是只在揭曉後說早就知道；對新手來說，這種回顧氣氛更願意留下來玩。"),
        new("GAME", "遊戲回顧", "CUSTOM", "房間裡有人用很生活化的比喻，我終於理解作品大小", "有玩家把作品的尺寸和手掌、茶杯放在一起比喻，我本來以為這只是閒聊，後來發現它確實幫我校正了尺度。當然比喻不能代替正式尺寸，但在有限時間裡先建立大小感很有幫助。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我把博物館咖啡時間留給剛才沒看懂的那件作品", "逛完一輪後沒有立刻離館，而是在休息時把剛才最不懂的名稱重新打開。重新看一次時，沒有突然得到完整答案，但至少能指出自己缺的是來源還是形制，回去查資料就不會漫無目的。"),
        new("GENERAL", "參觀心得", "CUSTOM", "送給朋友的文物小禮物，我先確認他真的會想看資料", "朋友喜歡桌上小物，我沒有只挑外觀，而是先找了一件能連回圖鑑的縮小複製品。送出時一起分享原作資料，對方後來真的回來問我作品的尺寸，這比單純說它很好看更有意思。"),
        new("REVIEW", "收藏心得", "CUSTOM", "收到縮小複製品後，我先把它和原作資料放在同一個閱讀清單", "這次收到小型複製品，我沒有馬上替它找最顯眼的位置，而是先把商品名稱、對應作品和自己的參觀照片放在一起。這樣每次看到它，都能想起自己為什麼對那件文物感興趣，而不是只記得下單。"),
        new("REVIEW", "收藏心得", "CUSTOM", "展示櫃裡放小型複製品，我會刻意留一段空白", "我以前總想把展示櫃塞滿，最近改成每件小複製品旁邊留一點空白，從坐著和站著的高度各看一次。空間變鬆後，器形反而更容易被看見，也比較不會互相碰撞。"),
        new("REVIEW", "收藏心得", "CUSTOM", "商品到了才發現，原作尺寸和展示比例很值得一起聊", "拆箱時第一個感覺不是像不像，而是它的比例讓我重新想起原作資料裡的長寬高。把模型、商品說明和圖鑑放在同一張桌上看，才知道縮小之後哪些輪廓保留下來，哪些細節本來就不可能完整呈現。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我把家裡的燈光換成比較柔和後，表面細節好看很多", "原本放在桌燈正下方，表面反光太強，很多細節只剩一片亮。換成從側前方照的柔和光線後，輪廓和凹凸比較清楚；這個經驗也讓我回想起參觀時，現場光線同樣會改變第一印象。"),
        new("REVIEW", "收藏心得", "CUSTOM", "買之前我先比較展示尺寸，沒有只看商品主圖", "下單前我把幾件想買的縮小複製品尺寸寫在紙上，順便量了書架可用的深度。最後選的不是主圖最吸引我的那件，而是能和現有展示位置相處得最好、也最想回頭讀原作資料的那一件。"),
        new("REVIEW", "收藏心得", "CUSTOM", "作品卡很短，但剛好提醒我回到圖鑑繼續看", "收到商品時附的作品資訊沒有寫得很長，反而不會讓人以為一張卡片就能取代完整研究。名稱和來源提示已經足夠我找到對應圖鑑，想深入的部分再回到原始資料看，閱讀節奏很舒服。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我把縮小複製品當成提醒，不把它當成原作的替代品", "桌上的模型會讓我想起曾經看過的作品，但每次查資料時我仍然回到原作影像、尺寸和來源。對我來說它比較像一個閱讀提醒，提醒自己還有一件作品值得再看，而不是拿來代替博物館的觀看經驗。"),
        new("GENERAL", "家庭分享", "CUSTOM", "孩子問為什麼同一件作品在照片和模型上看起來不一樣", "孩子看到模型後問，為什麼照片裡的作品看起來比較大、顏色也不同。我們先把尺寸和拍攝角度放在一起比較，再說明模型是縮小展示品，這次對話讓我發現用具體例子解釋比直接講名詞容易很多。"),
        new("GENERAL", "家庭分享", "CUSTOM", "陪長輩看展時，我們從生活用途開始聊比較自然", "長輩不熟悉分類和年代，我沒有先講一串專有名詞，而是問他覺得這件東西拿起來、放在哪裡會怎樣。聊完生活感受後，再回到作品資料看尺寸和材質，對方反而主動問起來源。"),
        new("GENERAL", "朋友交流", "CUSTOM", "朋友說他只看得懂畫面，我請他先說自己看見的地方", "朋友常說自己不懂文物，我請他不要先想答案，只描述畫面裡最先看到的顏色、形狀和方向。等他說完，我們再一起看資料，原來不需要先懂所有名詞，也可以從觀察開始聊天。"),
        new("GUIDE", "看展路線", "CUSTOM", "人多的時候我會先看小展廳，再把主展區留到後面", "熱門展區人多時，我先去看旁邊的小展廳，讓自己有時間熟悉展覽主題。等人潮稍微散開再回主展區，視線比較不會一直被旁邊的走動打斷，也能把前面看到的內容拿來比較。"),
        new("GUIDE", "參觀規劃", "CUSTOM", "一天只安排兩個展區，反而有空間把筆記寫完整", "以前安排博物館行程會把展區排得很滿，回家才發現只剩一堆沒有標題的照片。最近一天只排兩個展區，留時間坐下整理名稱、位置和問題，隔天回想時清楚很多。"),
        new("GENERAL", "參觀心得", "CUSTOM", "同一趟旅行裡看了兩個館，我開始注意不同的說明方式", "旅行中連續走了兩個展館，發現同樣是介紹器物，一邊先講用途，一邊先講來源和製作。這個差異讓我回家整理資料時不再只找一種固定的閱讀順序，而是看自己當下想理解的是哪一層。"),
        new("REVIEW", "近看心得", "CUSTOM", "我在展櫃前退後又靠近，才知道自己原本站得太近", "站得太近時只看得到局部紋樣，退後後才看出整體輪廓，再靠近一點才補回表面細節。這個來回很簡單，卻讓我發現自己以前常用一個距離看完整件作品，難怪容易漏掉東西。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "活動中聽到的補充，我回家沒有直接當成最後定論", "導讀裡聽到一段很有趣的補充說法，我當下先記起來，回家後再和圖鑑與來源連結核對。最後有一部分找到支持，有一部分仍要等待更多資料；把兩者分開保存，日後回看才不會誤會。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我在遊戲裡最常犯的錯，是把相似名稱當成相同作品", "幾次回合後發現自己常因名稱很像就直接選答案，等揭曉才知道圖像和分類並不相同。現在看到熟悉字樣，反而會先核對編號與影像，這個習慣也慢慢帶回平常查圖鑑的時候。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動結束後大家交換筆記，才發現漏看的細節可以拼回來", "活動結束後我們沒有只拍合照，而是各自分享今天記下的細節。有人補上作品背面的觀察，有人記得講者提到的來源，合在一起後才形成比較完整的回顧，也讓我知道下次該把注意力放在哪裡。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "回家讀一年前的筆記，發現自己現在會先看以前忽略的欄位", "整理舊筆記時看到一年前的自己只寫了顏色和喜好，現在卻會先找尺寸、來源和觀看角度。作品沒有變，是我的閱讀方式變了；把這些差異留下來，對長期累積很有成就感。"),
        new("GUIDE", "照片整理", "CUSTOM", "我替每張參觀照片補上拍攝位置，回頭看時不再只剩一張漂亮圖片", "以前的照片只按日期存放，過一陣子就忘記它是哪個展廳、從哪個方向拍的。現在會補上展館、展區、角度和當時想查的問題，影像因此變成可以重新使用的參觀記錄。"),
        new("CATALOG", "同類比較", "CUSTOM", "把同類作品按尺寸排序後，原本模糊的差異變得容易說明", "我把幾件同類作品按照尺寸和器形排列，不再只依照名稱分組。這樣看才發現有些外觀相近的作品，比例其實差很多；排序不是為了決定哪件比較好，而是讓比較有一個清楚的起點。"),
        new("QUESTION", "開放提問", "CUSTOM", "我想請教大家，遇到兩種來源說法時通常會先保留哪一種", "整理一件作品時看到兩個來源對年代的說法不完全相同，我先把原文和查閱時間都留著，沒有自行選一個看起來順的版本。想請教大家遇到這種情況時，會先比較哪些條件，讓後續查證有可以延伸的方向。"),
        new("DISCOVERY", "保存狀態", "CUSTOM", "看不清楚的局部先不要猜，是我最近最需要提醒自己的事", "照片解析度不夠時，我以前會用相近作品的印象把空白補起來，結果越寫越肯定。最近改成直接標示看不清楚，並記下需要哪個角度或來源才能繼續，文字少一點卻更可靠。"),
        new("REVIEW", "觀看感受", "CUSTOM", "離開展廳後還記得的，通常不是我原本設定要看的作品", "這次展前列了幾件必看作品，結果離開後最常想起的是一件原本沒有做功課的小品。它讓我停下來的原因很難一句話說完，但也因此想把那個當下的感覺和後續查到的資料慢慢接起來。"),
        new("GENERAL", "收藏脈絡", "CUSTOM", "我把想買、想讀和想再看分成三張清單，決定事情清楚很多", "以前看到喜歡的作品就同時加入購物車和收藏清單，最後常忘記自己究竟想做什麼。現在分成想買、想深入閱讀、想再到現場看三類，過一段時間回來仍然知道每一筆清單的理由。"),
        new("GAME", "遊戲回顧", "CUSTOM", "遊戲中的錯誤答案，也可以變成下一次看展的提醒", "這次答錯不是因為完全沒看見線索，而是只記住其中一個，忽略了其他條件。回合結束後我把這個錯誤寫在參觀清單旁，下次遇到相近作品時提醒自己先做完整比較，而不是只找熟悉的地方。"),
        new("EVENTS", "活動交流", "TEMPLATE", "如果下次還有同主題活動，我會提早留下可以提問的地方", "活動中有幾個疑問當下沒想到，回家整理照片才浮現出來。下次參加同主題活動，我想在出發前先讀一點基本資料，並把想問的地方寫下來，現場比較能把握真正想請教的內容。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我沒有把這篇心得寫成答案，因為還有一段資料需要確認", "這次整理到一半已經可以寫出看似完整的結論，但其中一段來源仍然沒有核對清楚。我決定把確定的觀察先寫完，再明白標出待查的地方；保留空白比用漂亮句子掩蓋不足更適合長期記錄。"),
        new("GUIDE", "參觀規劃", "CUSTOM", "把交通、入口和想看的作品放在同一張行程表，實際走起來安心很多", "以前只記展館名稱，到了現場才開始找入口和展廳，時間常被消耗掉。現在會把交通方式、入口、開館時間和想看的作品一起寫進行程表，地圖負責確認方向，文字負責讓我到場後不慌張。"),
        new("REVIEW", "收藏心得", "CUSTOM", "小型複製品最適合放在我每天會讀資料的地方", "我試過把複製品收進櫃子，也試過放在客廳最顯眼的位置，最後覺得書桌旁最好。每天讀到相關資料時抬頭就能看到它，卻不會因為太醒目而把作品本身變成背景。"),
        new("CATALOG", "局部觀察", "CUSTOM", "把照片裁成局部前，我會先把完整構圖留一份", "整理局部細節時，裁切圖片很容易讓人忘記它原本在作品哪個位置。我現在一定先保存完整影像，再另存局部，並在檔名或筆記寫上方向；之後回看時才不會把細節和整體脈絡拆開。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "查到新資料時，我會把原本的理解留下來再補更新", "找到新來源後直接覆蓋舊筆記很方便，但也會失去自己當初怎麼理解的過程。最近會把原本的觀察保留，再加上查證日期和新的說明，未來回頭看時能知道是哪份資料改變了我的想法。"),
        new("QUESTION", "開放提問", "CUSTOM", "我想知道大家看待待測量資料時，會如何安排自己的比較方式", "遇到作品尺寸尚未測量時，我先用能取得的影像比例做初步觀察，卻不把它當成正式尺寸。想請教大家會用哪些同類作品或展場資訊來建立暫時的比較框架，才不會一開始就把尺度想錯。"),
        new("GENERAL", "朋友交流", "CUSTOM", "把參觀心得說給沒去過的人聽，才知道哪些背景真的需要補充", "我把今天的展覽心得講給沒去過的朋友聽，講到一半才發現自己一直使用只有現場看過才懂的指示。後來改成先說作品長什麼樣，再補展廳和來源，對方才真的能跟上我的描述。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "我現在先問自己想知道什麼，再決定要放大哪個欄位", "同一頁資料可以從很多方向閱讀，如果一開始沒有問題，常常只是在頁面上來回滑動。最近會先寫一句想知道的事，例如大小、來源或製作，再選對應影像和欄位，查找時間短很多。"),
        new("REVIEW", "觀看感受", "CUSTOM", "展場聲音和人流也會影響我對作品的第一印象", "今天展廳比較安靜，我發現自己能看得比平常慢；另一個熱門展區人流一直經過，注意力就容易被打斷。這不代表作品本身不同，但把環境寫進心得後，回頭看自己的感受比較有脈絡。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我喜歡活動先讓參加者觀察，再把背景資料放到後面", "這次活動的安排是先看作品、再聽背景，對我來說比一開始先講完整年代更容易記住。因為已經有自己的觀察，後面聽到資料時會知道它在回答哪一個疑問，不會只剩下一串名詞。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我把每回合的最早線索和最後答案分開記，才看得出判斷怎麼改變", "回合結束後只記正確答案，很快就會忘記自己一開始為什麼那樣猜。現在會留下最早看到的線索、改變判斷的原因和最後答案，幾次累積後，自己的推理習慣變得很清楚。"),
        new("GENERAL", "參觀心得", "CUSTOM", "同一件作品隔幾個月再看，注意到的地方真的會換", "幾個月前來看時，我只記得作品的色彩，這次重訪卻先注意到輪廓和底部。作品沒有改變，是我帶著不同問題回來，所以現在會在筆記上留下參觀日期，讓之後的差異有跡可循。"),
        new("CATALOG", "器形比較", "CUSTOM", "我用三個欄位比較作品，不再用一個很像就結束", "拿相近作品比較時，我固定先看器口、腹部和底足三個位置，再補材質與尺寸。這樣就算整體看起來很像，也能說明究竟是哪一段相同、哪一段不同，討論比較不會飄在印象上。"),
        new("DISCOVERY", "材質與工藝", "CUSTOM", "表面的光澤很吸引人，但我先把它當成需要確認的現象", "看到很亮的表面時，我以前會直接聯想到材質或製作方式，現在先寫成光澤明顯，再找不同光線和來源資料核對。把看到的現象和原因分開，反而更容易邀請別人補充。"),
        new("QUESTION", "資料判讀", "CUSTOM", "有一個用途想像很吸引我，但目前資料還不夠讓我寫死", "我對這件作品有一個很直覺的使用想像，尺寸和形狀也剛好能支持部分畫面，但仍然缺少來源證據。這篇先把想像寫清楚，再列出需要確認的欄位，避免把一個好故事誤當成歷史事實。"),
        new("REVIEW", "展陳想像", "CUSTOM", "如果只剩一分鐘，我會先看完整輪廓再選一個局部", "今天時間不夠，不能像平常一樣慢慢停留，我先從完整輪廓和作品名稱開始，再挑一個最想放大的局部。這個順序讓我至少保留整體印象，離開後也知道要從哪裡回查。"),
        new("GUIDE", "筆記方法", "CUSTOM", "我在筆記最後加一行下一步，重新打開時就不會從頭迷路", "整理完一件作品後，我會在最下面寫下一步要找的來源、影像或同類作品。過幾天重新打開時，不用先回想自己當初卡在哪裡，直接照著那一行繼續，長期累積輕鬆很多。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "今天最大的收穫，是終於知道自己還缺哪一份資料", "這次沒有找到一個漂亮的結論，但把問題拆開後，已經知道缺的是不同角度的影像和一段來源說明。以前會把這種結果當成沒有進展，現在覺得能清楚說出下一步，本身就是很實際的收穫。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我現在會把遊戲結果當成回到圖鑑的入口，而不是最後答案", "遊戲的結果很有趣，但真正讓我想繼續的是答案和自己理由之間的落差。回合結束後我會點回相關圖鑑，把哪些線索有支持、哪些只是猜測標出來，這樣每次遊玩都能留下可回看的東西。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動報名成功後，我會先把時間和到場方式寫進行事曆", "報名成功不代表到場就不會出錯，我會把活動開始、報到、交通和入口一起放進行事曆，也把活動頁的文字地址留著。地圖適合確認路線，文字則能在手機訊號不好時派上用場。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我沒有為了湊滿一格展示櫃而買第二件相似的複製品", "看到相近作品時很容易覺得放在一起會很好看，但我先問自己是否真的想讀它們的資料。最後保留空間，等下次參觀後有更明確的理由再決定，收藏慢一點反而比較不會後悔。"),
        new("GENERAL", "照片整理", "CUSTOM", "我把一張模糊照片留下來，但明確標示它不能拿來下結論", "有些照片不夠清楚，卻仍然能幫我回想當時站的位置，所以我沒有全部刪掉，只在筆記標示它只能作為參觀記憶，不能用來判斷細節。把影像用途寫清楚，比勉強把每張都當證據好。"),
        new("CATALOG", "尺寸比較", "CUSTOM", "尺寸不是冷冰冰的欄位，它會改變我對一件作品的想像", "以前讀尺寸只想快點跳過，這次把長寬高和展櫃距離放在一起看，才發現作品在空間中的存在感和我想的不一樣。數字沒有直接告訴我用途，但能讓想像先回到合理的尺度。"),
        new("DISCOVERY", "保存狀態", "CUSTOM", "我開始把保存造成的可能變化和原本工藝分開討論", "看見表面斑痕時，現在不會立刻把它算成製作痕跡，而是先列出保存、修復和拍攝條件幾種可能。這樣雖然文章少了一句斬釘截鐵的結論，但後續查證時保留的空間更大。"),
        new("QUESTION", "開放提問", "CUSTOM", "如果作品只有一個角度的圖，大家會先怎麼避免過度解讀", "手上的資料目前只有一張主要影像，我知道它不夠支撐完整判斷。想請教大家面對這種情況時，會先從名稱、尺寸、來源還是同類作品開始補資料；我先把自己的觀察限定在看得到的範圍。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "我把一篇長說明拆成名稱、觀察、來源和疑問四段來讀", "面對很長的作品說明時，我以前常讀到中間就忘記開頭。最近先分成名稱與基本資料、自己直接看見的內容、來源提供的內容，以及還想確認的疑問，讀完後比較能保留整體脈絡。"),
        new("REVIEW", "觀看感受", "CUSTOM", "不是每次看展都要拍照，有時候只坐著記一個視線落點", "今天沒有拍太多照片，只在休息時寫下自己看一件作品時視線先落在哪裡。少了整理大量影像的負擔，反而更能記住觀看速度和當時的情緒，回家再用圖鑑補資料就好。"),
        new("GENERAL", "參觀心得", "CUSTOM", "我把這次沒看懂的地方留在文章最後，當成下一次再訪的理由", "離開前還有一個局部看不清楚，我沒有硬湊出結論，而是把它寫在文章最後，連同下次想找的角度一起留下。這樣下次再到館裡，不會只重複走過，而是有一個明確的回來理由。"),
        new("GAME", "遊戲回顧", "CUSTOM", "遊戲裡答得快不一定代表看得完整，我這回合終於體會到", "這次很快送出答案，卻漏掉了題目裡一個限制條件。其他玩家花久一點整理線索，最後雖然沒有寫最華麗的故事，理由卻更完整。回顧後我決定把速度和完整度分開練，不再只追求第一個送出。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我會把活動中聽到的專有名詞回家換成自己的說法", "活動現場聽到不少專有名詞，當下覺得懂了，隔天卻只剩發音和零碎印象。現在會在回家後先用自己的話重述，再附回原本的詞和來源，真正理解的地方和還不懂的地方就會分得很清楚。"),
        new("CATALOG", "來源查證", "CUSTOM", "一個外部編號讓我找回原本以為遺失的參觀記錄", "整理舊照片時只記得作品名稱，搜尋結果很多，差點找不到是哪一件。後來用外部編號重新查，才把原圖和當天的展廳位置接回來。從那之後我會在參觀筆記裡同時留下名稱和編號。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "把一件作品介紹給別人前，我會先確認自己哪些地方其實不確定", "以前介紹作品時常把不確定的部分講得很順，聽的人也就以為那是已經證實的內容。現在會先標出自己的推測，再說明可以回查的資料，對話反而更容易延伸，也不會無意間把猜測傳下去。"),
        new("REVIEW", "收藏心得", "CUSTOM", "商品到手後的第一件事，是確認它對應的作品而不是找地方擺", "收到縮小複製品後，我先核對名稱、圖鑑連結和尺寸，再決定展示位置。這個順序讓我更清楚自己買的是一件和文物有關的展示品，不是買回來後才臨時想一個故事。"),
        new("GUIDE", "參觀規劃", "CUSTOM", "帶著一個具體問題去看展，比帶著一張長長的必看清單更有效", "這次只帶一個想確認的問題進展廳，其他作品遇到有興趣的再留下名稱。因為沒有一直趕著完成清單，反而有空間在某個細節前停久一點，離開後記得的內容也比較完整。"),
        new("QUESTION", "用途想像", "CUSTOM", "我能想像它怎麼被使用，但仍然想找更多資料確認", "從器形和尺寸看，我腦中很快浮現一個使用情境，不過這只是觀看後的想像。文章先把推測和能直接查到的資料分開，希望之後有人能補上同類作品或來源，讓這個問題往前走一點。"),
        new("DISCOVERY", "材質與工藝", "CUSTOM", "同一種材質在不同作品上呈現的表面感，不能用一句話概括", "比較幾件同類材質的作品後，我發現有的表面溫潤，有的反光明顯，不能只用一個形容詞說完。現在會把看到的差異寫在影像旁，再去找工藝和保存資料，不先替整個材質下總結。"),
        new("GENERAL", "朋友交流", "CUSTOM", "朋友的提問讓我重新看了一次自己以為熟悉的作品", "朋友問我一件熟悉作品的尺寸和來源，我原本以為可以直接回答，結果只記得名稱和大概年代。一起重新打開資料後，我才發現熟悉感不等於真的看過，這次也順手補了自己的筆記。"),
        new("CATALOG", "紋飾細節", "CUSTOM", "重複紋樣不只是裝飾，我開始注意它怎麼帶著視線走", "以前看到重複紋樣只會記得漂亮，這次沿著它的排列方向看，發現視線會被帶往器口和中心。這是我的觀看感受，不代表作品一定有同樣意圖，但把視線如何移動記下來，讓心得更具體。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動的集合說明越清楚，真正參加的人越能把注意力留給作品", "這次活動通知把時間、入口、報到方式和館區寫得很清楚，到了現場不用一直確認下一步，反而能專心聽導讀。對參加者來說，這些看似行政的細節其實直接影響整段參與經驗。"),
        new("GAME", "遊戲回顧", "CUSTOM", "這一回合我學到先讀完題目，再把自己喜歡的答案放到最後", "我常常先寫自己覺得最有趣的故事，之後才發現它沒有回應題目條件。這回合刻意先把題目讀完、列出限制，再把故事放進資料能支持的範圍裡，結果雖然慢一點，答案比較站得住腳。"),
        new("GUIDE", "照片整理", "CUSTOM", "我把來源和拍攝日期一起留著，日後才知道照片能用到什麼程度", "同一件作品的照片看起來很像，但不同日期和來源可能代表不同拍攝條件。現在整理時會保留來源、日期、角度和授權資訊，之後要分享或查證時，才不會只剩一張沒有背景的圖片。"),
        new("REVIEW", "展陳想像", "CUSTOM", "我喜歡展櫃裡留一個能讓人轉身看的角度", "看到一件作品時，我試著從正面、側面和稍微退後的位置各看一次，發現展櫃若只留正面視線，會錯過器形的厚度。這讓我開始注意展示安排如何影響觀眾實際能看到什麼。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "新的資料沒有推翻整篇筆記，只是把其中一段改得更精確", "找到補充來源後，原本的觀察大多仍然成立，只需要把年代範圍和措辭改得更精確。這次讓我覺得保留原始筆記很有用，更新不是把過去全部刪掉，而是讓理解逐步靠近資料。"),
        new("QUESTION", "同類比較", "CUSTOM", "看起來一樣的作品，應該從哪一個小差異開始比較", "我手上的兩件作品外觀很接近，目前只看出器口和底足有些不同，還說不清楚哪一項最有意義。想請教熟悉這類作品的人，通常會先從哪些穩定欄位開始，而不是只比較顏色。"),
        new("GENERAL", "參觀心得", "CUSTOM", "這趟行程沒有完成原本的清單，但留下了一篇真正想回看的筆記", "今天因為人潮和時間只看完一半清單，起初有點失望，整理後卻發現留下的那一篇筆記比以前完整很多。行程完成度不一定等於理解深度，這次算是重新調整自己的期待。"),
        new("CATALOG", "器底線索", "CUSTOM", "器底的款識讓我回頭重新看整件作品的時代背景", "我原本只注意器身，後來看到器底的款識，才回去把年代和來源資料重新讀一遍。款識本身不能單獨解決所有問題，但它提供了一個明確的回查入口，讓原本分散的資料接在一起。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我會把玩家的不同答案保存下來，因為理由本身也值得閱讀", "遊戲結束後最有趣的不只是正確與錯誤，而是不同玩家如何從同一張圖走出不同推理路線。把答案和投票結果一起留下，之後回看時能看到大家注意的線索，也比較容易設計下一次練習。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動現場有人補了一個我完全沒看到的觀察角度", "我一直從正面看作品，旁邊的參加者卻注意到側面和底部的關係。聽完他的說法後，我再回去看一次，才理解為什麼講者會把那個細節放在後半段說明。交流真的能補上個人視線的盲點。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "長文我會先讀標題和尺寸，再決定哪一段值得慢慢看", "作品說明很長時，我先確認名稱、基本尺寸和影像，再挑和目前問題有關的段落深入讀。這不是跳過資料，而是先建立一張小地圖，讀到細節時比較知道它在整件作品裡的位置。"),
        new("REVIEW", "收藏心得", "CUSTOM", "收藏不是把東西買回來就結束，我現在會替它安排一個可以延伸的問題", "每次新增一件展示品，我會順手寫下一個還想查的問題，例如作品比例、來源或同類比較。這樣收藏不會停在拆箱那一天，之後每次回到圖鑑，還有一個可以繼續閱讀的方向。"),
        new("DISCOVERY", "保存狀態", "CUSTOM", "同一張照片裡的顏色差異，我先確認是不是拍攝條件造成的", "看到畫面一側顏色比較深時，我沒有直接寫成作品的色彩變化，而是先比較照片的白平衡、反光和拍攝角度。這些條件不一定能立刻解釋全部差異，但至少能避免太快把影像效果當成原物特徵。"),
        new("QUESTION", "資料判讀", "CUSTOM", "我想知道大家會怎麼寫一段既保留個人感受又不過度推論的心得", "我很喜歡這件作品帶來的某種感覺，但不想把感受寫成作品一定要表達的意思。現在先描述自己在哪個視線落點產生這個感覺，再附上可以回查的資料，想看看大家還會如何處理這種界線。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "這次我先接受資料還不完整，文章反而比以前更容易讓人接著讀", "以前總想把每篇心得寫得像完成品，遇到缺資料就硬補幾句，讀起來雖然順卻不可靠。這次直接標出還缺的部分，反而讓人知道可以從哪裡接著查，也讓文章留下真正的討論空間。"),
        new("CATALOG", "尺寸比較", "CUSTOM", "尺寸資料和展廳距離放在一起，我終於理解為什麼現場看起來比照片小", "照片佔滿螢幕時，作品看起來常比實際大很多，回想現場距離才知道差異來自觀看尺度。這次把尺寸、展櫃高度和站立位置一起記，之後再看影像時比較不會被畫面比例帶走。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我會把遊戲中改答案的那一刻記下來，因為那裡最容易看見自己的偏見", "每次改答案時，我通常是被一個新線索吸引，卻很少記得原本為什麼選第一個。這回合把改答案的原因寫下來後，發現自己常在看到醒目顏色時過早轉向，這是比輸贏更值得練習的結果。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我希望下次活動還能留一點自由討論時間，不要每分鐘都排滿", "活動內容很豐富，但最後留給大家自由交換觀察的時間不多。對我來說，聽完正式說明後和其他參加者比較筆記很重要，希望下次行程能保留一點空白，讓問題有機會自然長出來。"),
        new("GUIDE", "參觀規劃", "CUSTOM", "我會在行程表上替每個展區留一個不一定要完成的彈性時段", "把所有展區都排成硬性目標，遇到人潮或臨時活動時就會很焦慮。現在每段行程只列一兩件核心作品，另外留一格彈性時間，看到值得停留的地方就停，不必一直趕下一站。"),
        new("REVIEW", "觀看感受", "CUSTOM", "這次最喜歡的是看見自己的第一印象如何慢慢改變", "第一次看到作品時我只記得顏色，讀完尺寸和來源後，視線開始轉向器形與使用痕跡。最後喜歡的原因和一開始不同，這個改變本身比立刻得到一個固定答案更值得留下。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我把查閱日期寫進筆記，避免幾個月後忘記自己看過哪個版本", "同一個來源過一陣子再打開，頁面內容或自己的理解可能都會變。現在會留下查閱日期、原始連結和當時摘記，日後發現不同說法時，才知道差異是資料更新還是自己記錯。"),
        new("QUESTION", "開放提問", "CUSTOM", "如果只能再補一項資料，我會先選另一個角度的影像，但想聽聽大家的順序", "目前這件作品有名稱、年代和正面影像，卻缺少能確認厚度的角度。我直覺會先找側面或背面照片，但也想知道大家會不會先查同類作品或製作來源，哪一條路通常比較有效。"),
        new("GENERAL", "收藏脈絡", "CUSTOM", "我把每次參觀的作品串成一條小路線，回頭看時比單張清單有感", "單獨看收藏清單時，只看到一串名稱；把同一趟參觀、延伸查到的作品和後來買的展示品串在一起，就能看見自己的興趣怎麼移動。這條小路線不一定有標準答案，但很像自己的學習地圖。"),
        new("CATALOG", "局部觀察", "CUSTOM", "我現在會先在完整圖上圈出局部，再放大，不讓細節脫離作品", "看到有趣的局部時，直接放大很容易忘記它原本的位置。這次先在完整影像上標出視線落點，再切換局部查看，回頭寫心得時能同時說明細節和它在整體構圖裡的關係。"),
        new("GAME", "遊戲回顧", "CUSTOM", "房間結束後看排行榜，我更在意每個人的回合表現而不只是名次", "最後名次很直觀，但我更想知道誰在哪一回合觀察得仔細、誰在時間壓力下仍然能寫出理由。把每回合的回答、票數和勝者留下來，下一次再玩時就有具體的進步可以比較。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動報到時如果有清楚的館區說明，第一次來的人會安心很多", "這次有人在入口附近找不到報到位置，大家花了一些時間互相確認。活動內容本身很精彩，但我也更確定集合地點、入口和報到方式應該寫得足夠清楚，第一次參加的人才能把心力放在活動上。"),
        new("GUIDE", "筆記方法", "CUSTOM", "我替自己的筆記保留一個不確定標記，回頭看時不會忘記哪些地方還沒核對", "以前筆記寫完看起來都很肯定，過幾天就忘記其中哪些其實只是當下猜測。現在會用簡單的待查標記和原因，等找到資料再補上日期，長期累積時比較不會把推測誤當成已確認內容。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我喜歡把展示品和自己的參觀照片放在一起，但不會把照片當成商品的裝飾背景", "把複製品和參觀照片放在同一格時，照片提醒我它對應哪次看展，展示品則讓我記得想再讀原作。兩者各自有用途，不必把照片裁成只剩漂亮背景，保留展廳脈絡反而更有記憶點。"),
        new("DISCOVERY", "材質與工藝", "CUSTOM", "越查資料越覺得一句材質描述需要很多條件一起支持", "我原本想用一個材質詞概括作品，查到工藝與保存資訊後才發現表面效果、製作方式和現況不能混成一件事。現在文章會先說看見什麼，再說資料支持到哪裡，讀起來比較踏實。"),
        new("QUESTION", "年代範圍", "CUSTOM", "朝代名稱很方便，但我不想讓它取代原本保留的年代範圍", "整理年代時，我會保留來源中的原始文字，再用比較容易閱讀的分類名稱輔助理解。分類方便搜尋，原文則保留精度；兩者一起看，比直接把一段範圍壓成單一年份更誠實。"),
        new("GENERAL", "參觀心得", "CUSTOM", "離館前我會回到今天最想再看一次的作品，不一定是最有名的那件", "離開前回頭走一小段，找今天最想再看一次的作品，常常不是原本最期待的名品。第二次看時會帶著剛才其他展區的印象，往往能注意到第一次沒有發現的關係。"),
        new("CATALOG", "來源查證", "CUSTOM", "我終於把外部資料的名稱和平台裡的作品名稱分開記了", "以前整理來源時會把不同系統的名稱混在同一行，過一陣子就不知道哪個是原始名稱、哪個是平台標題。現在分開記錄，再用作品編號連起來，搜尋和後續修正都清楚很多。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望遊戲結束後能看到自己的回合歷程，因為那比一句總分更有用", "這次玩完只記得最後結果，卻想不起自己在哪一回合看錯線索。如果能保留每回合的回答、票數、勝者和自己改變判斷的時間，玩家就能從結果回到練習，而不只是看完名次離開。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動結束後把社群貼文和活動資料放在一起看，回顧會完整很多", "現場聽到的內容、自己拍的照片和活動頁的時間地點各自放著，很容易只剩零碎印象。若能從社群貼文回到活動資料，再把自己的心得接在同一個脈絡裡，之後想重溫會方便很多。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "我把一頁資料讀完後會用一句話說明自己真正記住了什麼", "讀很多資料不代表真的留下理解，所以現在會在最後用自己的話寫一句摘要，再檢查這句是否能回到原始欄位。若寫不出來，就表示我可能只看過文字，還沒有真正掌握它的關係。"),
        new("REVIEW", "觀看感受", "CUSTOM", "一件作品不需要一次看完，我現在比較願意把問題帶回家", "以前離開展廳前總想把每個疑問解決，後來發現很多問題需要來源或其他作品才能回答。現在會把問題好好記下來帶回家，下一次再訪時，反而能看見自己理解過程中的變化。"),
        new("DISCOVERY", "保存狀態", "CUSTOM", "我把照片裡的刮痕先寫成現象，不先替它找一個很確定的原因", "看到表面像刮痕的線條時，我先記錄位置、方向和影像條件，沒有立刻寫成修復或製作痕跡。這樣看似少了一個答案，卻讓後來找到的保存資料可以真正補進來，而不是被原本的猜測綁住。"),
        new("QUESTION", "資料判讀", "CUSTOM", "我想請教大家，介紹一件不熟悉的作品時會先說哪個細節", "如果要把一件不熟悉的作品介紹給朋友，我在名稱、外形、尺寸和一段背景之間猶豫很久。自己最後會先從一個看得見的細節開始，再補資料，但想聽聽大家怎麼讓第一次接觸的人容易進入。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我把自己的推測留在文章裡，但明確寫出它只是目前的想法", "有些推測其實很有趣，全部刪掉又會失去討論的起點，所以我沒有藏起來，只在句子裡明確說這是目前的想法，並附上支持和不足的地方。這樣別人可以回應推理，也不會誤讀成正式結論。"),
        new("CATALOG", "紋飾細節", "CUSTOM", "紋樣從中心往外看和從邊緣往內看，注意到的節奏完全不同", "我先從中心看向邊緣，再換成從邊緣往中心看，兩次注意到的重複單位不一樣。這是很主觀的觀看練習，但把視線路線寫下來後，別人也能知道我為什麼會把某一段當成重點。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我把遊戲裡的錯誤理由寫完整，下一次才知道要改哪個習慣", "只寫答錯不會告訴我問題在哪裡，這次把當下依據、忽略的線索和揭曉後的差異都補上。原來我不是不會看，而是常在第一個熟悉線索出現時就停止比較，這是很具體的練習方向。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我希望活動資訊除了地圖，也能保留讓人照著走的文字步驟", "地圖很適合看館區和路線，但第一次到陌生地方時，我還是需要入口、樓層、集合點和報到方式的文字說明。兩者一起提供，才能同時照顧喜歡看地圖的人和需要清楚步驟的人。"),
        new("GUIDE", "照片整理", "CUSTOM", "我分享照片前會先確認授權與來源，因為漂亮不代表可以直接使用", "參觀照片整理好後很想直接分享，但我會先確認影像來源、授權和是否需要標示。若只是自己的現場照片，也會把拍攝條件寫清楚；這些步驟不會讓分享失去趣味，反而讓別人更放心引用。"),
        new("REVIEW", "收藏心得", "CUSTOM", "有一件作品我最後沒有買，因為我想先把原作資料看熟", "看到喜歡的縮小複製品時很容易馬上下單，但這次先把它加入稍後決定的清單，回到圖鑑多看幾次。過一陣子仍然想收藏才真的購買，這樣比較能確定自己喜歡的是作品，而不是一時的畫面。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "查證不是找一句最順的說明，而是把不同版本放在一起看", "整理來源時最容易只挑讀起來最順的一句，這次刻意把不同版本並列，標出相同和不同的地方。雖然文章變長了，但也更能看出哪些內容穩定、哪些仍然需要保留範圍。"),
        new("QUESTION", "同類比較", "CUSTOM", "我想再找一件尺寸接近的作品，看看現在的比例判斷是否站得住腳", "目前對一件作品的尺寸感受，可能只是因為我常看的參照物不同。下一步想找一件尺寸接近、但器形不同的作品比較，確認自己描述比例時是否真的抓到重點，而不是只用了好聽的形容詞。"),
        new("GENERAL", "收藏脈絡", "CUSTOM", "我開始接受收藏清單裡有些作品只想讀，不一定要擁有", "以前把收藏和購買混在一起，看到喜歡的作品就覺得應該帶回家。現在也會把只想深入閱讀、只想現場再看一次的作品放進清單，興趣不一定要用購買來證明，脈絡反而更清楚。"),
        new("CATALOG", "器形比較", "CUSTOM", "我用同一個觀看順序比較不同材質，才發現自己容易被色彩先帶走", "比較不同材質的作品時，我刻意固定先看輪廓、再看尺寸和底部，最後才看顏色。這樣做讓我發現自己平常很容易被顏色帶走，固定順序不是規定答案，而是幫我把注意力拉回作品整體。"),
        new("GAME", "遊戲回顧", "CUSTOM", "如果能看到長期統計，我最想知道自己在哪種線索上反覆失分", "比起只看總分，我更想知道自己長期在哪些題型上容易失分，例如尺寸、來源或器底。把每回合結果累積成可回看的歷程，玩家才知道要練習哪個觀察，而不是只在下一場重複同一個錯誤。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我把活動現場的問題寫成貼文，讓沒到場的人也能接著討論", "活動中有些問題來不及問完，我回家把自己的觀察和問題整理成一篇分享，沒有假裝它是完整摘要。沒到場的朋友可以從作品資料開始補充，現場參加者也能回來接著說明，交流就不會在散場時中斷。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "我會先決定今天要留下哪一種記錄，避免照片、心得和來源全部混成一團", "有時候是參觀日記，有時候是來源查證，有時候只是想留下自己的一個問題。先決定這篇要保存什麼，再選照片和欄位，寫出來的內容會比把所有東西都塞在一起更容易回看。"),
        new("REVIEW", "觀看感受", "CUSTOM", "我喜歡作品前方有足夠空間，讓人可以自然地改變觀看距離", "展櫃前太擠時，很難退後看完整輪廓，也不容易換到側面。這次遇到一件前方空間較大的展示，能自然地靠近、退後和轉身，才明白觀看距離不是抽象的建議，而是場地直接提供的可能。"),
        new("DISCOVERY", "材質與工藝", "CUSTOM", "我把反光、顏色和紋理分成三個觀察，不再用一個詞一起帶過", "表面看起來很有光澤時，我先分別記錄亮度、色彩和能否看見紋理，再去找工藝資料。拆開之後才發現，有些原本以為的材質差異其實只是光線，描述也因此更準確。"),
        new("QUESTION", "資料判讀", "CUSTOM", "目前我只能確認作品的外觀，關於用途的部分想先聽聽不同看法", "這件作品的形狀和尺寸可以直接從資料確認，但用途仍然有幾種可能。我先不把其中一種寫成答案，想聽聽大家會如何區分觀察、類比和推測，也希望有人能提供可以回查的來源。"),
        new("GENERAL", "參觀心得", "CUSTOM", "今天的展覽筆記很短，但每一句都知道自己是在哪裡看到的", "這次沒有追求寫很多，而是每一段都補上展館、展廳或觀看方向。文字雖然短，隔一段時間回來看仍然能重建當時的脈絡，這比一篇很長卻沒有位置資訊的心得更有用。"),
        new("CATALOG", "來源查證", "CUSTOM", "我把作品名稱、平台編號和外部編號各自留著，搜尋時終於不會互相打架", "資料一多就容易把不同系統的識別資訊混成一個名稱，這次重新整理後，每個編號都保留自己的用途，再用關聯把它們接起來。看起來欄位變多，其實查找和後續更新都更容易。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望下一次遊戲能讓玩家在揭曉後直接回到對應的作品資料", "最有價值的時刻常常是揭曉之後，因為那時候大家最想知道自己漏掉了哪個線索。如果能從回合結果直接回到對應圖鑑，玩家就能把一次遊玩接成一次短小的閱讀，而不是看完答案就結束。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我把活動心得分成現場感受和資料回查兩段，讀起來不會互相搶位置", "現場的聲音、人流和第一印象很真實，但它們和回家查到的資料用途不同。這次把兩段分開寫，讀者可以先感受參與過程，再看哪些地方有來源支持，不會把心得和正式說明混在一起。"),
        new("GUIDE", "整理方法", "CUSTOM", "我在文章裡把已確認、正在查和只是想像的句子分開", "這種分段讓文章看起來沒有那麼像一個完成答案，但回頭看時非常清楚。已確認的內容可以直接引用，正在查的內容可以繼續補，純粹的想像則保留成討論起點，三者不會互相覆蓋。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我會先確認展示品有沒有和圖鑑資料連起來，再決定是否分享開箱照片", "開箱照很容易只剩包裝和外觀，我會先補上對應作品的名稱、來源和尺寸，讓照片有閱讀脈絡。這樣分享的不只是收到商品的興奮，也能讓看到的人知道它和哪件文物有關。"),
        new("DISCOVERY", "保存狀態", "CUSTOM", "同一個局部如果只在一張照片裡出現，我會把判斷寫得更保留", "單張照片裡的細節可能受角度、反光和解析度影響，所以我現在會根據影像數量調整語氣。兩三個角度都看得到的現象可以寫得清楚，只有一張圖支持的部分就留下待查標記。"),
        new("QUESTION", "開放提問", "CUSTOM", "我想知道大家會如何把看展時的直覺轉成可以被別人理解的文字", "當下的直覺很快，但直接寫成文章常常只剩我自己懂。這次試著補上視線從哪裡開始、看到了什麼、哪些資料改變了想法，文字變長一點，別人才有機會沿著同一條路理解。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我終於把一個大問題拆成三個小問題，查資料時沒有那麼挫折", "原本想弄懂一件作品的全部背景，查到後面只覺得越來越亂。後來拆成名稱來源、器形比較和觀看感受三個問題，每次只處理一個，資料雖然沒有變少，閱讀卻變得可以持續。"),
        new("CATALOG", "器底線索", "CUSTOM", "底足的形狀讓我重新想像作品在平面上如何被安放", "我以前只把底足當成作品的支撐，這次觀察它和器身的接合後，開始注意作品如何穩定地放在平面上。這只是從形狀出發的理解，不直接等於用途，但讓我更願意把底部放進比較。"),
        new("GAME", "遊戲回顧", "CUSTOM", "每個玩家都看見不同線索，這正是遊戲最適合留下的部分", "這場遊戲結束後，我記得的不是哪個人最快，而是大家從不同位置開始推理。有人的理由很像展場筆記，有人先提出假設再找支持；把這些過程留下，下一次回看會比單一正解更有學習價值。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動資訊寫清楚參加方式後，社群分享才能真正幫到想參加的人", "我看到有人在貼文裡分享活動很有趣，卻找不到集合時間和報名方式。後來把活動資料和社群貼文一起看，才發現心得適合分享感受，時間、名額和參加條件仍要回到活動本身確認，兩邊各自清楚最好。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "我把每次查證只設定成一個可完成的小步驟，慢慢累積比一次查完有效", "面對資料很多的作品，我會先選一個今天能完成的動作，例如確認編號、找到側面影像或讀完一個來源。完成後再決定下一步，這樣不會因為想一次弄懂所有背景而停在原地。"),
        new("REVIEW", "觀看感受", "CUSTOM", "我把今天的喜歡寫成一個具體畫面，而不是只留一句很好看", "回家後試著回答自己到底喜歡哪裡，才想起是站在斜前方時看見的一段輪廓轉折。把感受放回具體畫面裡，之後再看資料時比較能理解自己為什麼會被它吸引。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我保留原始資料的語氣，再另外寫一段給一般讀者看的摘要", "原始說明有自己的精度和限制，直接改寫成很順的白話容易把細節弄丟。現在會先保留原文重點，再另寫一段容易閱讀的摘要，兩段並列，既照顧理解也保留回查線索。"),
        new("QUESTION", "年代範圍", "CUSTOM", "我想知道大家會怎麼向新手解釋年代範圍，而不把它講成一個精確年份", "面對有範圍的年代資料，我會先說明原本的區間，再用朝代或時期名稱幫忙定位，不直接改成一個看似精確的年份。這樣新手比較容易理解資料的不確定性，也不會誤以為所有作品都能精確到某一年。"),
        new("GENERAL", "參觀心得", "CUSTOM", "今天我刻意沒有查手機，先用自己的眼睛看完一件作品", "平常遇到不熟的作品會立刻搜尋，今天先把手機收起來，只記下眼前看到的輪廓、光線和位置，離開展櫃後才查資料。先有自己的觀察再讀答案，回頭看時更能分辨哪些想法是資料帶來的。"),
        new("CATALOG", "局部觀察", "CUSTOM", "一個局部只有放回完整構圖，才知道它到底是不是重要線索", "放大某段紋樣時覺得它非常醒目，縮回完整圖後才發現它其實位在邊緣，不一定是作品的主要焦點。這次提醒我，局部的清楚不代表它在整體裡的意義就能直接被決定。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我開始把排行榜當成自己的長期練習紀錄，而不是只看一次輸贏", "幾場遊戲累積後，單場名次的情緒很快就過去，真正有用的是看自己在哪些回合答得穩、哪些題型容易急。若能保留完整房間歷程和每回合分數，玩家會更容易看見長期變化。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我喜歡活動結束後還有一個可以繼續提問的地方", "現場時間有限，不可能每個問題都得到答案；如果活動結束後能回到同一個貼文脈絡繼續討論，參加者可以補筆記，沒到場的人也能從資料開始加入。這樣活動的價值不會只停在當天。"),
        new("GUIDE", "整理方法", "CUSTOM", "我把每篇心得的最後一段留給下一次的自己，而不是硬寫一個收尾", "文章最後不一定要下結論，有時候留下下一次要查的來源、想再看的角度或想問的人，反而更符合實際的閱讀過程。過一陣子再回來時，那一段就會變成接續探索的入口。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我現在會把展示位置當成收藏的一部分一起思考", "同一件小複製品放在不同高度、背景和光線下，觀看感覺差很多，所以買之前會先想它要和哪些書或照片放在一起。展示位置不是買完才處理的附帶問題，而是整體收藏經驗的一部分。"),
        new("DISCOVERY", "材質與工藝", "CUSTOM", "我把材質觀察寫成可能性，不讓照片看起來比資料更有說服力", "影像有時很容易讓人覺得自己已經知道材質，但照片只提供一個觀看條件。現在會寫明看到的表面效果，再列出仍需工藝資料確認的可能性，這樣文章不會被漂亮影像推著走。"),
        new("QUESTION", "同類比較", "CUSTOM", "我想和大家比較兩件作品，但先把自己的比較條件說清楚", "如果只說兩件作品很像，別人很難知道我看到的是哪裡。所以這次先說明我比較的是器口比例、底足和表面處理，再附上兩件作品的資料；即使大家不同意，也能從同一組條件開始討論。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "把一件作品讀懂一點點，也足夠成為今天的進度", "有些日子只能讀完名稱、尺寸和一段說明，沒有時間繼續查來源。以前會覺得這樣不算進度，現在把能確認的內容和下一步留下，隔天再接著讀，反而比較能長期維持。"),
        new("CATALOG", "觀看順序", "CUSTOM", "我把先看整體、再看局部寫成自己的習慣，但遇到畫作時會調整", "器物和畫作的觀看順序不一定相同，這次先用整體輪廓建立方向，再挑局部；面對畫面則會讓視線在整體和細節之間來回。固定原則可以幫忙開始，但作品不同時仍要留調整空間。"),
        new("GAME", "遊戲回顧", "CUSTOM", "如果玩家能標記自己不確定的線索，回合回顧應該會更有幫助", "遊戲時常常知道某個地方可疑，卻來不及寫完整答案。若能把不確定的線索先標記，揭曉後再回看哪些標記真的有用，玩家會更容易認識自己的直覺，而不是只記住最後的對錯。"),
        new("EVENTS", "活動交流", "TEMPLATE", "這次活動讓我知道正式解說和會員心得可以各自保留自己的位置", "講者的說明有來源和脈絡，會員的心得則有現場感和疑問，兩種內容放在一起很豐富，但不需要互相假裝成同一種文字。活動貼文提供入口，個人分享留下經驗，讀者可以依需要往下看。"),
        new("GUIDE", "參觀規劃", "CUSTOM", "我會先確認展館是否有南北院區，再安排交通和停留時間", "之前只記得館名，差點把正館和南院的行程排在同一個下午。現在看到活動或展覽資訊會先確認實際館區，再查入口、交通和停留時間；地點寫清楚，行程才不會只停在想像。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我沒有把所有喜歡的作品都買成複製品，留一些只在圖鑑裡追蹤也很好", "收藏清單裡有些作品，我更喜歡透過資料和參觀記錄持續追蹤，未必需要有一件實體展示品。把想讀、想看和想買分開後，反而更能確定每一件收藏對自己的意義。"),
        new("DISCOVERY", "保存狀態", "CUSTOM", "回家照片和現場印象不同時，我會先相信條件不同，而不是急著選一個是真的", "照片裡的顏色和現場記憶有落差，我現在不會立刻決定哪一個才是原貌，而是先記下光線、距離和設備。承認兩種感受都受到條件影響，後續查證反而比較有方向。"),
        new("QUESTION", "開放提問", "CUSTOM", "大家會怎麼邀請別人補充資料，又不讓問題看起來像在考對方", "我想請教某件作品的來源，但又不希望貼文變成只有懂的人才能回答的考題。現在會先說自己已經查到什麼、卡在哪裡，再請大家分享可回查的資料或觀看角度，交流會比較自然。"),
        new("GENERAL", "參觀心得", "CUSTOM", "我把今天的行程寫成一段故事，回頭看時比單純的時間表更能想起現場", "時間表能告訴我幾點到館，卻不一定能想起為什麼在某個展櫃停下。這次把行走、停留、看到的細節和回家後的疑問寫在一起，日後再讀時，整趟參觀比較像真的重新走過一次。"),
        new("CATALOG", "器底線索", "CUSTOM", "我現在把底部和背面列成必看，不再因為它們不在主視覺就跳過", "作品的正面最容易吸引人，但底部、背面和接地處常常提供不同線索。這次刻意把它們放進自己的閱讀順序，雖然不是每次都能看清楚，至少不會在一開始就把重要角度排除。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望遊戲的回合結果能讓玩家知道自己是靠哪一種線索得分", "同樣拿到一票，可能是因為看對器形，也可能只是答案寫得很有趣。若回合結果能同時保存回答、票數和對應作品資料，玩家就能回頭理解得分來自哪裡，練習也會更有方向。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動貼文如果能連回正式活動資料，大家比較不會把心得裡的時間當成報名資訊", "分享活動心得時常會提到自己的到場時間，但那不一定是正式開始或報名截止。把貼文和活動資料連起來，讀者可以看心得，也能回到活動頁確認時間、地點和名額，資訊各自有清楚來源。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "我現在會把一篇文章的主題寫清楚，避免看到後面才發現其實在談另一件事", "寫心得時如果同時談展場、人流、作品和商品，很容易讓讀者找不到主線。現在會先選一個主要主題，其餘內容只在真的能幫助理解時補上，文章比較集中，也方便日後搜尋。"),
        new("REVIEW", "觀看感受", "CUSTOM", "我很喜歡有些作品需要繞到側面才看得懂，觀看本身就像一段小路程", "有件作品正面看起來很平靜，繞到側面後才發現厚度和輪廓改變了整體感覺。這次讓我明白，作品不是一張固定圖片，觀眾移動的路線也會成為理解的一部分。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我把自己的說法和來源原文並排，才看見自己偷偷加了哪些意思", "重新對照原文時，發現自己為了讓句子順暢，無意間補進了來源沒有說的因果。現在會把原文重點和自己的改寫並列，逐句檢查哪些是忠實轉述、哪些是自己的理解。"),
        new("QUESTION", "資料判讀", "CUSTOM", "我想知道大家怎麼面對資料中沒有說明、但畫面很容易讓人聯想到的部分", "有些畫面很容易讓人補出一個故事，可是資料沒有提供那樣的說明。我目前會把聯想到的內容放在個人感受，不寫成作品背景，想聽聽大家在觀察和想像之間會怎麼拿捏。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "今天沒有找到新資料，但我把舊資料讀出了不同的順序", "同一段說明以前看過幾次，今天因為先有一個關於尺寸的問題，讀起來突然注意到以前忽略的句子。資料沒有增加，問題改變後閱讀方式就變了，這也是重新回看的意義。"),
        new("CATALOG", "同類比較", "CUSTOM", "我先把比較條件寫出來，才沒有把兩件作品的好惡混成差異", "比較作品時很容易把我比較喜歡的那件寫得好像所有欄位都更好。這次先列出形制、尺寸和表面三個客觀比較方向，再另外寫個人偏好，讀者比較能分辨資料和品味。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我喜歡回合結束後看大家的理由，因為那裡有比正解更豐富的閱讀線索", "正解能告訴我答案，但不同回答的理由會顯示玩家如何理解提示。有些人從作品資料出發，有些人從生活經驗類比，回合歷程若能完整保留，之後再讀仍然像一場小型討論。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動前先讀一點圖鑑資料，現場聽解說時真的比較能抓到重點", "以前參加活動都是到現場才第一次看到作品，這次出發前先看了基本影像和尺寸。講者提到細節時，我已經知道它在作品哪裡，理解比以前深，也更知道自己還想問什麼。"),
        new("GUIDE", "照片整理", "CUSTOM", "我會替分享照片寫能讓別人理解的替代文字，不只寫漂亮或好看", "照片如果沒有說明，視力不同或沒有到過現場的人很難知道我想分享什麼。現在會寫下作品、角度、主要可見細節和影像限制，文字和圖片一起提供，分享才比較完整。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我把商品評價寫成收到後真的觀察到的事情，不只留下好看或喜歡", "收到縮小複製品後，我會記錄尺寸是否符合、從哪個角度最容易看見輪廓，以及它如何連回原作資料。這些具體感受比一句好看更能幫助下一位收藏者判斷是否適合自己。"),
        new("DISCOVERY", "材質與工藝", "CUSTOM", "我越來越能接受一句話只描述看見的效果，不急著解釋背後原因", "看到表面粗細或顏色變化時，先把現象說清楚已經很有價值，不必每次都立刻替它找到工藝原因。保留這個分寸後，文章比較不會過度解釋，也更容易等到可靠資料補上。"),
        new("QUESTION", "開放提問", "CUSTOM", "如果有人有不同角度的照片，希望也能一起說明拍攝條件", "不同角度的照片很有幫助，但如果不知道光線、距離和來源，也可能讓差異看起來比實際更大。若要補圖，我會一起寫下拍攝條件，大家比較能判斷哪些是作品、哪些是影像造成的效果。"),
        new("GENERAL", "參觀心得", "CUSTOM", "我現在比較少追求一次看很多件，而是讓一件作品留下幾個可以再回來的入口", "一趟看展如果帶走很多名稱，回家不一定記得其中內容。這次只挑幾件作品留下影像、尺寸、來源和一個疑問，之後每次回來都能從不同入口接著讀，記憶反而更牢。"),
        new("CATALOG", "觀看順序", "CUSTOM", "我把先看完整影像的習慣帶到手機上，避免一打開就只看縮圖", "手機畫面小，很容易只掃過縮圖和標題就往下滑。現在會先打開完整影像，再看基本資料，最後才決定是否放大局部；小螢幕上的閱讀順序改變後，漏掉的細節少很多。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我想把每次遊玩的進步寫成一句話，讓長期紀錄不只剩下分數", "這次雖然沒有拿到最高分，但我第一次在時間內把尺寸和來源一起列入判斷。這種進步不一定會立刻反映在排名上，所以我想在每次遊戲後補一句自己的學習紀錄，過一段時間再回頭看。"),
        new("EVENTS", "活動交流", "TEMPLATE", "如果活動有正式的官方公告，社群心得就能把重點留給實際參與經驗", "活動時間、場地和報名規則適合由正式活動資料清楚維護，會員分享則可以留下交通感受、觀看順序和現場問題。兩者接在一起，讀者既找得到準確資訊，也看得到真正參加後的樣子。"),
        new("GUIDE", "整理方法", "CUSTOM", "我不再把文章寫成像說明書，而是先說這次真的看到了什麼", "以前為了讓文章完整，常常把內容寫成一步一步的功能介紹，讀起來不像社群分享。現在先從實際參觀、查資料或遊戲中的一個片段開始，再補需要的背景，文字比較像真的人在交流。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我很在意商品和原作之間能不能清楚對上，這比包裝多一層裝飾更重要", "對我來說，縮小複製品最重要的是名稱、尺寸和對應作品清楚，收到後能順利回到圖鑑繼續讀。包裝漂亮當然加分，但如果關聯資料不明確，再精緻也很難成為長期收藏。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我會把查不到的內容直接寫成查不到，不用猜一個看似完整的版本", "有些欄位目前沒有足夠資料，我以前會想找一個相近答案填上，讓文章看起來完整。現在直接寫明查不到、可能需要哪類來源，雖然少了一點裝飾，卻讓後續補充有明確位置。"),
        new("QUESTION", "用途想像", "CUSTOM", "我想把一個用途問題留給熟悉這類作品的人，而不是自己先替它定案", "從形狀看，我有一個用途猜想，但也知道相似的外觀可能有不同使用方式。文章先寫自己看到的依據和不確定性，希望熟悉這類作品的人能分享比較方向，讓討論從資料開始而不是從爭論開始。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "回頭整理這批文章時，我希望每一篇都有一個真實的出發點", "有些分享從參觀開始，有些從遊戲中的錯誤開始，也有些是收到展示品後才回到圖鑑。出發點不同，文章自然會有不同節奏；對我來說，這比每篇都寫成同一種漂亮格式更像真的社群。"),
        new("CATALOG", "紋飾細節", "CUSTOM", "我把紋飾的重複、間距和轉角分開看，才不會只留下顏色印象", "同一段紋樣裡，重複單位、間距和轉角的變化其實不同。以前只記得整體色彩，這次把三個觀察分開寫，再回頭看完整構圖，才真的說得出它為什麼有節奏。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望遊戲的結果頁能同時照顧想看排名和想檢查推理的人", "有些人想知道誰拿到最高票，有些人更想看自己在哪回合漏線索。結果頁如果同時提供房間總覽、每回合勝者、回答票數和玩家長期排名，遊戲就能兼顧競賽和學習兩種需要。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動參加過程中的小問題，也值得被記錄下來讓下一次更順", "集合時找入口、報到時不知道要去哪裡、展廳裡是否能拍照，這些不一定是活動主題，卻會直接影響參與感。把它們整理成心得分享，下一次參加者就能少走一點冤枉路。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "我現在會先決定文章是寫給正在參觀的人，還是寫給之後想查資料的自己", "同一段經驗，寫給現場準備出發的人會強調路線和時間，寫給未來的自己則會保留來源、影像和問題。先想清楚讀者，文章就不會同時塞進互相衝突的細節。"),
        new("REVIEW", "收藏心得", "CUSTOM", "一件小複製品讓我重新打開一篇很久沒讀的文物資料", "桌上看到它時突然想起原作的名稱，順手打開圖鑑才發現上次只讀到一半。展示品沒有替我完成閱讀，卻成了一個很自然的提醒，讓一份快被遺忘的資料重新回到日常裡。"),
        new("DISCOVERY", "保存狀態", "CUSTOM", "我把一個看起來像裂痕的地方交叉看了三張影像，結論反而變得比較保留", "三張影像的光線不同，那段線條有時明顯、有時幾乎看不見。我最後沒有寫成確定裂痕，而是記錄它在影像中的出現條件，等待更可靠的保存說明，這樣比較對作品負責。"),
        new("QUESTION", "資料判讀", "CUSTOM", "我想知道大家如何判斷一段說明是作品資料，還是後來整理者的推論", "讀資料時有些句子寫得很肯定，但我還不清楚它來自原始記錄、研究整理，還是後來的推測。現在會先找來源層級和原文，再把自己的理解分開，希望能和大家交換更好的判讀方法。"),
        new("GENERAL", "參觀心得", "CUSTOM", "今天離開博物館時，我記住的是自己的觀看順序而不是展覽件數", "回家後發現自己其實沒有看很多件，但能清楚說出先看哪裡、哪一段回頭看了兩次，以及哪個疑問帶回家。這種順序感比一張長長的參觀清單更像真正屬於自己的經驗。"),
        new("CATALOG", "尺寸比較", "CUSTOM", "我把小尺寸作品和展示櫃高度一起看，才知道觀看距離會放大比例感", "小件作品放在太低的位置時，視線會一直落在上緣；換到較適合的高度，器形比例才完整出現。尺寸資料和展示條件放在一起，讓我明白同一件作品的觀看感受不只由數字決定。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我把遊戲中的答案分成故事、推測和資料判斷，回看時容易比較", "同一回合裡，有人用創意故事回應，有人提出合理推測，也有人努力從資料找證據。把回答類型和票數一起看，可以理解大家是在不同規則下表現，不會只用一種標準衡量所有人。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動心得最有價值的時候，是它讓下一個人知道該怎麼準備", "我不只想寫活動很精彩，也會記下出發前先看什麼、到場後從哪裡報到，以及哪些地方值得預留時間。這些內容能幫助下一個人真正參加，而不是看完心得後仍不知道如何開始。"),
        new("GUIDE", "整理方法", "CUSTOM", "我會把一篇分享的核心放在一個經驗，其他資料只用來讓它站得住腳", "文章如果同時想講完作品背景、商城、活動和遊戲，很快就會失去重點。現在先選一個真正發生的經驗，再用關聯資料支持它，讀者比較能感受到這篇分享到底想留下什麼。"),
        new("REVIEW", "觀看感受", "CUSTOM", "我喜歡作品資料能讓人回到現場感，但不會假裝文字能取代現場", "圖鑑中的影像和尺寸能幫我回想作品，卻不能完全取代展廳裡的距離、光線和人流。把兩者的差異寫出來，反而讓資料和參觀各自保有價值，不會互相誇大。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我在文章中留了查閱連結，因為自己的摘要不應該成為唯一來源", "整理後的摘要比較好讀，但它畢竟是我的理解，不能取代原始資料。這次把查閱連結和原始名稱一起留在文章脈絡裡，讀者可以先看我的觀察，再自行回查需要的部分。"),
        new("QUESTION", "開放提問", "CUSTOM", "我想把這件作品的疑問留在社群裡，等有人從另一個角度補上資料", "目前我能確認的只有影像、名稱和部分尺寸，其他解釋都還太早。把問題放到社群後，希望有人能從不同館藏、工藝或來源資料提供線索；就算沒有立刻答案，也能先累積比較方向。"),
        new("GENERAL", "收藏脈絡", "CUSTOM", "我現在會回頭整理自己為什麼喜歡一件作品，而不只記得什麼時候買了它", "訂單只能記錄購買時間，卻不會告訴我當初為什麼被作品吸引。這次把參觀照片、閱讀筆記和展示品放在一起，才補回那個起點；收藏對我來說也因此多了一段可回看的故事。"),
        new("CATALOG", "閱讀心得", "CUSTOM", "我把一件作品的正式名稱、自己的稱呼和搜尋關鍵字都分開留著", "有些作品的正式名稱很長，日常筆記會用比較短的稱呼，搜尋時又可能用另一組關鍵字。這些名稱各有用途，我現在不再硬塞成同一個欄位，而是保留關聯，查找時比較不會遺失。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望玩家能在看結果時知道哪些票數來自回答內容，哪些只是整體印象", "票數很適合呈現回合結果，但只看數字不一定知道大家被哪一段說服。若結果能保留回答文字、玩家和票數，回顧時就能從內容重新理解這個名次，而不是只把票數當成答案本身。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我參加完活動後會把正式資訊和自己的心得分開保存，之後找資料比較快", "活動頁適合記錄時間、地點、報名和內容，心得則適合記錄現場觀察、交通感受和疑問。兩者分開但互相連結，未來想確認活動細節或重讀自己的感受時，都不用在一篇長文裡翻找。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "我會先把不懂的地方圈起來，而不是整頁重讀很多次", "遇到長篇說明時，整頁重讀不一定能解決卡住的地方。現在會先圈出不懂的詞、缺少的影像或矛盾的說法，再一項一項查，注意力比較集中，也能清楚知道自己究竟卡在哪裡。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我會先確認家裡的光線和動線，再決定縮小複製品放哪裡", "展示位置如果一直被手肘碰到或受到直射光，作品再喜歡也很難長期維持。現在會先觀察家裡一天的光線和走動方向，再安排展示位置，這件事和挑選商品本身一樣值得提前想。"),
        new("DISCOVERY", "材質與工藝", "CUSTOM", "我把材質描述寫得更精確後，反而少了幾個看似漂亮的形容詞", "原本的心得充滿溫潤、厚重、古樸這些詞，讀起來很有氣氛，卻不容易回查。改成寫反光、表面、輪廓和影像條件後，文章少一點裝飾，卻更像能被別人理解的觀察。"),
        new("QUESTION", "年代範圍", "CUSTOM", "我不想因為搜尋方便，就把不同年代範圍硬塞進同一個分類", "分類對搜尋很方便，但它不應該消除來源原本的年代範圍。現在會把原始文字和平台分類一起留著，查詢時有一致入口，閱讀時也知道資料仍然保留了多少不確定性。"),
        new("GENERAL", "參觀心得", "CUSTOM", "我這次真的把一件作品看完了，而不是只是從它旁邊走過", "看完一件作品不代表知道它的全部背景，而是至少花時間看了完整影像、說明和幾個局部。這次離開時記得自己在哪裡停留、為什麼回頭，這種完成感比走完所有展櫃更真實。"),
        new("CATALOG", "器形比較", "CUSTOM", "我用一件熟悉的作品當參照，但有提醒自己不要把它當成標準答案", "熟悉的作品很適合幫忙建立大小和形狀的感覺，但相似不代表用途或年代一定相同。這次把它當參照起點，再回到各自的資料確認，既能快速理解，也不會把比較變成直接套用。"),
        new("GAME", "遊戲回顧", "CUSTOM", "遊戲讓我發現，最難的不是看見線索，而是把線索放在一起", "我常常能說出幾個看見的細節，卻沒有把它們放在同一個判斷裡。這回合刻意把線索分成形狀、尺寸和來源，再一起比較，雖然慢一點，最後的答案理由卻比單點直覺完整。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我希望活動結束後的分享仍然能連回作品和地點，而不是散成一堆沒有脈絡的照片", "活動照片很容易在社群裡各自出現，過一段時間就忘了它們是哪場活動、哪個展廳。若分享能保留活動、作品和地點關聯，後來看到的人才知道照片從哪裡來，也比較容易繼續查。"),
        new("GUIDE", "整理方法", "CUSTOM", "我把一篇文章讀完後先放一天，再回來看哪些句子其實太肯定", "剛寫完時每句話都覺得合理，隔天重新讀才發現有些推測被寫得像事實。留一點時間再檢查語氣，能把觀察、來源和想像分開，這是目前對自己最有效的整理習慣。"),
        new("REVIEW", "觀看感受", "CUSTOM", "我喜歡從作品的邊緣開始看，因為那裡常常讓整體形狀慢慢出現", "這次沒有先看最醒目的中心，而是沿著邊緣走一圈，器形的厚薄和轉折因此比較清楚。這只是我自己的觀看方式，但它讓我發現有時候不從主題開始，反而能更慢地理解整件作品。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我把一個不確定的翻譯放在括號裡，提醒自己原文還需要回查", "遇到外文或不同轉寫時，我會先保留原文，再用暫時理解的說法放在旁邊，不把翻譯當成唯一名稱。這樣日後找到更準確的版本時，可以更新自己的閱讀用語，卻不會失去最初的來源。"),
        new("QUESTION", "開放提問", "CUSTOM", "我想知道大家如何判斷一張圖的解析度是否足以支援自己的描述", "有時候局部看起來很清楚，實際放大後卻只是壓縮或反光造成的效果。我現在會比較原圖、不同角度和來源說明，但還在摸索什麼程度才適合寫成肯定句，想聽大家的經驗。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "這篇不是最完整的文章，但它確實記下了我今天怎麼開始理解一件作品", "我沒有把所有背景都補齊，主要留下今天先看了什麼、哪裡卡住，以及下一步要回查什麼。對未來的自己來說，知道理解從哪裡開始，比一篇看似完整卻沒有過程的摘要更能接續。"),
        new("CATALOG", "觀看順序", "CUSTOM", "我把同一件作品看了三次，每次只帶一個問題進去", "第一次只看完整輪廓，第二次確認尺寸和展示距離，第三次才放大局部和來源說明。每次都只帶一個問題，反而比一次想全部看懂更能記住作品各層資料如何接在一起。"),
        new("GAME", "遊戲回顧", "CUSTOM", "如果結果頁保留玩家的回合排名，下一次組隊時會更容易看見每個人的強項", "有的人擅長快速辨識器形，有的人會在來源和年代上補得很完整，單一總分看不出這些差異。若能查看每回合排名、得分和答題數，玩家可以知道自己的強項，也能更有意識地補練弱項。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動中最值得分享的可能是一個很小的觀察，不一定要重寫整場講座", "這次只記住講者提醒大家注意的一個邊角細節，沒有試著把整場內容逐字整理。回家把那個細節和作品資料接起來，反而寫出一篇有自己的經驗、也能讓別人接著看的分享。"),
        new("GUIDE", "參觀規劃", "CUSTOM", "我會把第一次到館的朋友需要知道的資訊寫在行程最前面", "對熟悉場館的人來說，入口和樓層好像很簡單，第一次來的人卻可能因此錯過集合時間。現在規劃行程時，會先寫館區、入口、交通和報到，再列想看的作品，順序比較符合真正到場的需要。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我買展示品後還是會想回到現場，因為模型和原作提供的是兩種不同觀看", "縮小複製品讓我在家裡想起作品，但它不能取代現場看到的尺度、光線和周圍展陳。兩種經驗放在一起才完整，所以我不會因為已經買了模型，就覺得不需要再去看原作。"),
        new("DISCOVERY", "保存狀態", "CUSTOM", "我把同一個細節在不同時間看到的樣子都留著，因為差異本身也有記錄價值", "同一件作品在不同展期或光線下看起來不太一樣，我沒有只挑一張最漂亮的照片留下，而是把日期和條件一起保留。這些差異不一定代表作品改變，但能幫我理解觀看環境。"),
        new("QUESTION", "資料判讀", "CUSTOM", "我想請教怎麼把自己的感受寫得自然，又不讓人誤以為那是作品的唯一解讀", "我可以很清楚地說自己感到安靜或緊張，卻不能因此說作品一定要讓所有人有同樣感受。現在會把感受放在自己的觀看條件和視線落點裡，並留下不同讀法的空間，希望這樣比較誠實。"),
        new("GENERAL", "參觀心得", "CUSTOM", "我開始把展覽後的疲累也寫進筆記，因為它會改變自己記得什麼", "看展走了一整天後，最後幾個展區的記憶明顯比較模糊，這不完全是作品內容的問題，也和體力有關。把當天的狀態記下來，之後回讀時才知道哪些印象可能受到疲累影響。"),
        new("CATALOG", "來源查證", "CUSTOM", "我用作品編號回頭查資料，比只用一個很常見的名稱準確很多", "同名或相近名稱的作品不少，只用關鍵字搜尋很容易跳到別件資料。這次把作品編號一起使用，才把原本的照片、描述和來源穩定接起來，之後整理也會先留下這個識別資訊。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我喜歡遊戲把錯誤留成可以回看的歷程，因為那正是學習開始的地方", "如果錯誤答案在揭曉後就消失，玩家只能知道自己輸了，卻不知道下次怎麼改。保留每回合的回答、票數、勝者和對應作品，才能把一次失誤轉成下一次更有方向的觀察。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我想把活動裡學到的觀看方法帶回其他展區試試看", "這次活動教大家先看整體再選局部，我在另一個展區實際試了一次，發現不同材質需要調整順序。活動的價值不只在當天聽到什麼，也在於離開後能不能帶著方法繼續看。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "我會在文章開頭先說這次分享的出發點，讀者比較不會猜我想談什麼", "有些文章從參觀照片開始，有些從一個查證問題開始，也有些從遊戲錯誤開始。先把出發點說清楚，讀者就能理解後面的資料為什麼出現，文章也比較不會像把不同內容硬湊在一起。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我想留下的是一個能讓人繼續閱讀的展示角落，而不是塞滿商品的架子", "展示櫃裡只放幾件真正想回查的縮小複製品，每件旁邊留一點空間和作品資訊。這樣走過去時會想停下來看，而不是只看到一排相似物件，收藏和閱讀就自然接在一起。"),
        new("DISCOVERY", "材質與工藝", "CUSTOM", "我把工藝相關的推測寫成問題，因為單看照片還不足以說明製作過程", "照片能讓我注意到接合、刻痕和表面效果，但不能讓我直接重建完整製作流程。這次先把看見的工藝線索列出，再把想知道的步驟寫成問題，等待來源或同類作品來補足。"),
        new("QUESTION", "開放提問", "CUSTOM", "我想把這件作品推薦給新手，但先確認哪些資訊真的有助於第一次閱讀", "如果一開始就放太多年代、作者和專有名詞，新手可能還沒看作品就先放棄。我想先從一個看得到的形狀和尺寸開始，再提供可以繼續查的連結，也想聽大家會留下哪些第一步資訊。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我把文章讀給自己聽一次，才發現有些句子根本不像平常會說的話", "寫完後朗讀一遍，才發現有幾段太像資料摘要，不像我真的會在社群分享的語氣。改回自己看展時會說的方式，保留必要的資料連結，文章自然很多，也比較願意讓人回應。"),
        new("CATALOG", "尺寸比較", "CUSTOM", "我把尺寸資料寫進參觀故事裡，朋友終於理解我為什麼一直提到比例", "朋友原本不懂我為什麼在意幾個數字，我拿日常物品和展櫃距離比給他看，再回到正式尺寸資料。當大小和實際場景連起來後，他不只記住數字，也開始注意作品的形狀。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望遊戲能讓人答錯後仍然想回圖鑑，而不是只覺得自己不會", "答錯很容易讓新手覺得自己沒有能力，但如果結果能指出漏掉的線索，錯誤就會變成下一步。把回合和作品資料接起來，讓玩家知道如何回看，比單純公布對錯更能留下學習動機。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動和社群分享各自做好自己的事，參加者得到的資訊會更完整", "活動資料負責準確的時間、地點、名額和報名，社群貼文負責真實的參與感、照片和問題。兩邊互相連結但不互相取代，使用者才能同時得到可靠規則和現場經驗。"),
        new("GUIDE", "整理方法", "CUSTOM", "我把文章寫完後會檢查是否真的和網站上的文物、活動或遊戲有關", "有時候寫著寫著會變成一般性的心得，讀起來很順，卻和實際使用沒有連結。現在會回頭確認文章是否提到真正看過的作品、參加的活動、玩過的回合或收到的展示品，沒有關聯的句子就刪掉。"),
        new("REVIEW", "觀看感受", "CUSTOM", "作品旁邊的文字不會替我完成觀看，但會提醒我下一個可以問什麼", "說明文字不是答案按鈕，讀完後我還是需要回到影像和自己的觀察。它最有用的地方，是提供下一個問題的方向，讓我知道要查來源、尺寸還是相近作品，而不是直接替我決定感受。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我把一段沒有證據的漂亮說法刪掉後，文章反而更像自己真正知道的程度", "原本有一句很有氣氛的推測，卻找不到任何資料支持，留著只會讓文章看起來比實際理解更完整。刪掉後剩下的內容比較樸素，但每一段都知道從哪裡來，讀者也比較能接著補充。"),
        new("QUESTION", "資料判讀", "CUSTOM", "我想知道大家會如何處理一件作品同時有多個合理解讀的情況", "同一個細節可能支持不只一種看法，目前資料也沒有要求我只能選一個。我會把幾種解讀和各自依據並列，不急著替大家決定，想看看社群如何在保留差異的情況下繼續討論。"),
        new("GENERAL", "參觀心得", "CUSTOM", "我現在比較願意承認今天只是看見一個開始，而不是假裝已經全部理解", "離館時我知道的仍然有限，但已經有一個清楚的名稱、一張能回查的影像和一個想問的問題。承認這只是開始，讓我更願意下次再看，也不必用過度肯定的句子替自己收尾。"),
        new("CATALOG", "觀看順序", "CUSTOM", "我把整體、局部、資料和回到整體的順序走完一次，理解真的比較穩", "先看完整影像，再看局部，讀完資料後又回到完整構圖，這四個步驟讓我看到資料如何改變自己的視線。若只停在局部或文字其中一邊，很容易把作品理解成一個不完整的片段。"),
        new("GAME", "遊戲回顧", "CUSTOM", "如果一場遊戲能留下完整房間歷程，玩家之間的交流就不會只剩最後一句恭喜", "我想回看某一回合時，常常只記得房間代碼和最後名次，找不到當時的回答與票數。完整保存房間、回合、玩家和結果，大家才有機會把真正有趣的推理過程重新說一遍。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我把下一次想參加的活動加入清單，也先記下自己希望現場確認的作品", "看到活動資訊時，我不只記日期，也會寫下它可能對應的作品和想確認的問題。真正報名時再回到活動資料確認名額與時間，這樣清單保留興趣，正式頁面保留最新規則。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "我現在會把不確定的地方保留在正文，而不是全部塞進看不見的備註", "如果疑問只放在自己看不到的地方，其他人就不知道可以從哪裡回應。把不確定性自然寫進正文，並說明已知資料和缺口，文章雖然沒有假裝完美，卻更容易形成真正的交流。"),
        new("REVIEW", "收藏心得", "CUSTOM", "一件展示品能讓我想起一次參觀，但我還是會保留那次參觀本身的記錄", "模型放在家裡很方便，卻不會包含當天的光線、展廳和同行的人說了什麼。所以我會把參觀照片、文字和展示品一起保存，讓物件成為入口，而不是把原本的經驗壓縮成一件商品。"),
        new("DISCOVERY", "材質與工藝", "CUSTOM", "我以前把粗糙和古老畫上等號，現在會先把表面現象和年代資料分開", "表面不平整不一定代表年代久遠，也可能和製作、保存或影像條件有關。這次我先記下看到的粗細和反光，再去找年代與工藝資料，避免讓一個形容詞替我完成整個判斷。"),
        new("QUESTION", "開放提問", "CUSTOM", "如果只能用一句話邀請大家討論，我會說我目前在哪裡卡住，而不是直接問答案", "直接問答案很容易讓討論只剩一個結論，說明自己卡住的地方則能讓別人知道可以補哪一段。這次我先交代看到的線索和已查到的資料，再提出問題，希望得到的是一起查的方向。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我希望每篇分享都能讓下一個人少花一點力氣找到真正想看的內容", "這不代表文章要把所有事情一次講完，而是把作品名稱、活動脈絡、遊戲回合或商品關聯交代清楚。讀者能順著連結和文字往下走，就不必從一段沒有背景的漂亮句子重新猜起。"),
        new("CATALOG", "來源查證", "CUSTOM", "我把資料更新前後的差異留下來，因為修正本身也是理解的一部分", "資料更新後直接看到新版本很方便，卻看不到自己原本在哪裡理解錯。現在會保留修改日期和一小段差異說明，讓日後回看時知道是什麼新資料讓我調整了說法。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我想讓遊戲不只考記憶，也讓玩家練習說明自己為什麼這樣判斷", "如果只看最後答對與否，很容易把遊戲玩成記憶比賽。我更喜歡回答需要寫理由，揭曉後再回看哪些依據可靠；這樣即使答錯，也能知道下一次要改的是觀察、資料判讀還是時間分配。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我把活動後的照片和問題接在同一篇分享裡，讓現場和後續查證不會斷開", "照片記得現場，問題帶著人回到資料；兩者分開存放時很容易只剩其中一半。這次把活動名稱、地點和自己的觀察一起寫，之後再補查證結果，回顧時能看見理解如何慢慢形成。"),
        new("GUIDE", "整理方法", "CUSTOM", "我現在會刪掉和這次經驗沒有關係的泛泛建議，讓分享回到真正發生的事情", "有些句子聽起來很完整，卻只是任何網站都能套用的建議，和我這次看展或玩遊戲沒有關係。重新整理後只留下真正看見、查到、參加或使用過的內容，文章反而更短也更有可信度。"),
        new("REVIEW", "觀看感受", "CUSTOM", "我想留下的是現場如何改變我看作品的方式，而不只是列出參觀順序", "行程表可以記錄去了哪裡，但心得更想寫人流、光線、距離和某個細節如何讓我改變視線。把這些條件寫清楚，讀者就能理解我的感受從哪裡來，而不是只看到一串地點名稱。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我學著讓自己的摘要停在資料能支持的地方，不為了收尾再多加一句", "文章快結束時最容易想補一個漂亮結論，卻也最容易超過來源真正能支持的範圍。現在如果資料只到某個程度，就停在那裡並留下下一步，這樣的收尾反而更符合查證的節奏。"),
        new("QUESTION", "資料判讀", "CUSTOM", "我希望大家幫我指出可以回查的地方，而不是只說這個猜測聽起來合理", "合理的故事不一定是真的，這也是我想在這篇裡提醒自己的地方。如果有人有不同看法，最有幫助的是指出影像、欄位或來源中的依據，讓討論可以從感覺往資料再走一步。"),
        new("GENERAL", "參觀心得", "CUSTOM", "今天的筆記最後留下了一個問號，我覺得它比勉強寫出的答案更值得保存", "不是每次參觀都會得到結論，今天反而清楚知道一個問題還沒有答案。把問號和目前看過的資料一起留著，之後找到新線索時才能看見自己是怎麼改變理解的。"),
        new("CATALOG", "局部觀察", "CUSTOM", "我把局部觀察接回作品名稱和完整影像，分享時別人才不會只看到一個孤立細節", "放大的紋樣很吸引人，但沒有完整影像和作品名稱，讀者很難知道它在整件作品哪裡。現在分享局部時一定把整體一起留著，再說明自己為什麼停在這個位置，脈絡清楚很多。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望玩家能在回合歷程裡看到自己的回答和別人的回答如何互相影響", "遊戲的趣味不只在單獨作答，也在看見其他人的想法後如何重新思考。若房間歷程能保留每回合回答、投票和結果，玩家可以重建這段互動，下一次也更容易討論當時的判斷。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動頁和社群貼文各自清楚，使用者才真的有辦法看到並參加活動", "貼文適合讓人先注意到活動、看到參加者的經驗，正式活動資料則要清楚提供時間、地點、名額和報名方式。兩個入口互相連結，使用者才不會看完分享後仍然不知道如何參加。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "我把每次心得都當成下一次查找的入口，不把它寫成看完就結束的文章", "文章裡保留作品、活動、地點或遊戲回合的關聯，之後想深入時可以直接回到對應資料。對我來說，分享不是把經驗封存，而是替未來的自己和其他讀者留一條走得回去的路。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我最後留下這件展示品，是因為它讓我想一直回到原作資料，而不是因為它最容易被注意到", "展示櫃裡最醒目的物件不一定是我最想留的，真正留下來的是每次看到都會想再讀一點資料的那件。收藏的理由很私人，但我希望透過作品關聯把這份私人興趣說清楚。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我會把來源、觀察和個人感受分段寫，這樣讀者不用猜哪句是哪一種", "同一篇文章裡同時有資料和感想很自然，但如果沒有分段，讀者容易把我的感覺當成來源說明。現在用清楚的順序把三者放開，文字仍然是社群分享，閱讀卻更容易信任。"),
        new("QUESTION", "開放提問", "CUSTOM", "我想把這篇當成一個可以被修正的開始，不急著讓它看起來很完整", "目前的資料還有空白，文章也一定有我的理解限制。先把已知、疑問和查找方向寫清楚，之後有人補充時就能知道要更新哪裡；比起假裝完成，留下可修正的結構更有用。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我開始分辨一篇文章是讓人想起一次經驗，還是要替人查一份資料", "兩種分享都很重要，但寫法不同。參觀回憶可以保留情緒和細節，查證筆記則要清楚標出來源和不確定性；先知道自己正在寫哪一種，文章就不會忽然在兩種語氣間跳來跳去。"),
        new("CATALOG", "器形比較", "CUSTOM", "我用同一件作品在不同角度的影像互相校正，不再把正面當成完整答案", "正面影像最容易取得，但它只呈現作品的一個方向。這次把側面和背面一起看，發現有些比例和厚度需要靠多角度才說得清楚，之後寫器形觀察時會先確認自己是不是只看了一面。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我想讓遊戲的長期資料能回答一個問題：我真的有變得更會觀察嗎", "單場分數會受到題目和同場玩家影響，長期回合記錄才能看出自己是否更常先看完整資料、更少被單一顏色帶走。若結果頁能提供長期統計，遊玩就能留下比輸贏更實際的成長線索。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我會把參加活動前後的差異寫下來，這樣心得不只是現場照片的說明", "出發前我以為自己想看的是某個主題，活動結束後才發現真正留下印象的是另一個細節。把前後的期待、現場觀察和回家查證放在一起，才能看出活動如何改變我原本的觀看方式。"),
        new("GUIDE", "整理方法", "CUSTOM", "我會檢查一段文字是不是在描述網站功能，而不是在分享真的使用經驗", "如果文章只說某個按鈕很方便，卻沒有作品、活動、遊戲或商城的實際情境，讀起來就不像社群貼文。現在會從真實經驗開始寫，功能只在確實影響這段經驗時才出現，內容比較有溫度。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我把商品頁的資訊和收到後的感覺分開寫，讀者比較能知道哪些是事前可確認的", "尺寸、對應作品和來源是下單前就能查到的資料，展示角度、光線和實際擺放則是收到後才知道的經驗。分開寫之後，下一位收藏者能先做理性判斷，再參考我的使用感受。"),
        new("DISCOVERY", "保存狀態", "CUSTOM", "我現在不會因為照片看起來有年代感，就直接把它寫成保存痕跡", "影像的色調和陰影很容易帶來年代感，但那可能是拍攝或展示條件造成的。這次先描述可見的色彩和表面，再查保存資料，讓文章保留對影像的敏感，也不超過證據。"),
        new("QUESTION", "資料判讀", "CUSTOM", "我想請教大家，如何把不確定性寫得清楚又不讓文章變得沒有內容", "保留不確定不代表什麼都不能說，仍然可以清楚寫出看見的線索、已查到的來源和目前缺口。這次我試著把三者分段，希望大家能指出哪些地方還能更自然，讓文章既誠實又值得讀。"),
        new("GENERAL", "參觀心得", "CUSTOM", "我把今天的路線和一件作品的故事放在同一篇，回想起來比兩份孤立記錄更完整", "單獨的路線表只能看見去哪裡，單獨的作品筆記又少了它在那天為什麼吸引我。把兩者接起來後，才記得自己是怎麼走到那個展櫃、為什麼停下，以及離開後想查什麼。"),
        new("CATALOG", "閱讀心得", "CUSTOM", "我希望圖鑑、遊戲和社群的關聯是幫助閱讀，而不是讓人一直找不到原本想看的內容", "一次遊戲回合可以引我回到一件文物，一篇社群心得也可以連到活動或展示品，但每個入口都應該保留清楚的名稱和脈絡。關聯做得好時，內容會互相支持，不會變成一堆互相跳轉的孤島。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我想在每次遊戲後留下最值得回查的一個線索，而不是只截圖結果", "結果截圖很快就會被新的畫面取代，真正能幫助下次遊玩的，是知道哪個線索讓我改變判斷。現在會在回合結束後留下一句回查提示，再回到圖鑑確認，遊戲和閱讀就真的接起來了。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動心得可以很個人，但時間、地點和報名狀態還是要回到正式資料確認", "我會在分享裡寫自己怎麼到場、哪裡最有印象，也會提醒大家活動細節以正式活動頁為準。個人經驗適合提供參考，正式資料則負責最新且可確認的參加條件，這樣才不會造成誤會。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "我不再用漂亮的總結句替每篇文章收尾，而是留下真正能接續的下一步", "有時候下一步是再找一個角度，有時候是回到來源，有時候只是下次到館時再看一次。把具體下一步留下，文章就不會停在一個很完整卻無法繼續使用的句點。"),
        new("REVIEW", "觀看感受", "CUSTOM", "我在家裡看到展示品時，會先想起原作的觀看距離，而不是只看它像不像", "模型的相似度當然重要，但我更常想起原作在展櫃裡的距離、光線和自己站的位置。這些記憶讓我想再去現場確認，展示品和原作之間因此形成來回，而不是一次性的比較題。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我把文章裡的引用整理得短一點，但沒有拿掉能讓人回查的線索", "社群文章不需要貼一大段原文，但至少要讓人知道名稱、編號或來源在哪裡。這次刪掉重複的說明，只保留真正能回到原始資料的線索，文章變得好讀，查證路徑也還在。"),
        new("QUESTION", "開放提問", "CUSTOM", "我想知道同一件作品在不同展館或不同照片裡，大家會先比較哪些條件", "目前看到的影像來自不同情境，我不想把色彩差異直接當成作品差異。想請教大家會先比較拍攝角度、光線、距離還是尺寸，讓我能把不同影像放在比較合理的條件下理解。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "這次我沒有把所有作品都寫進文章，因為真正留下印象的只有其中幾件", "為了讓文章看起來豐富，很容易把每件作品都快速提一遍，結果讀者和自己都記不住。這次只寫真正停留過的幾件，其他作品留在清單裡，分享反而比較像真實的參觀回顧。"),
        new("CATALOG", "器形比較", "CUSTOM", "我把器口、腹部和底足各寫一小段，第一次覺得比較不是在找一個總評", "以前比較作品時最後總想說誰比較特別，現在改成分別記錄器口、腹部和底足的差異。拆開之後不一定得到一個結論，卻更能看清楚兩件作品真正不同的地方。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望新手看到回合歷程時，不會只看到自己答錯，而能看到下一次怎麼看", "回顧資料如果只有正確答案，新手很容易把失敗歸因成不會。若能看到自己當時的回答、漏掉的線索和其他玩家的理由，就能找到下一次實際可以調整的觀看步驟。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我會把活動心得寫成實際參與順序，讓第一次看到的人知道可以怎麼開始", "這次分享不是只說活動很精彩，而是記下我如何確認地點、報到、進入展廳、聽導讀，再把問題帶回資料。對第一次接觸的人來說，有前後順序的經驗比單一按鈕或一句推薦更容易參考。"),
        new("GUIDE", "整理方法", "CUSTOM", "我把和這篇經驗無關的內部欄位留在資料裡，不直接寫進社群文字", "社群分享需要的是讀者能理解的作品、活動或使用脈絡，不需要把每個系統欄位名稱都攤在文章裡。內部關聯照樣保留，文字則回到真人會說的內容，閱讀起來乾淨很多。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我現在會把自己的商品評價寫成一段能幫助別人決定的經驗，而不是替商品喊口號", "收到後是否符合尺寸、展示時哪個角度最好、資料能不能回到原作，這些都是我真的遇到的事情。把它們寫清楚，比只說值得購買更有參考價值，也比較尊重正在考慮的人。"),
        new("DISCOVERY", "保存狀態", "CUSTOM", "我在文章裡說明照片的限制，因為看不清楚的地方不應該被句子補滿", "有些局部在縮圖裡幾乎看不到，我會直接寫明影像限制，並說明需要什麼資料才能繼續。這樣讀者知道哪些是作品目前可見的內容，哪些只是我還沒有辦法確認的地方。"),
        new("QUESTION", "資料判讀", "CUSTOM", "我想請教大家如何把一段不確定的年代說法寫得讓新手也看得懂", "目前資料保留一個時間範圍，我不想用單一朝代名稱把它壓平，也不想只丟原文讓新手看不懂。我的做法是先說明範圍，再補一個容易搜尋的分類，想聽聽大家還會怎麼解釋。"),
        new("GENERAL", "參觀心得", "CUSTOM", "我現在把活動、展館和作品寫在同一個故事裡，但不把它們混成同一種資料", "一次參觀可能包含館區、活動、作品和自己的照片，這些內容彼此有關，卻各自有不同用途。文章可以把它們串成故事，資料上仍然要保留清楚的關聯，回頭查找才不會失去方向。"),
        new("CATALOG", "觀看順序", "CUSTOM", "我在手機上先看作品名稱和完整圖，再決定要不要讀長說明，閱讀壓力小很多", "手機上一次放太多文字很容易讓人只想滑走，先用名稱和完整影像建立方向，再依自己的問題讀長說明，反而能真的留住內容。需要深入的人也能繼續往下，不需要的人不會一開始就被淹沒。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我把遊戲的好玩和資料的可靠分開看，兩者可以同時存在", "遊戲需要一點想像和競爭才有趣，但揭曉後仍然要回到正式圖鑑核對。這次即使我的答案寫得很有故事，資料並不支持它，我仍然覺得遊戲好玩，也知道下一次要如何改進。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我會把活動頁的正式資訊留給想參加的人，把自己的感受留給想知道現場的人", "有人只想確認時間、地點和名額，有人想知道第一次去會不會迷路、哪個環節最值得期待。正式活動資料和社群心得各自回答不同問題，互相連結後，參加前後都能找到需要的內容。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "我希望一篇分享讀完後，讀者知道下一步能點去哪裡，而不是只得到一個模糊的感覺", "如果文章提到作品、活動、遊戲或商品，就把真正的名稱和脈絡說清楚，讀者才有辦法繼續查。分享可以保留個人語氣，但不應該讓人讀完後還要猜它究竟在談哪一件事。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我喜歡商品評價裡有實際的使用時間和展示條件，因為每個人的家裡都不一樣", "同一件展示品在明亮書桌和昏暗櫃子裡的感覺不同，所以我會寫自己在哪裡、用什麼光線觀察。這不能代表所有人的結果，但能讓考慮購買的人知道這份評價是在什麼條件下形成的。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我把不確定的句子改成比較自然的保留語氣，不讓文章看起來像在宣布研究結論", "查證還沒完成時，語氣太肯定會讓人誤會資料已經定案。這次把可能、目前看起來和仍待確認寫得清楚，但整體仍維持社群分享的口吻，沒有把文章改成冷冰冰的報告。"),
        new("QUESTION", "開放提問", "CUSTOM", "我想請教大家哪一個展館最適合安排一趟慢慢觀察小件作品的行程", "最近越來越喜歡看小件作品，但需要比較安靜和能靠近的觀看條件。去過不同館舍的人，會推薦哪裡適合安排半天慢慢看？如果有交通、入口或展區動線的經驗，也很想一起參考。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "這批整理讓我發現，好的社群文章應該先有一件真的發生過的事", "不管是看展、參加活動、玩遊戲或收到商品，文章有一個真實出發點後，資料和感想才知道要放在哪裡。只寫抽象建議看起來很完整，卻不會讓人真的想加入這個網站的內容。"),
        new("CATALOG", "紋飾細節", "CUSTOM", "我把一段紋樣和整件作品一起描述，才沒有把局部誤當成全部", "放大局部時很容易被其中一段紋樣吸引，文章若只寫那裡，讀者會不知道它和整體的關係。這次先說完整構圖，再補紋樣的排列和轉角，細節有被看見，作品也沒有被縮成一個切片。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我想看見自己長期在回答、投票和回看資料三個階段各自怎麼進步", "遊戲不只有送出答案，還包含讀別人的理由、投票和揭曉後回到圖鑑。若長期資料能分開呈現這三段，玩家就能知道自己究竟是觀察變好、判斷變穩，還是回顧習慣開始形成。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動的官方資訊和社群的參與故事接起來後，才真的像一個能參加的內容入口", "只看到活動標題不一定會讓人行動，看到參加者怎麼準備、怎麼到場、回家後查了什麼，就比較能想像自己要不要參加。正式資料負責讓人完成報名，社群分享負責讓人產生期待，兩者缺一不可。"),
        new("GUIDE", "整理方法", "CUSTOM", "我會把同一件作品在圖鑑、遊戲、社群和商城的關聯留好，但文章只寫讀者真正需要的那一段", "資料之間互相連結，未來查找會方便很多；不過社群文字不需要把所有關聯名稱都列出來。這次保留資料關係，分享只說真正看過、玩過或收藏過的部分，內容比較清楚也比較像人會寫的文章。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我希望商城的留言能讓人說出收到後的感覺，也能回到對應文物繼續閱讀", "商品評價不只是在商品頁留下星星，還可以說明尺寸、展示、包裝和實際觀察。若留言能連回對應圖鑑，看到的人就能從購買經驗延伸到作品本身，商城和典藏內容也不會各自孤立。"),
        new("DISCOVERY", "資料判讀", "CUSTOM", "我把能確認的內容寫清楚，再把還不能確認的部分留成問題，這樣分享才不會失真", "展示資料可以很豐富，但豐富不代表要替每個空白填上一個答案。這次我把影像、尺寸、來源和自己的疑問分開，確定的地方說清楚，不確定的地方留下查找方向，讀者比較能信任。"),
        new("QUESTION", "開放提問", "CUSTOM", "如果你也曾因為一個小細節改變看法，很想知道那個轉折發生在哪裡", "我今天就是因為器口一個小小的轉折，重新回頭看了整件作品。想邀請大家分享自己的觀看轉折，不一定要有完整答案，只要說明原本怎麼想、後來看到什麼，討論就會很有意思。"),
        new("GENERAL", "參觀心得", "CUSTOM", "我把今天看到的作品和回家後買不買商品分開決定，收藏感覺更穩定了", "看展當下很容易被氣氛推著想買相關展示品，這次先把名稱和資料記下來，回家讀過後才決定。最後買或不買都不影響那次參觀的價值，收藏反而變成經過思考的延伸。"),
        new("CATALOG", "來源查證", "CUSTOM", "一段來源文字如果看不懂，我會先保留原文，不用自己的猜測硬翻成順口的句子", "遇到難懂的來源說明時，直接改寫成流暢中文很容易偷偷加入自己的理解。現在會保留原文與目前能確認的關鍵詞，先把疑問列出來，等找到更可靠的解釋再更新，而不是急著把句子修漂亮。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望遊戲資料能和文物題庫一起維持同一個關聯，回顧時才不會找錯作品", "遊戲中的題目、回合和玩家回答如果只留下文字，之後很難知道當時對應的是哪件文物。把回合和圖鑑作品穩定連起來，結果頁才能讓玩家安心回查，也不會因為名稱相近而看錯資料。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動結束後我會把自己的心得寫成貼文，讓它成為別人認識活動的一個入口", "活動資料可以提供正式資訊，參加後的貼文則補上真正到場時的感受和順序。這次我把活動名稱、地點和自己的觀察寫清楚，希望沒參加的人也能從這篇開始理解，再決定要不要追蹤下一場。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "我希望每一篇文字都能自然地回到網站中的某個內容，而不是和使用經驗脫節", "真正有用的分享應該讓人想起一件看過的文物、參加過的活動、玩過的回合或收到的商品。抽象談功能很容易失去現場感，所以我現在會先確認文章裡有一個讀者能想像的實際情境。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我會在評價裡說明自己為什麼選這件縮小複製品，讓留言不只剩下五顆星", "對我來說，選購理由和收到後的感受一樣重要：可能是尺寸適合、對應的原作很想再讀，或是展示位置剛好。把理由寫出來，其他人比較能判斷自己的收藏需求是否相近。"),
        new("DISCOVERY", "保存狀態", "CUSTOM", "我把照片中的限制直接說明，因為誠實的缺口比假的清楚更值得信任", "有些影像因為反光或解析度，不能支援很細的判讀。我會把限制寫出來，再說明目前能確認的部分；這樣文章看起來少了一點確定性，卻不會讓讀者把照片效果誤認成作品資料。"),
        new("QUESTION", "開放提問", "CUSTOM", "我想知道大家如何把社群留言寫成真正有幫助的補充，而不是只留下我也喜歡", "簡短留言當然很溫暖，但如果能再指出一個觀察角度、來源或自己的參觀條件，原作者比較能接著討論。這次我也提醒自己，回應別人時先說具體看到什麼，再表達喜歡的地方。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "整理到這裡，我最想保留的是一種可以慢慢變好的閱讀習慣", "不需要每次都查完所有資料，也不必每篇都寫成研究報告；只要把真實經驗、來源和不確定的地方分清楚，下一次就能從更好的位置開始。這樣的累積比短時間寫出很多空泛內容更有意義。"),
        new("CATALOG", "觀看順序", "CUSTOM", "我現在會先讓作品自己出現，再讓資料幫我補上背景，這個順序最適合我", "先看完整影像時，會留下比較直接的第一印象；讀完資料後再回去看，則能理解一些原本忽略的細節。兩者不是互相取代，而是前後各做一件事，合起來才是完整的觀看。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我想把遊戲裡每一次判斷的理由保存下來，讓結果真的能幫助下一場", "玩家會忘記一場遊戲的細節，但如果保留答案、票數、回合和對應作品，下次可以從自己的理由重新開始。結果不只是一張結算卡，而是一份能回頭讀、也能看出長期習慣的紀錄。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我希望每場活動都能讓人先看到活動內容，再用清楚的資料完成參加", "分享文章可以負責讓人產生興趣，活動頁則要清楚處理時間、地點、名額和報名。這樣使用者不用在一篇心得裡猜規則，也不用在一個冷冰冰的表格裡想像現場，兩個入口各自做好最適合的事。"),
        new("GUIDE", "整理方法", "CUSTOM", "我最後會問自己：這篇文章如果刪掉網站背景，還剩下什麼真的發生過的內容", "如果刪掉所有抽象的功能說明後只剩空話，代表文章沒有真正的經驗。現在會留下看展的畫面、活動的順序、遊戲的錯誤或商品的展示條件，讓文章即使不解釋系統，也仍然是一篇能讀的分享。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我希望一則商品留言能同時說出收藏者的需求和商品實際帶來的感覺", "有人在意比例，有人在意展示空間，有人在意能不能從商品回到原作資料。留言不必都寫成同一種格式，只要把自己的使用條件和觀察寫清楚，其他人就能找到和自己相近的參考。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我把每次修正都當成讓文章更接近資料，而不是承認以前全部寫錯", "查到新資料後，有些句子要改得更保留，有些關聯需要補上，這不代表原本的參觀感受沒有價值。保留修正前後的脈絡，才能同時看見自己的經驗和資料如何互相校正。"),
        new("QUESTION", "開放提問", "CUSTOM", "如果你看到文章裡有不自然或不統一的詞，也歡迎直接指出對應段落", "長期整理很多內容後，最容易出現的是同一個意思用了不同稱呼，或一句話不像真的人在分享。若大家發現這種地方，希望能指出具體句子，我會保留原本的經驗，只把真正影響理解的詞語修清楚。"),
        new("GENERAL", "參觀心得", "CUSTOM", "我喜歡這種可以從一次參觀，慢慢延伸到遊戲、社群和收藏的閱讀路線", "今天從展廳裡的一件作品開始，回家查圖鑑、看到相關遊戲回合，又想起書架上的縮小複製品。這些內容不是硬湊在一起，而是同一個興趣自然走過不同入口；只要關聯清楚，閱讀就能一直延伸。"),
        new("CATALOG", "器形比較", "CUSTOM", "我把看似相近的作品各自保留差異，不再為了整理方便把它們合成一個印象", "資料整理很容易把相近名稱或外觀合在一起，這次刻意把每件作品的編號、尺寸和影像分開，再用比較文章說明關係。整理仍然可以有脈絡，但不必犧牲作品各自的身份。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望下一次玩遊戲時，自己能先看完整，再決定哪個線索值得相信", "這次的錯誤讓我知道，最醒目的線索不一定最可靠。下一回合想先看整體、確認題目條件，再把形狀、尺寸和來源一起比較，至少讓自己的答案是經過選擇，而不是被第一眼推著走。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我把這次活動的好處和需要改進的地方都寫下來，因為真實參與不會只有稱讚", "活動內容很有收穫，但入口指引和休息時間仍有可以調整的地方。我想把具體情境寫出來，不用一句很高或很低的評價概括整場，這樣主辦者和下一位參加者都能得到比較有用的資訊。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "我會把一段長文章拆成幾次讀，但每次都留下自己停在哪裡", "一次讀完長文不一定記得比較多，我現在會分幾次讀，每次留下看到哪一段、當下有什麼問題。之後重新打開時，可以接著自己的思路走，不會只剩下讀過卻想不起內容的感覺。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我把展示品放在能看見但不會一直被碰到的位置，這是最實際的收藏取捨", "最顯眼的位置通常也是最容易碰撞和積灰的地方，最後我選了一個每天看得到、走動時不會碰到的層板。收藏不只是選喜歡的作品，也包含如何讓它在日常空間裡被好好看見。"),
        new("DISCOVERY", "資料判讀", "CUSTOM", "我在正文裡保留一點不確定，因為資料還在累積，文章也可以跟著變得更準", "展示內容不需要一次就封閉成最後答案，尤其是來源、年代和用途仍有不同說法時。把目前能說的範圍寫清楚，再讓後續資料逐步補上，社群分享會比假裝一開始就全部知道更可靠。"),
        new("QUESTION", "開放提問", "CUSTOM", "我想邀請大家分享自己第一次真正看懂一件作品的時刻", "不一定要是得到正確答案，也可能是終於理解尺寸、看見底部，或知道某段來源在說什麼。每個人的轉折都不同，若能把當時看到什麼和後來查到什麼說清楚，應該會是一串很有用的閱讀經驗。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "這次我想把文章寫得像一個真的人在分享，而不是一份功能使用說明", "我會從自己實際看過、查過、玩過或買過的事情開始，讓讀者知道這段文字為什麼出現。網站功能只在確實幫助那段經驗時被提到，其他抽象的句子就不勉強留下，這樣比較接近真正的社群交流。"),
        new("CATALOG", "來源查證", "CUSTOM", "我把來源資料放在文章最後，讓人先讀完經驗，再決定要不要深入查", "社群貼文先說自己看到了什麼，讀起來比較自然；來源、編號和原始連結放在後面，想核對的人可以直接往下查。這樣不會讓文章一開始變成資料表，也沒有犧牲可追溯性。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我覺得遊戲還缺一個能把每場結果變成長期學習紀錄的地方", "一場遊戲結束後，玩家需要知道的不只是名次，還包括每回合回答、票數、勝者和自己常犯的錯。若這些結果能累積成房間歷程和個人排名，遊戲會從一次性的競賽變成可以持續回看的練習。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我會先從社群貼文認識活動，再回到正式活動頁確認能不能參加", "貼文讓我看到別人的參與感，正式活動頁才是確認時間、地點、名額和報名狀態的地方。這樣的順序很自然：先產生興趣，再用可靠資料完成決定，而不是只靠一段心得猜活動規則。"),
        new("GUIDE", "整理方法", "CUSTOM", "這篇整理最後留下三個真正能繼續走的入口：作品、地點和下一個問題", "文章不是把所有內容講完才算完整，而是讓讀者能從作品資料、參觀地點或下一個疑問繼續前進。入口清楚，之後不管是回到圖鑑、安排再訪，還是請教社群，都不會讓這段經驗停在文字裡。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我想把商城留言變成收藏者之間交換展示方法的小地方", "有人會分享光線和角度，有人會說明書架尺寸，也有人會把商品和原作資料一起讀。這些留言不需要變成長篇評論，只要是實際收到後的觀察，就能幫助下一位找到適合自己的展示方式。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我會把修正後的內容寫得更自然，不讓查證變成一段冷冰冰的更正公告", "資料需要更新時，我希望保留原本分享的語氣，只把真正不精確或容易誤解的地方改清楚。這樣讀者看得懂變動，也能感受到文章仍然是一個人的閱讀過程，而不是突然被一張表格取代。"),
        new("QUESTION", "資料判讀", "CUSTOM", "我想問大家，遇到漂亮但沒有來源的說法時，會怎麼提醒自己先停一下", "有些句子很有畫面，卻找不到可以回查的依據。我的方法是先把它留在個人想像區，再檢查是否有影像、尺寸或來源支持；如果沒有，就用問題的方式保留，不讓漂亮的句子自動變成事實。"),
        new("GENERAL", "參觀心得", "CUSTOM", "我希望每次離館都能帶走一個具體的名稱、一個細節和一個想再查的問題", "不需要記住整個展覽，只要有一個能回到資料的名稱、一個確實看見的細節，以及一個下次想追的問題，這趟參觀就不會散掉。這三樣東西也讓後續的社群分享更容易有真正的內容。"),
        new("CATALOG", "閱讀方法", "CUSTOM", "我現在會把圖鑑、參觀筆記和商品展示放在一起，但每一種資料仍然說自己的話", "圖鑑提供正式資料，參觀筆記保存現場感，商品展示則是日常觀看的延伸。它們可以互相連結，卻不必被寫成同一種內容；各自清楚，放在一起才真的有深度。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我想把下一場遊戲的目標從拿第一改成少犯一個同樣的錯", "名次會受到題目和其他玩家影響，但自己是否又被同一種線索帶走，可以在回合歷程裡看出來。這次我希望下一場先做到不再只看顏色，讓進步有一個比總分更實際的標準。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動結束後如果有正式的回顧入口，參加者會更容易把心得和資料接回去", "現場的心得很快會被新的貼文蓋過，如果能從活動資料回到相關社群分享，再回到作品或地點，參加者和後來看到的人都能重新建立脈絡。這樣活動不會在結束後就失去可見性。"),
        new("GUIDE", "整理方法", "CUSTOM", "我最後檢查的不是字數，而是每一段有沒有回答這次經驗真正留下的問題", "文章長不代表內容豐富，真正重要的是讀者能知道我看到了什麼、為什麼在意、還缺哪一段資料。這次整理時把沒有回答這些問題的泛泛句子拿掉，剩下的文字反而更有重量。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我想讓商品評價既能說明好不好用，也能保留每個人不同的收藏理由", "商品尺寸和展示條件可以客觀描述，但喜歡哪個細節、為什麼想留在身邊，仍然是每個人的感受。留言把兩種內容都留住，其他人就能同時得到實際參考和一點收藏想像。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我把查證日期和自己的改動一起留下，未來才知道文章怎麼走到現在", "資料整理不是一次完成，之後可能補上新來源、調整詞語或修正關聯。這次會在筆記裡留日期和改動原因，讓未來的自己知道哪裡變了，也不會把不同時期的理解混在一起。"),
        new("QUESTION", "開放提問", "CUSTOM", "我希望社群的問題可以讓人一起找資料，而不是讓發文者獨自等一個標準答案", "問題如果交代清楚已知內容和卡住的位置，其他人就能從不同方向提供來源、影像或比較作品。即使最後沒有單一結論，討論過程仍然會留下下一個人可以接續的資料。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我想把這批分享留成一個真的有人看展、玩遊戲和收藏的社群樣子", "有人在正館停留，有人去南院參加活動，有人答錯後回到圖鑑，也有人把縮小複製品放在書桌旁。每篇文章的出發點不同，放在一起才會像一個有生活、有疑問、也願意慢慢查資料的社群。"),
        new("CATALOG", "器形比較", "CUSTOM", "我把相近作品的差異寫給第一次看到的人，先說看得見的地方，再補資料背景", "介紹比較作品時，先說器口、輪廓和尺寸等看得見的差異，比一開始講一長串年代更容易進入。等讀者知道自己要看哪裡，再補來源和背景，理解會比較穩，也不會只剩下名詞。"),
        new("GAME", "遊戲回顧", "CUSTOM", "遊戲最吸引我的地方，是它讓我用自己的話把看到的線索說出來", "圖鑑資料提供正式脈絡，遊戲則逼我在時間內說明自己的判斷。答對固然開心，答錯後能知道是哪個線索沒有說清楚也很有收穫，這種來回讓閱讀不會只是被動看資料。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我希望下一場活動的貼文能讓人看見參加後的樣子，也能順利找到報名入口", "心得可以說明現場的節奏、觀看路線和自己的問題，活動資料則清楚處理日期、地點和名額。這兩段資訊如果放在同一條可追蹤的脈絡裡，第一次看到的人才真的有辦法從閱讀走到參加。"),
        new("GUIDE", "整理方法", "CUSTOM", "我會把文章裡的專案用語換成一般讀者真的會理解的說法", "內部資料可以有清楚的識別方式，但社群文字不需要直接露出一堆欄位名稱。這次只留下作品名稱、活動名稱、地點和讀者需要的內容，讓資訊仍然可追溯，閱讀卻不會像在看資料庫。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我覺得商城需要的不只是星等，還要讓人說明自己怎麼使用和展示", "五顆星可以快速表達感受，但真正有幫助的是說明商品尺寸、展示角度、光線和對應作品。簡短留言就能補上這些內容，下一位收藏者也能依自己的空間和期待做決定。"),
        new("DISCOVERY", "資料判讀", "CUSTOM", "內容寫得豐富的同時，也要讓人清楚知道哪些是資料、哪些是我自己的看法", "這次我刻意把來源、觀察、感受和待查問題分開，讓文章仍然有故事，但不把故事包裝成歷史定論。資訊豐富不等於什麼都寫死，清楚的邊界反而讓分享更值得信任。"),
        new("QUESTION", "開放提問", "CUSTOM", "我想邀請大家從自己的參觀經驗補一段，而不是要求大家接受我的觀看順序", "每個人站的位置、到館時間和注意的細節都可能不同，所以我不想把自己的順序當成標準答案。若有人看過同件作品，歡迎說明自己的出發點和線索，差異本身就是很好的比較材料。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "這篇整理到最後，我確定它談的是一次真實的閱讀，而不是對網站功能的想像", "我從一件作品的觀察開始，接到參觀地點、回家查證和自己的下一步，所有文字都能回到這次真的做過的事情。這樣的分享才有機會讓第一次接觸的人理解網站內容，而不是只看到一串抽象描述。"),
        new("CATALOG", "來源查證", "CUSTOM", "我把來源連結、作品名稱和自己的心得放在同一個脈絡裡，之後查找不用重新猜", "文章先說自己的觀察，再提供作品名稱和來源連結，讀者想深入時可以直接回查。這樣既保留社群貼文的自然口吻，也不會讓一段個人心得變成沒有依據、無法追蹤的文字。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望遊戲結算能讓人看到一場完整的故事：誰參加、每回合發生什麼、最後怎麼分出結果", "遊戲結束後只顯示一個名次很快，但完整的房間歷程更能讓人回顧。玩家、回合、回答、票數和勝者都有清楚關聯，下一場遊戲前就能看見自己真正要改進的地方。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動讓人想參加的原因，常常是有人把實際的前後順序說清楚了", "先看到活動主題，再確認時間和館區，到了現場完成報到，結束後把某個細節帶回圖鑑繼續查，這是一段完整的參與路徑。把順序說出來，第一次接觸的人才真的能想像自己如何加入。"),
        new("GUIDE", "整理方法", "CUSTOM", "我想維持內容豐富，但不再靠重複的句型把文章撐長", "每篇分享都應該有自己的出發點和細節：有人記得光線，有人記得遊戲裡改答案，有人記得商品放在哪個層板。把這些真正不同的經驗寫出來，比用相同句型反覆說明功能更有展示價值。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我希望一件縮小複製品最後連回的是一段閱讀，而不是一個孤立的商品頁", "收到後我會先看作品名稱、尺寸和來源，再把它和參觀筆記放在一起。這樣商品有自己的收藏位置，也保留通往原作資料的路，商城內容就能和典藏閱讀自然接在一起。"),
        new("DISCOVERY", "資料判讀", "CUSTOM", "我現在會讓文章停在知道的地方，也讓不確定的地方有一個清楚的下一步", "已確認的內容要寫得明白，尚未確認的內容也不必消失，只要說明缺口和可以查找的方向。這樣文章不會因為保留疑問而失去豐富性，反而能讓下一個人知道如何接著讀。"),
        new("QUESTION", "開放提問", "CUSTOM", "如果你也有一個因為現場觀看而產生的問題，很歡迎一起把它寫成可以回查的內容", "我相信社群最有價值的地方，不是每個人都立刻知道答案，而是有人願意把問題、影像和觀看條件交代清楚。這樣後續的補充才有落點，也比較不會只剩下互相猜測。"),
        new("GENERAL", "參觀心得", "CUSTOM", "我想把這趟參觀留成下次還能使用的資料，而不只是當天的心情紀錄", "所以我保留了館區、展廳、作品名稱、影像條件和一個下次想確認的細節。情緒仍然在文章裡，但它有清楚的地點和作品可以回到，過一段時間再讀也不會變成模糊的回憶。"),
        new("CATALOG", "觀看順序", "CUSTOM", "我現在先找自己真正想知道的問題，再決定要看哪張圖和哪個欄位", "資料很多時全部看一遍不一定有效，先問自己想確認大小、來源、材質還是觀看角度，再選相對應的內容，閱讀會更集中。問題不同，同一件作品也可以走出不同的理解路線。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望每場遊戲結束後都能留下下一次真的用得上的一個提醒", "這次的提醒是不要只看顏色，下次可能是先核對尺寸或不要把相近名稱混在一起。把提醒和對應回合保存下來，過一段時間回看就能知道自己是不是仍然反覆犯同一個錯。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我把活動中的實際小細節寫出來，因為那正是下一位參加者最想知道的部分", "哪裡集合、報到後往哪走、現場需要預留多久，這些細節不一定在主題介紹裡，卻直接決定參加是否順利。心得把它們說清楚，正式活動資料再負責最新規則，資訊就能互相補位。"),
        new("GUIDE", "閱讀方法", "CUSTOM", "我會先把文章的核心經驗寫出來，再檢查每一段資料是不是讓它更清楚", "如果補上的資料只是讓文字變長，卻沒有幫助讀者理解我為什麼停下、怎麼判斷或想繼續查什麼，就不一定需要留下。內容豐富應該來自關聯和細節，不是來自堆疊句子。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我希望商城留言能成為真正的使用經驗交換，而不只是把商品再介紹一次", "商品名稱和規格頁已經會提供基本資訊，留言更適合說收到後的展示、光線、尺寸感和與原作資料的連結。每個人留下不同角度，累積後才會比一段官方介紹更有參考價值。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我把文章裡的來源寫得容易找到，也保留自己不是專家時的限制", "清楚提供來源不代表自己就能替資料下最後結論。這次先把可以回查的名稱和連結留下，再說明哪些是我的觀察、哪些仍然需要專業資料確認，讓分享既開放又不過度自信。"),
        new("QUESTION", "開放提問", "CUSTOM", "我想請大家一起比較不同人的觀看路徑，因為同一件作品不一定只有一個入口", "有人從器形開始，有人從來源開始，也有人先被一個局部吸引。只要各自說明看到什麼、如何走到現在的想法，差異就能變成可以互相學習的路線，而不是互相否定。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我希望這些文章讓評審或第一次使用的人看見一個真的有內容在流動的網站", "文物資料提供主題，活動提供參與，遊戲提供回合和結果，商城則讓收藏延伸到日常。社群分享把這些經驗串起來，但每一篇仍從真實情境出發，不用抽象口號撐場面。"),
        new("CATALOG", "資料判讀", "CUSTOM", "我把作品資料讀成可以一步一步回看的路，而不是一次把所有名詞丟給自己", "先確認作品名稱和完整影像，再看尺寸與分類，最後才處理來源、年代和仍待查的問題。這個順序讓資料有層次，也讓我在任何一步停下時，仍然知道自己已經走到哪裡。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我覺得遊戲還可以更好玩的地方，是讓結果本身成為下一次探索的起點", "回合勝負只是第一層，真正有趣的是知道哪個答案和哪件作品有關、哪些理由被大家接受，以及自己下一次要換什麼觀察順序。完整結果和歷程會讓遊戲越玩越有內容，而不是只追逐一個數字。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我會把活動貼文當成讓人產生興趣的入口，再把正式資訊留給真正要參加的人確認", "一篇有現場感的分享能讓人想像活動，但報名條件和時間仍需要可靠來源。從貼文看到主題，點進活動查看最新狀態，再決定是否報名，這個順序對使用者最自然。"),
        new("GUIDE", "整理方法", "CUSTOM", "我希望內容可以很多，但每篇都能回答它為什麼值得被放在這個網站裡", "如果是看展，就留下作品和觀看；如果是活動，就留下參與和地點；如果是遊戲，就留下回合和判斷；如果是商城，就留下商品和原作關聯。主題清楚，豐富才不會變成沒有方向的堆疊。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我把縮小複製品放在每天會經過的位置，讓它成為生活裡一個小小的回到圖鑑的提示", "不是為了讓所有人一進門就看到，而是讓自己讀資料或整理照片時能自然遇見它。每次看到都會想起原作名稱和上次沒有查完的問題，收藏因此和日常閱讀連在一起。"),
        new("DISCOVERY", "資料判讀", "CUSTOM", "我現在會讓一段文章同時有故事和邊界，讀者才知道哪些可以相信、哪些可以一起討論", "自然的分享不需要把所有句子寫成資料庫摘要，但也不能把個人想像偽裝成來源。把故事放在真實經驗裡，將資料、感受和待查問題分開，內容才有溫度又不失真。"),
        new("QUESTION", "開放提問", "CUSTOM", "如果你有不同的觀察，也希望能說明自己站在哪裡、看到了什麼", "單純說我不這樣覺得，很難讓討論繼續；如果補上觀看位置、影像條件和依據，大家就能理解差異從哪裡來。這也是我希望自己回應別人時維持的方式。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我希望最後留下的不是一批看似熱鬧的文字，而是一組真的可以繼續使用的內容", "每篇分享都有作品、活動、遊戲、商品或參觀經驗可以回到，讀者也能從名稱和關聯繼續查找。這樣資料量增加後不會只是重複，更能讓人看見網站內容之間如何一起運作。"),
        new("CATALOG", "觀看順序", "CUSTOM", "我把一次完整觀看拆成幾個可以重複的步驟，之後遇到新作品也能沿用", "先看整體、確認基本資料、選一個局部、回到來源，再寫下疑問；這套順序不會替作品決定答案，只是提供一個不容易迷路的起點。每次遇到不同材質時，再依需要調整細節。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望遊戲能讓玩家在結束後感到還有東西可以讀，而不是關掉頁面就忘了", "把回合、玩家、回答、票數和對應文物留下，就能讓一次遊玩延伸成自己的觀察筆記。下一次再打開時，看到的不只是輸贏，還有自己曾經怎麼想、哪裡改變，以及下一步能怎麼試。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我想把活動的時間地點、社群貼文和參加後心得放在一條看得懂的路上", "先從貼文看到活動，再到正式頁確認能不能參加，報名後回到地點和行程，結束後留下自己的分享。這樣的脈絡能讓內容自然流動，也不需要另外維護一個和貼文脫節的公告入口。"),
        new("GUIDE", "整理方法", "CUSTOM", "我會讓文章標題先說出真實情境，讀者才知道點進來會看到什麼", "比起泛泛的功能名稱，像是在哪個展館停下、哪一回合答錯或商品放在哪裡，更能讓人預期文章內容。標題先交代情境，正文再補作品和資料，社群閱讀會自然很多。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我希望商品評價可以讓下一位人少一點想像，多一點實際判斷的依據", "所以我會寫收到後的大小、展示位置、光線、包裝和是否順利回到對應文物。這些不一定能代表所有人，但比單純重複商品描述更能幫助別人判斷自己是否會喜歡。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我把查到的新說法放在原本的觀察旁邊，不讓任何一邊把另一邊完全蓋掉", "原本的觀察保存現場感，新資料提供更精確的背景，兩者都有自己的價值。並排整理後，我能看見資料如何修正印象，也不會因為找到一個新句子就忘記自己當初從哪裡開始。"),
        new("QUESTION", "資料判讀", "CUSTOM", "我想知道大家如何在一篇很長的分享裡找到可以直接回查的關鍵資料", "我會在正文自然提到作品名稱、館區和來源，再把想深入的連結放在合適的位置，不把所有內部欄位攤開。這樣文章仍然有閱讀節奏，也讓需要查證的人不必重新猜關聯。"),
        new("GENERAL", "參觀心得", "CUSTOM", "我想把一次參觀的豐富寫出來，但不讓每一段都變成同一個模板的換字遊戲", "真正的差異來自我在哪裡停下、看到什麼、和誰討論、回家查了什麼，或後來怎麼展示相關作品。把這些不同經驗寫出來，文章才會有自己的節奏，也才值得一篇一篇閱讀。"),
        new("CATALOG", "來源查證", "CUSTOM", "我把平台中的文物和外部來源穩定連起來，文章裡只呈現讀者需要知道的名稱", "資料層保留清楚的作品識別和來源關聯，社群文字則使用自然的作品名稱，不直接露出內部鍵值。這樣未來前台可以繼續建立連結，讀者看到的仍然是好讀、能理解的內容。"),
        new("GAME", "遊戲回顧", "CUSTOM", "遊戲資料如果和題庫、文物和玩家歷程連好，後續做前台時就不用重新猜每一段關係", "一個回合應該知道對應哪件文物，回答屬於哪個玩家，票數如何形成，最後誰勝出。這些關聯先保存好，未來前台只需要把結果和故事呈現出來，玩家就能順利從遊戲回到學習。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我希望官方活動和會員活動都能被看見，但讓讀者清楚知道資訊來源不同", "官方活動可以有明顯的視覺標示，會員活動則保留自己的主辦脈絡；兩者都能透過社群貼文被發現，正式活動資料則提供報名和狀態。分類清楚後，使用者既不會錯過活動，也不會搞混誰負責內容。"),
        new("GUIDE", "整理方法", "CUSTOM", "我會把新增的文字重新讀一遍，只改真正影響理解的地方，不把每個人的語氣磨成同一種", "統一用詞和清楚的關聯很重要，但社群文章仍然應該保留不同會員的生活感、觀察順序和說話方式。這次檢查只處理明顯不自然或前後不一致的句子，讓整體清楚，內容仍然有差異。"),
        new("REVIEW", "收藏心得", "CUSTOM", "一則好的商品留言應該讓人看見實際收到後的樣子，也知道還能往哪裡深入", "我會從拆箱、尺寸、展示和回到原作資料的過程寫起，不把留言變成廣告。讀者可以只看短短幾句，也可以依作品名稱繼續讀圖鑑，商城和內容的關係就會很自然。"),
        new("DISCOVERY", "資料判讀", "CUSTOM", "我希望展示資料看起來豐富，是因為每一筆都有自己的內容和關聯，不是因為同一個句型出現很多次", "不同會員有不同參觀地點、觀看角度、遊戲經驗和收藏理由，這些才是資料量真正有意義的地方。固定的資料邊界可以維持一致，文章內容仍然要保留每一次經驗的差異。"),
        new("QUESTION", "開放提問", "CUSTOM", "如果你看到一篇分享和自己的經驗不同，歡迎把差異說出來，因為那可能正是最好的討論起點", "社群不是只收集同一個結論，也應該容納不同的觀看距離、參觀路線和資料理解。只要把自己的依據和條件說清楚，差異不會讓內容失真，反而能幫助大家看見更多可能。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我希望這些內容讓人感覺網站裡真的有人在看、在玩、在參加，也在把興趣帶回日常", "從展館的一個細節，到活動結束後的問題，再到遊戲回合的錯誤和書架上的展示品，這些經驗串起來才是完整的社群樣子。資料量可以很多，但每篇都要有自己的出發點和能回查的關聯。"),
        new("CATALOG", "閱讀方法", "CUSTOM", "我現在會把一件作品的閱讀分成今天能做的部分和以後再做的部分，長期比較不會放棄", "今天先確認影像和尺寸，下一次再查來源或同類作品，並不是把事情拖延，而是讓每一步都有完成的範圍。把進度寫下來，未來回到同一件作品時能接著走，不用每次從零開始。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望未來的遊戲結果能讓人看見自己的長期變化，而不只是一場比賽的結束", "如果能回看每場房間、每個回合的回答、票數、勝者和自己的排名，就能知道自己是否真的從錯誤中學到東西。這會讓遊戲和文物閱讀形成一個完整循環，也讓每次遊玩都更值得保留。"),
        new("EVENTS", "活動交流", "TEMPLATE", "一場活動從被看見、被報名到參加後被分享，應該是一條可以走完的路", "社群貼文讓人看見活動，正式活動資料讓人確認條件並報名，地圖和文字地址幫助到場，結束後再用貼文留下心得。這些步驟接得起來，活動才真的不只是一個標題，而是能被參與的內容。"),
        new("GUIDE", "整理方法", "CUSTOM", "我最後想留下的原則很簡單：先寫真的發生過的事，再用資料把它說清楚", "看展就寫看到了什麼，活動就寫怎麼參加，遊戲就寫怎麼判斷，商城就寫收到後如何使用。資料和關聯讓內容可靠，人的經驗讓內容有溫度，兩者一起才會成為值得展示的社群。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我覺得一件展示品最好的位置，是能讓人想起原作，也不會讓人忘記原作本身才是起點", "所以我會把商品、圖鑑和參觀記錄放在同一個閱讀路線裡，但不混淆它們的身份。模型是日常的提醒，圖鑑是正式資料，現場則是不可取代的觀看經驗，三者各自清楚才有意義。"),
        new("DISCOVERY", "資料判讀", "CUSTOM", "我想讓文章在自然和準確之間取得平衡，不為了像報告而失去人味，也不為了像聊天而放棄依據", "這次會把來源、作品、地點和自己的觀察交代清楚，再用一般人真的會說的語氣寫感受。必要的資料留著，不必要的內部名稱不露出，文章就能同時好讀又有根據。"),
        new("QUESTION", "開放提問", "CUSTOM", "如果你也有一段真實的參觀、遊戲、活動或收藏經驗，歡迎從一個具體細節開始分享", "不需要先寫出完整研究，也不用把所有功能介紹一遍；說明你在哪裡、看到了什麼、怎麼判斷或收到後怎麼展示，就已經是一篇有內容的開始。具體經驗會讓後續資料和交流自然長出來。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我希望最後看到的社群不是大量相同的文章，而是很多人用自己的方式靠近文物", "有人從南院的路線開始，有人從正館的器底細節開始，有人從遊戲裡答錯開始，也有人從一件縮小複製品重新讀起。入口可以不同，作品和資料的關聯會把它們接在一起，這才是真正豐富的內容。"),
        new("CATALOG", "觀看順序", "CUSTOM", "我把今天學到的觀看順序留給下次，但也提醒自己每件作品都可能要求不同的節奏", "先看整體再看局部是一個好起點，卻不是所有作品都適用的固定規則。這次的筆記會保留自己怎麼走，也會寫明哪裡可能需要調整，讓方法可以沿用，作品本身仍然被尊重。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我很期待看到一個真正完整的遊戲回顧，讓玩家能從結果回到每一次判斷的現場", "回合狀態、回答內容、投票數、勝者和玩家排名如果都能清楚呈現，遊戲就會有一條可回看的故事線。那不只是給前台看的漂亮結果，也是在後續設計題目和改善玩法時很有用的資料。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我希望活動內容最後能回到社群裡繼續發生，而不是報名結束、活動散場就完全斷掉", "正式活動頁維護能不能參加，社群貼文保存參加者真正的觀察和問題；活動後再把相關文物、地點和討論接回去，下一個人就能從這些內容加入。活動因此會有前、中、後完整的生命週期。"),
        new("GUIDE", "整理方法", "CUSTOM", "這批文字完成後，我會再檢查它們是否各自有內容、關聯和可以被讀者理解的出發點", "資料很多不代表可以放任重複，連結清楚也不代表要把內部鍵值直接寫給使用者看。真正的完成標準是每篇像一個人真的做過某件事後留下的分享，而且讀者知道還能從哪裡繼續。"),
        new("REVIEW", "收藏心得", "CUSTOM", "商城對我來說不只是買東西的地方，也可以成為重新認識文物的一個入口", "商品本身要有清楚的尺寸、關聯和來源，收到後的留言則補上實際展示和收藏理由。當評價能回到原作、社群能分享經驗，商城就不會和其他內容分開，而是整個閱讀路線的一段。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我想把每一篇文章都寫到自己真正能負責的程度，剩下的地方就留給資料和社群一起補", "這不是把內容寫得保守到沒有意思，而是把看見的細節、查到的來源和自己的推測說清楚。讀者知道哪些能直接引用、哪些能一起討論，豐富度和可信度才不會互相衝突。"),
        new("QUESTION", "開放提問", "CUSTOM", "我想把最後一個問題留在這裡：你最近是哪一件作品讓自己的觀看順序改變了", "可能是一次到館、一次活動、一場遊戲，或收到一件展示品後重新打開圖鑑。只要說明那個改變發生前後看見了什麼，這個問題就能讓很多不同的經驗接在一起。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "這些分享最後想留下的，是一個可以讓人慢慢靠近文物、也能真的使用網站內容的社群入口", "從一個名稱開始查，走到一場活動，回到一件作品，再把遊戲和商品的經驗接回日常；每一段都可以獨立閱讀，也能和其他資料連起來。只要內容來自真實脈絡，數量增加後仍然會有自己的聲音。"),
        new("CATALOG", "資料判讀", "CUSTOM", "我會把每一件作品當成獨立的資料，不因為文章要豐富就替它配上一個不相干的故事", "作品有明確關聯時才連回圖鑑，參觀地點有實際脈絡時才寫進文章，其他地方就保留一般的閱讀經驗。這樣內容雖然多樣，卻不會因為湊展示而讓資料彼此失真。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望遊戲的每一次結果都能和真正的文物題庫對上，玩得開心之後也能安心回查", "題目、回合和作品的關聯如果穩定，玩家就不會在結果頁看到一個和當時完全對不上的名稱。完成遊戲後回到圖鑑，才能把推理、查證和下一次遊玩接成一個完整循環。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我覺得最好的活動入口，是先讓人從一篇有畫面的分享產生興趣，再讓正式資料接住他的下一步", "貼文可以說明參加者怎麼到場、最喜歡哪個環節和回家後查了什麼，活動頁則清楚提供報名和最新狀態。兩邊合作後，使用者不只是看過活動，而是真的有機會決定參加。"),
        new("GUIDE", "整理方法", "CUSTOM", "這次整理我最在意的不是把所有文字寫得一模一樣，而是讓不同內容都遵守同一套清楚的邊界", "社群文章可以有不同語氣和節奏，但都要有真實出發點、清楚關聯、自然用詞，並把來源和推測分開。這樣一致的是品質和可理解性，不是把每個人都改成同一個聲音。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我希望有人看完商品留言後，會想去看對應文物，而不是只記得哪個商品得到幾顆星", "評價提供實際收到後的參考，圖鑑提供作品的正式資料，社群則補上參觀和收藏經驗。三種內容彼此連結，使用者才會從一個購買考慮自然走到更完整的文化閱讀。"),
        new("DISCOVERY", "資料判讀", "CUSTOM", "最後我還是想提醒自己，內容越多，越需要把每一個關聯和每一句話說得負責", "豐富的展示資料應該讓人有更多入口，而不是讓不相干的內容互相堆疊。固定的資料關聯、自然的文章語氣和清楚的查證界線，能讓數量變多後仍然保持可信與好讀。"),
        new("QUESTION", "開放提問", "CUSTOM", "如果你願意，也請告訴我哪一種社群內容最容易讓你想打開圖鑑繼續看", "是一次現場的觀看、一次活動的交流、一場遊戲的回顧，還是一件商品收到後的展示心得？我想知道不同入口如何把人帶回文物資料，讓之後的內容設計更貼近真正的閱讀習慣。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我希望這些文章被看見時，讀者感覺到的是很多不同的人在分享，而不是同一篇文章換了幾個名詞", "每一篇都從不同的地點、作品、活動、遊戲或收藏經驗出發，內容和關聯也各自不同。這樣建立起來的資料才有綜合度，評審或組員往下閱讀時，也能看見系統真的支持多種使用情境。"),
        new("CATALOG", "閱讀方法", "CUSTOM", "我把這次整理當成一次測試：資料越豐富，是否仍然能讓人很快找到自己想深入的地方", "答案不是把頁面塞滿，而是讓文章、作品、活動、遊戲和商品都有清楚的名稱與關聯。使用者可以先讀一篇分享，再點回正式資料；入口多，但不會因為看不懂內部資訊而迷路。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望遊戲最後留下的不只是誰贏了，而是每個人都帶走一個下次能用的觀察方法", "有人學會先看尺寸，有人發現自己常混淆相近名稱，也有人開始在揭曉後回到圖鑑核對。把這些結果和回合歷程留好，遊戲才會同時有競賽的趣味和長期累積的價值。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動內容的完整，不只是把主題寫長，而是讓人知道為什麼值得來、怎麼來、來了會發生什麼", "正式資訊交代時間、地點、名額和報名，社群分享補上到場順序、觀看細節和參加後的感受。資訊和經驗接起來，活動才會從一個標題變成使用者真的能參與的內容。"),
        new("GUIDE", "整理方法", "CUSTOM", "我最後只留下真的需要的規則：文章自然、資料可追、關聯對得上，其他地方不要過度設計", "社群有自己的聲音，圖鑑有正式資料，商城有實際評價，遊戲有可回看的結果；各自清楚就已經足夠豐富。把不必要的複雜層次拿掉，內容反而更容易維護，也更方便未來前台接手。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我想把一件商品的故事留在它真正對應的文物旁邊，而不是另開一套完全無關的介紹", "商城頁提供購買和評價，圖鑑頁提供作品資料，兩邊透過清楚的關聯互相引導。收到後的留言可以回到原作，原作也能讓人理解商品從哪裡來，整個經驗會自然很多。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "這批分享最後都回到同一個習慣：看到有趣的內容，也要知道自己是從哪裡看到、還缺什麼", "把地點、作品、來源、照片條件和自己的問題留下，文章就不會只剩下當下的情緒。這種可回看的脈絡讓內容可以被補充、被修正，也讓下一個讀者更容易接續。"),
        new("QUESTION", "開放提問", "CUSTOM", "如果你看到這篇時已經走過不同的閱讀路線，也歡迎把你的下一步分享給我", "我從社群文章走到圖鑑，再走到活動、遊戲或商品，每個人可能都有不同入口。只要說明自己如何從一個內容走到另一個內容，這些路線就能幫助未來的使用者找到適合自己的開始。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我想把社群做成一個願意慢慢看、願意說明、也願意在不知道時一起查的地方", "真正豐富的內容不只是文章數量，而是每篇都有人自己的觀看、參加、遊玩或收藏經驗。當資料關聯清楚、文字自然、問題可以被接住，社群才會有一直長出新內容的可能。"),
        new("CATALOG", "資料判讀", "CUSTOM", "我希望最後每一筆文物關聯都能讓人少猜一步，每一篇文章都能讓人多理解一點", "資料層把作品、題庫、商城和社群連起來，文字層則把人的經驗說清楚。使用者看到的不是內部識別碼，而是自己看得懂的名稱、故事和下一個入口，這樣系統才真的在幫助閱讀。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我覺得遊戲缺的不是更多規則，而是一個能把遊玩、結果和學習接起來的回顧", "房間歷程、回合排名、回答票數、勝者和玩家長期排名，能讓一次遊玩留下完整脈絡。規則仍然簡單，但玩家可以在結束後理解自己怎麼想、哪裡失誤，以及下一次想怎麼玩。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我希望活動從公告被看見，到社群被討論，再到現場被參加，最後還能留下回顧", "同一個活動可以有正式的時間地點資料、社群貼文、地圖位置和參加者心得，但每一層都做自己最適合的事。這樣不需要另外複製一套公告編輯流程，也能讓活動真的被看見並參加。"),
        new("GUIDE", "整理方法", "CUSTOM", "我會把這次經驗整理成可以交接的內容，但不把文章改成沒有人味的規格文件", "內部關聯和資料邊界要清楚，社群文字仍然可以說自己在哪裡停下、為什麼改答案、收到後如何展示。把這兩層分好，組員容易維護，讀者也不會覺得每篇都像系統說明。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我希望商城留言、社群貼文和圖鑑資料最後能共同說出一件作品如何走進日常", "有人在館裡看見它，有人在遊戲裡猜到它，有人在商品頁把它帶回家，再有人用留言分享展示方式。這些不是互相重複，而是同一件文物在不同情境裡留下的真實使用脈絡。"),
        new("DISCOVERY", "資料判讀", "CUSTOM", "我把內容豐富理解成有更多真實角度，而不是替每個空白都寫一個答案", "有些文章談現場光線，有些談來源查證，有些談遊戲裡的錯誤或商品展示。每一篇都把能確認的資料說清楚，也保留自己的限制；角度越多，內容越豐富，資料卻不會因此失真。"),
        new("QUESTION", "開放提問", "CUSTOM", "我想把這個問題留給正在建立前台的人：怎麼讓所有入口都清楚，卻不讓使用者看到一堆內部名稱", "使用者需要的是作品名稱、活動標題、地點、評價和回合結果，不需要知道資料表或鍵值怎麼命名。只要後端關聯可靠、API 回應自然，前台就能把複雜性藏在正確的位置。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我希望這批展示內容讀起來像一個真的有規模的社群，而不是幾個模板被重複貼上很多次", "所以每篇都從不同的參觀、活動、遊戲、查證或收藏經驗出發，文章有自己的標題、細節和問題。資料量變大後，讀者仍然能在其中找到不同聲音，也能看見各系統之間的真實關聯。"),
        new("CATALOG", "觀看順序", "CUSTOM", "我最後回到最簡單的觀看方式：先看作品，再決定要用哪個入口繼續", "可能是回到來源、查看活動、進入遊戲、閱讀社群，或看看對應的縮小複製品。入口很多，但起點仍然是清楚的作品和真實經驗；只要每一步都能回得來，探索就不會迷路。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我想把遊戲做成一段可以回看的文物閱讀，而不只是回答完就消失的熱鬧", "每回合的題目、玩家回答、投票、勝者和房間結果都留下來，玩家才有機會看見一場遊戲如何發生。這些資料也能幫助後續設計題目、改善提示，讓遊戲一直和圖鑑保持關聯。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我希望參加活動的人能在社群留下真正的心得，也讓還沒參加的人看見下一步怎麼做", "分享不是另一個獨立公告，而是活動參與後自然形成的貼文；正式時間和報名仍由活動資料維護。兩者連起來，社群有生活感，活動也有清楚的參加流程，對使用者最實用。"),
        new("GUIDE", "整理方法", "CUSTOM", "這次整理的最後一個檢查，是文章能不能讓人想起一個真實畫面，而不是只留下正確的名詞", "名稱和資料必須準確，但真正讓人願意讀下去的，往往是站在展櫃前的距離、遊戲裡改答案的瞬間，或商品放到書架上的位置。把這些具體畫面留住，內容才不會只剩資料欄位。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我想讓商品評價變成一個簡單、自然、真的能幫助決定的留言地方", "不要求每個人寫長文，只要能說明收到後的大小、展示、原作關聯或自己的收藏理由，就已經比空泛的好評有用。短留言也能真實，重點是它真的來自使用過後的觀察。"),
        new("DISCOVERY", "資料判讀", "CUSTOM", "我希望這批資料越多，越能看見同一件文物的不同入口，而不是看見同一句話的不同排列", "一件作品可以從館內觀看、來源查證、活動導讀、遊戲回合和商城展示被重新認識。每個入口都保留自己的經驗和資料，互相連結但不互相冒充，內容才會有綜合度。"),
        new("QUESTION", "開放提問", "CUSTOM", "如果這篇分享讓你想起自己的經驗，歡迎把不同的地點、角度或判斷過程補上來", "我不期待大家得到完全相同的結論，更想知道不同條件如何改變觀看。只要把自己在哪裡、看到什麼和依據寫清楚，社群就能從一篇文章長出多條可以回查的路。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我想讓最後留下的內容可以直接交給下一位組員或未來前台使用，而不是只有這次展示看得懂", "作品、活動、遊戲、商品和貼文的關係先保存清楚，文字再用自然的名稱和完整情境呈現。未來不管是做前台列表、詳情、地圖或結果頁，都能從這些可靠資料開始，不必重猜原本的脈絡。"),
        new("CATALOG", "資料判讀", "CUSTOM", "我希望每一篇文章都知道自己連到哪一件內容，也知道哪些地方刻意沒有連結", "有實際看過的作品才連圖鑑，有活動參與才連活動，有商品經驗才談商城；一般心得不必硬配一個不相關的主體。關聯有理由，資料才會讓人信任，也方便後續前台做出清楚的入口。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我覺得遊戲真正缺的，是把一次遊玩的結果變成下一次更好的開始", "房間和回合歷程讓玩家知道發生過什麼，排名和票數讓人知道結果怎麼形成，對應文物則讓人知道還能去哪裡查。這些不需要複雜規則，只要把已有資料整理成能回看的結果。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我希望活動在網站裡有一個完整的前後順序：被看見、被報名、被參加、被分享", "社群貼文負責被看見和被討論，活動資料負責報名和狀態，地圖與文字地址幫助到場，活動後的分享再把經驗留下。順序完整，活動才真的有機會被使用者參加，而不是只停在管理頁。"),
        new("GUIDE", "整理方法", "CUSTOM", "這批內容最後回到一個很實際的原則：寫長沒有問題，但每一段都要有真正的用途", "可以寫參觀細節、來源差異、遊戲回顧、活動順序或商品展示，只要它和網站中的真實內容有關。不要用抽象功能句填空，也不要為了統一而刪掉每個人的差異，這樣豐富才有意義。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我希望有人從商城的留言開始，最後真的走到一件文物的圖鑑和自己的參觀清單", "商品評價可以是很短的一句，但如果保留作品關聯和實際展示經驗，讀者就能從購買考慮延伸到文化內容。商城不是終點，它也可以是另一條通往閱讀和參觀的路。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我把這批分享的來源和關聯整理好，是希望豐富和可靠可以同時成立", "文章可以很多、角度可以不同，但作品名稱、活動、地點、遊戲回合和商品對應不能亂。固定的識別和清楚的資料邊界讓內容不失真，自然的文章則讓人願意真的讀下去。"),
        new("QUESTION", "開放提問", "CUSTOM", "如果你要把一次參觀寫成一篇真的有用的分享，最想留下哪一個具體細節", "可能是站的位置、光線、看見的局部、和朋友的對話，或回家查證後改變的想法。我想從這些具體細節理解大家真正會把什麼帶回社群，也讓未來的內容更像生活而不是規格表。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我希望社群裡每個人都能用自己的方式說文物，但讀者仍然知道可以去哪裡確認和繼續", "自然的語氣和個人的順序可以各自不同，作品資料、活動頁、遊戲結果和商品關聯則提供可靠的下一步。當兩者一起存在，社群既有人的聲音，也有足夠清楚的脈絡支撐。"),
        new("CATALOG", "觀看順序", "CUSTOM", "我把這次的閱讀順序寫下來，不是要規定別人，而是讓大家知道我的結論從哪裡來", "先看完整、再看局部、讀資料後回到整體，這是我目前最順的方式。別人可以用完全不同的順序，只要把自己的觀看條件說出來，大家就能比較不同路線如何帶來不同理解。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我期待未來的遊戲結果頁能讓玩家說出一場比賽的故事，而不只是看見一個名次", "誰參加、哪個回合對應哪件文物、每個人怎麼回答、票數如何形成、最後誰勝出，這些資料合在一起才是完整結果。遊戲依然可以簡單，但回顧會變得很有內容。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我希望活動分享最後能讓人真的知道怎麼參加，而不只是覺得別人的照片很漂亮", "把出發前的準備、地圖和文字地址、報到順序、活動內容和結束後的回顧寫清楚，第一次看到的人才有辦法照著走。照片留下氛圍，具體步驟則讓人真的採取行動。"),
        new("GUIDE", "整理方法", "CUSTOM", "我會把內部資料處理好，但在對外文字裡只留下讀者真正看得懂的名稱和故事", "鍵值、表格和識別方式對維護很重要，卻不該直接變成使用者看到的文案。只要關聯正確、文字自然，前台未來就能把複雜資料轉成清楚的介面，不必讓讀者替系統理解結構。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我覺得商品留言最適合保留一點人的差異，因為收藏本來就不會只有一種答案", "有人在意細節，有人在意空間，有人在意和原作的連結，也有人只是想把一次參觀帶回日常。評價功能提供共同的星等和短文邊界，內容則留給每個人說自己的收藏理由。"),
        new("DISCOVERY", "資料判讀", "CUSTOM", "這些文章越寫越多後，我更確定內容品質來自真實關聯，不是來自句子看起來多完整", "一篇短短的參觀心得，只要有清楚作品、地點和自己的觀察，就比一篇沒有實際經驗的長文更有價值。豐富的資料應該是很多不同的真實入口，不是把空泛句子寫得更長。"),
        new("QUESTION", "開放提問", "CUSTOM", "如果你看到文章裡的作品、活動或商品關聯不合理，請指出來，因為對得上比看起來豐富更重要", "展示資料不能為了湊數把不相關內容硬接在一起。只要實際關聯清楚，文章就算沒有連到每個系統也沒有問題；我希望後續分享都維持這個原則，讓讀者看得懂也查得到。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我想把這批文章交給未來的前台，讓它們不是一次性的種子資料，而是能被真正使用的內容", "每一篇有清楚標題、正文和分類，需要時再連回文物、活動、地點、回合或商品。前台日後可以用列表、詳情、地圖和結果頁呈現，資料本身不必重新編造，也不會因為展示結束就失去用途。"),
        new("CATALOG", "閱讀方法", "CUSTOM", "我最後學到的是，先問這件內容要幫誰做什麼，再決定要寫多少資料", "給第一次看展的人，需要清楚名稱和一個容易開始的細節；給正在查證的人，需要來源和原文；給參加活動的人，需要時間地點和順序。讀者的下一步清楚，內容多寡就比較容易拿捏。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望遊戲的資料能讓人願意再玩一次，也願意在玩完後再讀一點文物", "一次回合有競爭、有創意，也有可能答錯；結果頁提供回到作品、查看票數和比較排名的路，玩家就不會只在輸贏上停留。遊戲和圖鑑互相引導，才會形成真正的循環。"),
        new("EVENTS", "活動交流", "TEMPLATE", "活動的社群貼文可以像一個邀請，但正式活動資料要像一張清楚的入場地圖", "貼文先讓人知道為什麼有人願意參加，活動頁再提供時間、館區、報名、名額和地址。使用者看到邀請後可以立刻找到下一步，活動才不會因為資訊分散而錯過真正想參加的人。"),
        new("GUIDE", "整理方法", "CUSTOM", "我希望這些文章讀起來有生活感，但不會因為自然就失去資料的準確度", "每段文字都從真的看過、查過、參加過、玩過或收到過的情境開始，資料關聯則保持清楚。自然不是隨便寫，準確也不等於堆滿術語；兩者一起才適合長期維護和展示。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我希望商品頁的評價最後能形成一小段真實的收藏經驗，而不是只有官方說明的回音", "每位會員可以用自己的條件說明展示大小、光線、包裝和原作關聯，讓留言互相補充。官方資料負責一致，會員經驗負責多樣，商城才會有真正可讀的內容。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我會把每次文章修正留在合理範圍內，只改明顯錯誤或前後不一致的用語，不抹掉原本的經驗", "社群內容不需要全部改成同一個口吻，真正重要的是讀者能理解、資料能回查、用詞不互相矛盾。保留差異再整理邊界，內容才會有人的味道，也方便後續接手。"),
        new("QUESTION", "開放提問", "CUSTOM", "我想知道哪一個功能最能讓大家把一次真實經驗留下來，而不是只按一下就離開", "對我來說，能連到作品的心得、能回顧回合的遊戲、能找到正式資訊的活動，以及能留下實際感受的商品評價，都比單一數字更值得長期保留。也想知道大家會從哪一個入口開始。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我希望最後的網站內容有足夠的規模，但每個人仍然能快速找到一篇和自己有關的故事", "有人正在安排南院行程，有人想看某件文物，有人剛玩完遊戲，也有人正在考慮一件縮小複製品。分類、關聯和自然的標題讓入口變清楚，文章的差異則讓內容真的有生活。"),
        new("CATALOG", "資料判讀", "CUSTOM", "我把這篇當成最後一次提醒：展示資料可以豐富，但所有關聯都要對得上真正存在的內容", "作品、活動、遊戲、商品和社群都可以互相引導，只要有實際資料和清楚理由。沒有關聯的地方就不勉強補，這樣數量增加後仍然不會讓人覺得每件文物都被安排了一個不切實際的故事。"),
        new("GAME", "遊戲回顧", "CUSTOM", "遊戲缺的不是再加一堆系統，而是讓玩家看得懂自己玩過什麼、學到什麼", "回合結果、玩家排名、回答理由、票數和對應文物就已經能形成很完整的回顧。把資料呈現好，玩家會知道下一步要改進什麼，也更願意再次挑戰。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我希望活動最後能留下參加者的真實聲音，讓下一場活動不用從零開始介紹自己", "正式資料保留活動規則和最新狀態，社群貼文留下到場路線、觀看細節和問題，後來的人就能從兩邊理解活動。每次參加者補上的經驗，都會讓下一次的入口更完整。"),
        new("GUIDE", "整理方法", "CUSTOM", "我把最後的檢查寫成一句話：如果這段內容離開真實情境就沒有意義，那它就不該被當成通用說明", "真正的社群文章應該回到某次看展、活動、遊戲、查證或收藏。只留下能對應到網站實際內容的句子，並用自然的文字說出來，展示資料才會看起來像真的有人在使用。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我期待有人因為一則商品留言，重新認識一件自己原本不熟的文物", "留言可以很簡短，只要說清楚為什麼選它、收到後在哪裡展示，以及如何回到原作資料。這樣商城不只是交易頁，也能成為讓更多人願意開始閱讀文物的入口。"),
        new("DISCOVERY", "資料判讀", "CUSTOM", "我希望每個人都能在自己的速度裡補資料，但不要因為速度不同就失去可回查的脈絡", "有人先看圖，有人先查來源，有人先參加活動或玩遊戲。只要作品和資料關聯可靠，每種速度都能在之後回到同一個內容繼續，系統就能容納不同的閱讀方式。"),
        new("QUESTION", "開放提問", "CUSTOM", "我把最後一個問題留給未來：哪一條從社群走回文物的路，會成為你最常使用的路", "可能是活動後的回顧、遊戲後的結果、商城裡的商品留言，或一次參觀留下的照片和心得。不同入口都值得被保留，只要讀者能清楚知道自己現在在哪裡、下一步可以去哪裡。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "這批內容最後想完成的，不是把社群寫得完美，而是讓它真的能承接下一個人的經驗", "下一個人可以在正館或南院留下觀看，也可以參加活動、玩一回合遊戲、買一件縮小複製品，再把自己的心得放回社群。資料邊界清楚、文字自然，內容就能持續長大而不失去方向。"),
        new("CATALOG", "閱讀方法", "CUSTOM", "我希望每一筆資料都能回答三件事：它是什麼、從哪裡來、下一步能去哪裡", "作品名稱和分類讓人知道它是什麼，來源和關聯讓人知道從哪裡來，圖鑑、活動、遊戲、社群或商城入口則提供下一步。這套簡單的方向感，比把所有資訊一次攤在眼前更容易使用。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我想把遊戲的樂趣留在結果裡，也把資料的可靠留在回查路上", "回答可以有創意，投票可以有競爭，結算可以有排名，但揭曉後仍然要能回到對應的文物和題庫。這樣遊戲不會因為有趣就失去內容，也不會因為資料正確就變得只剩考試。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我希望一個活動從社群被看見，到地圖和文字地址幫助到場，再回到貼文分享，整段經驗都能被理解", "地圖提供直覺的方向，文字地址提供穩定的確認，活動頁維護報名和狀態，社群貼文保留參加者的故事。每個部分都簡單做好自己的事，就能形成完整而不複雜的參加流程。"),
        new("GUIDE", "整理方法", "CUSTOM", "我會把這批文字交給後續開發時使用，但仍然讓每篇保留自己的故事和語氣", "API 和資料表可以用穩定的識別碼互相連結，使用者看到的則是清楚的名稱、日期、地點、作品和內容。這樣組員有可靠的開發基礎，未來前台也能直接把真實脈絡呈現出來。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我希望商城的留言讓人感覺是在和其他收藏者交換經驗，不是在看另一段商品廣告", "有人分享擺放位置，有人分享和圖鑑對照的方法，有人說明尺寸是否適合自己的空間。這些內容都來自收到後的真實觀察，簡短但有差異，才會讓留言區值得回來看。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我想把來源、關聯和人話整理同時做好，讓內容既能維護，也能真正被讀懂", "內部的識別和資料邊界要穩定，對外的名稱和文章則要自然。這樣不需要在 UI 上露出鍵值，也不需要讓社群貼文變成資料庫說明，讀者能讀，組員也能維護。"),
        new("QUESTION", "開放提問", "CUSTOM", "我想請大家一起想想，當一篇文章很長時，哪個資訊最能幫你決定要不要繼續讀", "對我來說是清楚的作品名稱、真實的參觀情境和一個可以回查的問題；對別人可能是活動地點、遊戲結果或商品尺寸。只要入口說清楚，長文就不會讓人一開始找不到方向。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我想把社群做成一個內容會互相照亮的地方，但不讓任何資料被迫扮演不屬於自己的角色", "文物是文物，活動是活動，遊戲是遊戲，商品是商品，社群則保存人如何遇到它們。彼此關聯讓閱讀延伸，清楚邊界讓資料可信，這樣豐富度和真實感才能同時存在。"),
        new("CATALOG", "資料判讀", "CUSTOM", "我最後確認的不是每件作品都有人討論，而是每一篇討論都真的有理由連到它所談的內容", "有些作品適合深入討論，有些只適合保留在圖鑑裡等待下一次閱讀；社群不需要替全部資料安排相同的故事。讓連結跟著真實經驗出現，展示才會顯得自然，也不會失去可信度。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望玩家在遊戲裡建立的是自己的觀察方法，而不是只記住一批正確答案", "回合結果把回答、票數和文物放在一起，玩家就能檢查自己怎麼走到答案。長期排名再補上穩定的回看方向，遊戲會變成持續練習，而不是一場過後就歸零的測驗。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我希望活動內容可以讓人先產生興趣，再用可靠的資料完成真正的參加", "一篇有現場感的分享是好的開始，地圖和文字地址讓人知道怎麼到，正式活動資料讓人確認時間和名額，活動後貼文再把經驗留下。整條路清楚，使用者才真的有辦法參加。"),
        new("GUIDE", "整理方法", "CUSTOM", "我會把這次最後的結論留在文章裡：自然的內容和可靠的資料，可以一起做得好", "不用把社群文章寫成抽象功能說明，也不用為了像真人而放棄作品、活動、遊戲和商品的真實關聯。把真的發生過的事寫長、寫清楚，資料對得上，網站就會有可以展示也能繼續使用的內容。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我希望每一個商品評價都能讓人多知道一點實際展示，也多想看一點原作資料", "留言不必複雜，說明收到後的尺寸、光線、位置和收藏理由就很有幫助。再把它和對應作品連起來，商城的短短一段話就能成為下一段文化閱讀的起點。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我會把這批分享的最後一句留給可以繼續查的地方，而不是一句空泛的總結", "可能是回到圖鑑、再看一次展廳、確認活動資料、查看遊戲歷程，或比較另一件作品。文章有具體下一步，讀者才有機會把一次閱讀變成下一次真正的行動。"),
        new("QUESTION", "開放提問", "CUSTOM", "如果你有更好的觀察順序或資料來源，歡迎從一個具體的作品細節開始告訴我", "我會保留自己目前的觀察和限制，也希望收到能回查的補充。社群的價值不是把所有人變成同一個答案，而是讓不同經驗在清楚的作品和資料上相遇。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我希望這些文章讓人感覺到，文物可以從很多入口被認識，但每個入口都能回到真實內容", "可以在正館看見它，在南院活動裡聽到它，在遊戲回合裡猜到它，在商城展示它，再回到圖鑑查證它。入口越多，越需要關聯對得上；只要這點做到，內容就會越來越豐富而不凌亂。"),
        new("CATALOG", "觀看順序", "CUSTOM", "我把一件作品的故事走完一次：先遇見、再觀察、後查證，最後留下下一次想看的地方", "這個順序不是所有人都一樣，但它讓我知道一次參觀如何變成一篇文章，也知道文章如何接回圖鑑和未來的行程。把過程留下來，內容才不只是結果，而是可以被別人參考的經驗。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望最後的遊戲資料像一份有排名的學習筆記，能看見競賽也能看見自己的改變", "每回合有回答和票數，整場有玩家和名次，長期還能看出哪些題型容易失誤。這些資訊不需要改變遊戲本身的簡單規則，卻能讓玩家在結束後得到更完整的回饋。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我覺得一場活動真正完成，是有人看見、有人參加，也有人在結束後願意把經驗留下", "官方活動資料維護可以確認的內容，社群貼文承接真實的參與過程，地圖和文字地址降低到場的門檻。三者接起來，活動才會從後台的一筆資料變成使用者真的能走完的經驗。"),
        new("GUIDE", "整理方法", "CUSTOM", "我會在最後保留簡單的規則，讓後續內容繼續增加時仍然好讀、好查、好維護", "文章從真實經驗開始，作品和活動關聯要對得上，來源與推測要分開，UI 不露出內部鍵值，遊戲和商品也要留下能回看的結果。規則不多，但足以支撐一個有規模的展示。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我希望商城最後呈現的是很多不同收藏者的實際生活，而不只是一排規格和價格", "有人把展示品放在書桌旁，有人和參觀照片並排，有人收到後回頭研究原作，也有人覺得先閱讀再決定比較適合自己。商品評價讓這些差異留下來，商城才會和社群一樣有人的內容。"),
        new("DISCOVERY", "資料判讀", "CUSTOM", "我把每一篇文章寫到能對應真實內容的程度，也把不能確認的地方明白留著", "這樣讀者看到的是有細節的文章，不是用很多抽象句子裝飾出來的完整感。作品、地點、活動、遊戲和商品只在真的相關時互相連結，內容多樣卻不會彼此失真。"),
        new("QUESTION", "開放提問", "CUSTOM", "這篇最後想邀請大家分享：你會從哪一個真實經驗開始，把文物帶進自己的日常", "可能是一趟到館行程、一張照片、一場活動、一回合遊戲，或一件放在書架旁的縮小複製品。只要從具體經驗開始，社群就能一起把資料、問題和下一步慢慢接起來。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我想把最後的社群留成一個有規模、但仍然看得見每個人不同經驗的地方", "文章可以很多，分類可以清楚，作品、活動、遊戲和商城可以互相連結；但每一篇仍然要有自己的情境、觀察和下一步。這樣組員和評審往下看時，會看到完整度，也會看到真的有人在使用這些內容。"),
        new("CATALOG", "閱讀方法", "CUSTOM", "我現在知道，最好的內容不是把所有答案一次交出去，而是讓人知道下一步去哪裡找", "一個名稱、一個來源、一張影像、一個地點或一段回合結果，都可以成為下一步。入口清楚、資料可靠，讀者就能依自己的速度繼續探索，文章也不必假裝自己已經涵蓋全部。"),
        new("GAME", "遊戲回顧", "CUSTOM", "我希望每場遊戲結束時，玩家除了知道誰勝出，也知道自己下一次可以怎麼看得更好", "回合歷程和玩家排名讓結果有脈絡，對應文物讓回顧有資料，回答與票數讓判斷有證據。這樣遊戲仍然簡單好玩，卻不會讓人玩完後只剩下一個沒有內容的數字。"),
        new("EVENTS", "活動交流", "TEMPLATE", "我希望活動內容最後能讓人自然完成一段路：看見活動、確認地址、報名參加、回來分享", "貼文提供興趣和現場故事，正式活動資料提供可靠的參加條件，地圖和文字地址照顧不同使用習慣。活動結束後再回到社群，內容就有完整的前後脈絡，也更方便未來前台呈現。"),
        new("GUIDE", "整理方法", "CUSTOM", "我會把這批內容當成真正要交給前台使用的資料，而不是一次展示完就丟掉的文字", "因此每篇都要有自然標題、清楚分類、可回查的關聯和足夠不同的內容。內部識別碼留給系統管理，讀者看到的是文物、活動、地點、遊戲和收藏者自己的故事，這才是可以長期使用的展示資料。"),
        new("REVIEW", "收藏心得", "CUSTOM", "我希望商城的留言和評價讓人知道商品適不適合自己，也讓人知道它為什麼值得被放進這個網站", "實際展示條件、尺寸感和原作關聯能幫助做決定，會員的收藏理由則補上商品規格之外的生活脈絡。留言區不必複雜，但要讓人能留下真正使用過後的觀察。"),
        new("DISCOVERY", "來源查證", "CUSTOM", "我會把每次新增內容的真實關聯確認好，再讓文字自然地說出來", "不把所有文物都安排成討論主角，不把所有商品寫成同一種心得，也不把活動和遊戲硬塞進無關文章。關聯有理由，內容就能很多樣；文字有人味，展示才不會像批次產生的資料。"),
        new("QUESTION", "開放提問", "CUSTOM", "如果你願意，請把你的答案、疑問或收藏理由說成一段別人看得懂的經驗", "不用直接貼出內部欄位或識別碼，也不用把文章寫成系統說明。只要交代作品、地點、回合、商品或當時的觀看條件，其他人就能理解、回應，並從正確的資料入口繼續。"),
        new("GENERAL", "閱讀心得", "CUSTOM", "我希望最後的社群是一個真的有故事、有資料、有活動、有遊戲和有收藏經驗的內容入口", "每一篇文章都從一件具體的事情開始，互相連結時不失去自己的邊界，讀者也不用理解內部鍵值才能使用。內容夠豐富，關聯夠可靠，未來前台就能從這裡開始長出完整的閱讀體驗。")
    ];

    // 目前工具可產生的展示貼文上限為 512 篇；固定素材數量高於這個上限，
    // 因此同一輪產生資料時不需要循環重用文章，也不會把隨機片段拼成不自然的內容。
    private static readonly IReadOnlyList<CommunityStory> CommunityStories =
        CommunityStoriesPartOne.Concat(CommunityStoriesPartTwo).ToArray();

    public static async Task GenerateAsync(
        string connection,
        int postCount,
        int orderCount,
        int seed,
        int activityDays,
        int pointTransactionCount,
        int keyTransactionCount,
        int keyProgressTransactionCount)
    {
        var options = new DbContextOptionsBuilder<QmahDbContext>()
            .UseSqlServer(connection)
            .Options;

        await using var db = new QmahDbContext(options);
        if (!await db.Database.CanConnectAsync())
            throw new InvalidOperationException("無法連線到 QMAH。請先建立同版本的本機資料庫。");

        var users = await LoadShowcaseUsersAsync(db);
        if (users.Count < 20)
            throw new InvalidOperationException("展示資料需要至少 20 個 @qmah.local 或 @qmah.test 會員，請先執行 seed-showcase-users。");

        var artifacts = await db.Artifacts
            .AsNoTracking()
            .Include(artifact => artifact.Category)
            .Include(artifact => artifact.EraBucket)
            .Where(artifact => artifact.IsActive)
            .OrderBy(artifact => artifact.ArtifactRef)
            .ToListAsync();
        if (artifacts.Count == 0)
            throw new InvalidOperationException("找不到可用文物，無法建立與圖鑑關聯的社群資料。");

        var events = await db.Events
            .AsNoTracking()
            .OrderBy(eventData => eventData.StartAt)
            .ThenBy(eventData => eventData.Title)
            .ToListAsync();
        var gameRounds = await db.GameRounds
            .AsNoTracking()
            .Include(round => round.Room)
            .Include(round => round.Artifact)
            .OrderBy(round => round.StartedAt)
            .ThenBy(round => round.RoundNumber)
            .ToListAsync();

        var products = (await db.Products
                .AsNoTracking()
                .Include(product => product.Artifact)
                .Where(product => product.ArtifactId != null && product.IsActive)
                .ToListAsync())
            .Where(product => product.Artifact is not null
                && product.ExternalRef?.StartsWith("artifact-", StringComparison.OrdinalIgnoreCase) == true
                && product.Name.Contains("縮小複製品", StringComparison.Ordinal))
            .OrderBy(product => product.ExternalRef, StringComparer.Ordinal)
            .ThenBy(product => product.Id)
            .ToList();
        if (products.Count == 0)
            throw new InvalidOperationException("找不到與文物關聯的縮小複製品商品，請先執行 ArtifactProductGenerator。");

        await using var transaction = await db.Database.BeginTransactionAsync();

        var postResult = await UpsertPostsAsync(db, users, artifacts, events, gameRounds, postCount, seed);
        var commentCount = await UpsertCommentsAsync(db, users, postResult, seed);
        var orderResult = await UpsertOrdersAsync(db, users, products, orderCount, seed);
        var reviewCount = await UpsertProductReviewsAsync(db, users, products, orderCount, seed);
        var ledgerResult = await ShowcaseLedgerCommands.GenerateAsync(
            db,
            activityDays,
            pointTransactionCount,
            keyTransactionCount,
            keyProgressTransactionCount,
            seed);

        await db.SaveChangesAsync();
        await transaction.CommitAsync();

        Console.WriteLine(
            $"SHOWCASE_GENERATED|posts:{postResult.Count}|artifact-posts:{postResult.ArtifactPostCount}|game-posts:{postResult.GamePostCount}|community-posts:{postResult.CommunityPostCount}|event-posts:{postResult.EventPostCount}|artifact-linked-posts:{postResult.ArtifactLinkedCount}|official-announcements:{postResult.OfficialAnnouncementCount}|comments:{commentCount}|orders:{orderResult.Count}|order-details:{orderResult.DetailCount}|miniature-orders:{orderResult.MiniatureOrderCount}|reviews:{reviewCount}|daily-activities:{ledgerResult.DailyActivityCount}|login-activities:{ledgerResult.LoginActivityCount}|check-in-activities:{ledgerResult.CheckInActivityCount}|point-transactions:{ledgerResult.PointTransactionCount}|key-transactions:{ledgerResult.KeyTransactionCount}|key-progress-transactions:{ledgerResult.KeyProgressTransactionCount}|login-achievements:{ledgerResult.LoginAchievementCount}");
    }

    private static async Task<IReadOnlyList<ShowcaseUser>> LoadShowcaseUsersAsync(QmahDbContext db)
    {
        var users = await db.Users
            .AsNoTracking()
            .Where(user => user.Status == "ACTIVE"
                && user.Email != null
                && (user.Email.EndsWith("@qmah.local") || user.Email.EndsWith("@qmah.test")))
            .OrderBy(user => user.Email)
            .ToListAsync();
        var profiles = await db.UserProfiles
            .AsNoTracking()
            .Where(profile => users.Select(user => user.Id).Contains(profile.UserId))
            .ToDictionaryAsync(profile => profile.UserId);

        return users
            .Select(user => new ShowcaseUser(
                user.Id,
                profiles.TryGetValue(user.Id, out var profile)
                    && !string.IsNullOrWhiteSpace(profile.Nickname)
                    ? profile.Nickname.Trim()
                    : user.Email!.Split('@')[0],
                user.Email!))
            .ToArray();
    }

    private static async Task<PostGenerationResult> UpsertPostsAsync(
        QmahDbContext db,
        IReadOnlyList<ShowcaseUser> users,
        IReadOnlyList<Artifact> artifacts,
        IReadOnlyList<Event> events,
        IReadOnlyList<GameRound> gameRounds,
        int postCount,
        int seed)
    {
        var announcementCount = Math.Min(postCount, Math.Clamp(postCount / 9, 8, 32));
        var remainingCount = postCount - announcementCount;
        // 只讓約三分之一的貼文成為文物專題，其他內容才有空間呈現遊戲、活動、公告與一般交流。
        // 這也刻意不把 256 件文物全部配上一則討論，避免展示資料看起來像為了湊數而生成。
        var artifactPostCount = Math.Min(artifacts.Count, Math.Min(remainingCount, postCount / 3));
        remainingCount -= artifactPostCount;
        var eventPostCount = Math.Min(events.Count, Math.Min(remainingCount, postCount / 36));
        remainingCount -= eventPostCount;
        var gamePostCount = Math.Min(64, Math.Min(remainingCount, postCount / 7));
        remainingCount -= gamePostCount;
        var communityPostCount = remainingCount;
        var orderedArtifacts = artifacts
            .OrderBy(artifact => StableNumber($"artifact-order:{seed}:{artifact.ArtifactRef}"))
            .Take(artifactPostCount)
            .ToArray();
        var generatedIds = Enumerable.Range(1, postCount)
            .Select(index => StableGuid($"{GeneratedPostKey}:{index}"))
            .ToArray();
        var existing = await db.SocialPosts
            .Where(post => generatedIds.Contains(post.Id))
            .ToDictionaryAsync(post => post.Id);
        var existingEventPosts = await db.SocialPosts
            .Where(post => post.EventId != null)
            .ToDictionaryAsync(post => post.EventId!.Value);
        var posts = new List<GeneratedPost>(postCount);
        var officialUser = users.FirstOrDefault(user => user.Email.StartsWith("admin@", StringComparison.OrdinalIgnoreCase))
            ?? users.First();
        var repeatedArtifactNames = artifacts
            .GroupBy(artifact => artifact.Name.Trim(), StringComparer.OrdinalIgnoreCase)
            .Where(group => group.Count() > 1)
            .Select(group => group.Key)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);

        for (var index = 1; index <= postCount; index++)
        {
            var id = generatedIds[index - 1];
            var kind = index <= artifactPostCount
                ? GeneratedPostKind.Artifact
                : index <= artifactPostCount + eventPostCount
                    ? GeneratedPostKind.Event
                    : index <= artifactPostCount + eventPostCount + gamePostCount
                        ? GeneratedPostKind.Game
            : index <= postCount - announcementCount
                ? GeneratedPostKind.Community
                : GeneratedPostKind.Announcement;
            var communityOrdinal = kind == GeneratedPostKind.Community
                ? index - artifactPostCount - eventPostCount - gamePostCount
                : 0;
            if (kind == GeneratedPostKind.Community
                && (communityOrdinal < 1 || communityOrdinal > CommunityStories.Count))
            {
                throw new InvalidOperationException(
                    $"社群展示素材不足，無法產生第 {communityOrdinal} 篇不重複貼文。請先補充 CommunityStories。");
            }
            var communityStory = kind == GeneratedPostKind.Community
                ? CommunityStories[communityOrdinal - 1]
                : null;
            var artifact = kind == GeneratedPostKind.Artifact
                ? orderedArtifacts[index - 1]
                : kind == GeneratedPostKind.Game && gameRounds.Count > 0 && index % 3 == 0
                    ? gameRounds[(int)(StableNumber($"game-artifact:{seed}:{index}") % (ulong)gameRounds.Count)].Artifact
                    : communityStory is not null && CanLinkArtifact(communityStory) && communityOrdinal % 5 == 0
                        ? artifacts[(int)(StableNumber($"community-artifact:{seed}:{index}") % (ulong)artifacts.Count)]
                        : null;
            var eventData = kind == GeneratedPostKind.Event
                ? events[index - artifactPostCount - 1]
                : null;
            var topic = PostTopics[(int)(StableNumber($"post-topic:{seed}:{index}") % (ulong)PostTopics.Count)];
            var eventOrganizer = eventData is null
                ? null
                : users.FirstOrDefault(user => user.Id == eventData.OrganizerUserId);
            var author = kind == GeneratedPostKind.Announcement
                ? officialUser
                : kind == GeneratedPostKind.Event
                    ? eventOrganizer ?? (eventData?.EventType == "OFFICIAL"
                        ? officialUser
                        : users[(int)(StableNumber($"post-author:{seed}:{index}") % (ulong)users.Count)])
                    : users[(int)(StableNumber($"post-author:{seed}:{index}") % (ulong)users.Count)];
            var createdAt = DateTime.UtcNow.Date
                .AddDays(-((index * 3 + (index % 7) * 5) % 360))
                .AddHours(index % 12);
            var location = eventData is not null && !string.IsNullOrWhiteSpace(eventData.Location)
                ? new ShowcaseLocation(eventData.Location!, eventData.Latitude, eventData.Longitude)
                : communityStory is not null && CanLinkLocation(communityStory) && communityOrdinal % 6 == 0
                    ? Locations[(int)(StableNumber($"community-location:{seed}:{index}") % (ulong)Locations.Count)]
                    : artifact is null || index % 4 != 0
                    ? null
                    : Locations[(int)(StableNumber($"post-location:{seed}:{index}") % (ulong)Locations.Count)];
            var draft = kind switch
            {
                GeneratedPostKind.Artifact => BuildArtifactPost(
                    artifact!,
                    topic,
                    index,
                    seed,
                    repeatedArtifactNames.Contains(artifact!.Name.Trim())),
                GeneratedPostKind.Event => BuildEventPost(eventData!),
                GeneratedPostKind.Game => BuildGamePost(gameRounds, artifact, index, seed),
                GeneratedPostKind.Community => BuildCommunityPost(communityStory!, artifact, location),
                _ => BuildAnnouncement(index - (postCount - announcementCount), postCount, seed)
            };

            var current = existing.TryGetValue(id, out var generatedPost)
                ? generatedPost
                : eventData is not null && existingEventPosts.TryGetValue(eventData.Id, out var eventPost)
                    ? eventPost
                    : null;
            var post = current ?? new SocialPost { Id = id };
            post.BoardCode = draft.BoardCode;
            post.UserId = author.Id;
            post.ArtifactId = artifact?.Id;
            post.EventId = eventData?.Id;
            post.PostType = draft.PostType;
            post.PublisherType = draft.PublisherType;
            post.ContentMode = draft.ContentMode;
            post.Title = Trim(draft.Title, 150);
            post.Content = Trim(draft.Content, 4000);
            post.LocationName = location?.Name;
            post.Latitude = location?.Latitude;
            post.Longitude = location?.Longitude;
            post.Status = index % 67 == 0 ? "DELETED" : index % 41 == 0 ? "HIDDEN" : "PUBLISHED";
            post.CreatedAt = createdAt;
            post.UpdatedAt = createdAt.AddMinutes(18 + (index % 77));

            if (current is null)
                db.SocialPosts.Add(post);
            posts.Add(new GeneratedPost(index, post, artifact, eventData, kind, draft.TopicLabel));
        }

        return new PostGenerationResult(
            posts,
            artifactPostCount,
            gamePostCount,
            communityPostCount,
            eventPostCount,
            announcementCount,
            posts.Count(post => post.Post.ArtifactId is not null));
    }

    private static async Task<int> UpsertCommentsAsync(
        QmahDbContext db,
        IReadOnlyList<ShowcaseUser> users,
        PostGenerationResult postResult,
        int seed)
    {
        var commentIds = postResult.Posts
            .SelectMany(post => Enumerable.Range(1, GetCommentCount(post.Index))
                .Select(slot => StableGuid($"{GeneratedCommentKey}:{post.Index}:{slot}")))
            .ToArray();
        var existing = await db.SocialComments
            .Where(comment => commentIds.Contains(comment.Id))
            .ToDictionaryAsync(comment => comment.Id);

        var commentCount = 0;
        foreach (var generatedPost in postResult.Posts)
        {
            var firstId = StableGuid($"{GeneratedCommentKey}:{generatedPost.Index}:1");
            var createdAt = generatedPost.Post.CreatedAt.AddMinutes(24 + generatedPost.Index % 35);

            for (var slot = 1; slot <= GetCommentCount(generatedPost.Index); slot++)
            {
                var commentId = StableGuid($"{GeneratedCommentKey}:{generatedPost.Index}:{slot}");
                var author = users[(int)(StableNumber($"comment-author:{seed}:{generatedPost.Index}:{slot}") % (ulong)users.Count)];
                var comment = existing.TryGetValue(commentId, out var current)
                    ? current
                    : new SocialComment { Id = commentId };
                comment.PostId = generatedPost.Post.Id;
                comment.ParentCommentId = slot == 1 ? null : firstId;
                comment.UserId = author.Id;
                comment.Content = Trim(BuildComment(generatedPost, generatedPost.Index, slot), 2000);
                comment.Status = generatedPost.Post.Status == "DELETED" ? "HIDDEN" : "PUBLISHED";
                comment.CreatedAt = createdAt.AddMinutes((slot - 1) * 9);
                comment.UpdatedAt = comment.CreatedAt;
                if (current is null)
                    db.SocialComments.Add(comment);

                commentCount++;
            }
        }

        return commentCount;
    }

    private static async Task<OrderGenerationResult> UpsertOrdersAsync(
        QmahDbContext db,
        IReadOnlyList<ShowcaseUser> users,
        IReadOnlyList<Product> products,
        int orderCount,
        int seed)
    {
        var orderIds = Enumerable.Range(1, orderCount)
            .Select(index => StableGuid($"{GeneratedOrderKey}:{index}"))
            .ToArray();
        var existingOrders = await db.StoreOrders
            .Where(order => orderIds.Contains(order.Id))
            .ToDictionaryAsync(order => order.Id);
        var existingDetails = await db.OrderDetails
            .Where(detail => orderIds.Contains(detail.OrderId))
            .ToListAsync();
        var existingPayments = await db.Payments
            .Where(payment => orderIds.Contains(payment.OrderId))
            .ToDictionaryAsync(payment => payment.OrderId);
        var detailCount = 0;
        var miniatureOrderCount = 0;

        for (var index = 1; index <= orderCount; index++)
        {
            var orderId = orderIds[index - 1];
            var member = users[(int)(StableNumber($"order-member:{seed}:{index}") % (ulong)users.Count)];
            var createdAt = DateTime.UtcNow.Date
                .AddDays(-((index * 7 + (index % 5) * 3) % 360))
                .AddHours(-(index % 9));
            var status = OrderStatuses[(index - 1) % OrderStatuses.Length];
            var address = DeliveryAddresses[(index - 1) % DeliveryAddresses.Count];
            var selectedProducts = SelectProducts(products, index, seed);
            var details = selectedProducts
                .Select((product, line) =>
                {
                    var quantity = 1 + (int)(StableNumber($"order-quantity:{seed}:{index}:{line}") % 3);
                    return new OrderDetail
                    {
                        Id = StableGuid($"{GeneratedOrderKey}:{index}:detail:{line + 1}"),
                        OrderId = orderId,
                        ProductId = product.Id,
                        ProductNameSnapshot = product.Name,
                        UnitPrice = product.Price,
                        Quantity = quantity,
                        LineTotal = product.Price * quantity
                    };
                })
                .ToList();
            var subtotal = details.Sum(detail => detail.LineTotal);
            var order = existingOrders.TryGetValue(orderId, out var current)
                ? current
                : new StoreOrder { Id = orderId };
            order.OrderNo = $"QMAH-GEN-{index:0000}";
            order.UserId = member.Id;
            order.UserCouponId = null;
            order.Status = status;
            order.Subtotal = subtotal;
            order.DiscountAmount = 0;
            order.PointsUsed = 0;
            order.TotalAmount = subtotal;
            order.RecipientName = Trim($"{member.DisplayName} 收", 80);
            order.RecipientPhone = $"09{((index * 137 + 88000000) % 100000000):00000000}";
            order.ShippingPostalCode = address.PostalCode;
            order.ShippingCity = address.City;
            order.ShippingDistrict = address.District;
            order.ShippingAddressLine = address.AddressLine;
            order.CreatedAt = createdAt;
            order.PaidAt = status is "PENDING_PAYMENT" or "CANCELLED"
                ? null
                : createdAt.AddMinutes(5);
            order.CancelledAt = status == "CANCELLED" ? createdAt.AddMinutes(8) : null;
            if (current is null)
                db.StoreOrders.Add(order);

            var oldDetails = existingDetails.Where(detail => detail.OrderId == orderId).ToArray();
            if (oldDetails.Length > 0)
                db.OrderDetails.RemoveRange(oldDetails);
            db.OrderDetails.AddRange(details);

            var paymentStatus = status switch
            {
                "PENDING_PAYMENT" => "PENDING",
                "CANCELLED" => "FAILED",
                _ => "PAID"
            };
            var payment = existingPayments.TryGetValue(orderId, out var currentPayment)
                ? currentPayment
                : new Payment { Id = StableGuid($"{GeneratedOrderKey}:{index}:payment") };
            payment.OrderId = orderId;
            payment.MerchantTradeNo = $"QMAH-GP-{index:000000}";
            payment.EcpayTradeNo = paymentStatus == "PAID" ? $"QMAH-GEN-{index:000000}" : null;
            payment.Amount = subtotal;
            payment.Status = paymentStatus;
            payment.RtnCode = paymentStatus switch
            {
                "PAID" => 1,
                "FAILED" => 0,
                _ => null
            };
            payment.RtnMsg = paymentStatus switch
            {
                "PAID" => "付款成功",
                "FAILED" => "付款未完成",
                _ => null
            };
            payment.PaymentType = PaymentTypes[(index - 1) % PaymentTypes.Length];
            payment.CallbackReceivedAt = paymentStatus == "PENDING" ? null : createdAt.AddMinutes(5);
            payment.CreatedAt = createdAt;
            if (currentPayment is null)
                db.Payments.Add(payment);

            detailCount += details.Count;
            if (details.All(detail => detail.ProductNameSnapshot.Contains("縮小複製品", StringComparison.Ordinal)))
                miniatureOrderCount++;
        }

        return new OrderGenerationResult(orderCount, detailCount, miniatureOrderCount);
    }

    private static async Task<int> UpsertProductReviewsAsync(
        QmahDbContext db,
        IReadOnlyList<ShowcaseUser> users,
        IReadOnlyList<Product> products,
        int orderCount,
        int seed)
    {
        // 評價者必須先在同一批展示訂單中買過該商品，避免出現評價內容與訂單資料對不起來的假關聯。
        var purchasersByProduct = new Dictionary<Guid, List<Guid>>();
        for (var orderIndex = 1; orderIndex <= orderCount; orderIndex++)
        {
            var status = OrderStatuses[(orderIndex - 1) % OrderStatuses.Length];
            if (status is "PENDING_PAYMENT" or "CANCELLED")
                continue;

            var member = users[(int)(StableNumber($"order-member:{seed}:{orderIndex}") % (ulong)users.Count)];
            foreach (var product in SelectProducts(products, orderIndex, seed))
            {
                if (!purchasersByProduct.TryGetValue(product.Id, out var purchaserIds))
                {
                    purchaserIds = [];
                    purchasersByProduct[product.Id] = purchaserIds;
                }

                if (!purchaserIds.Contains(member.Id))
                    purchaserIds.Add(member.Id);
            }
        }

        var requestedReviewCount = Math.Min(products.Count, Math.Max(24, orderCount * 3 / 5));
        var reviewProducts = products
            .Where(product => purchasersByProduct.ContainsKey(product.Id))
            .Take(requestedReviewCount)
            .ToArray();
        var reviewCount = reviewProducts.Length;
        var reviewIds = Enumerable.Range(1, reviewCount)
            .Select(index => StableGuid($"{GeneratedReviewKey}:{index}"))
            .ToArray();
        var existing = await db.ProductReviews
            .Where(review => reviewIds.Contains(review.Id))
            .ToDictionaryAsync(review => review.Id);

        for (var index = 1; index <= reviewCount; index++)
        {
            var product = reviewProducts[index - 1];
            var purchaserIds = purchasersByProduct[product.Id];
            var memberId = purchaserIds[(int)(StableNumber($"review-member:{seed}:{index}") % (ulong)purchaserIds.Count)];
            var reviewId = reviewIds[index - 1];
            var createdAt = DateTime.UtcNow.Date
                .AddDays(-((index * 11 + (index % 6) * 4) % 330))
                .AddHours(index % 13);
            var review = existing.TryGetValue(reviewId, out var current)
                ? current
                : new ProductReview { Id = reviewId };
            review.ProductId = product.Id;
            review.UserId = memberId;
            review.Rating = (byte)(1 + (int)(StableNumber($"review-rating:{seed}:{index}") % 5));
            review.Content = Trim(
                ProductReviewTexts[(index - 1) % ProductReviewTexts.Count]
                    .Replace("{product}", product.Name.Trim(), StringComparison.Ordinal)
                    .Replace("{artifact}", product.Artifact?.Name.Trim() ?? "這件文物", StringComparison.Ordinal),
                1000);
            review.Status = index % 29 == 0 ? "DELETED" : index % 17 == 0 ? "HIDDEN" : "PUBLISHED";
            review.CreatedAt = createdAt;
            review.UpdatedAt = createdAt.AddMinutes(12 + index % 48);
            if (current is null)
                db.ProductReviews.Add(review);
        }

        return reviewCount;
    }

    private static IReadOnlyList<Product> SelectProducts(
        IReadOnlyList<Product> products,
        int orderIndex,
        int seed)
    {
        var lineCount = orderIndex % 7 == 0 ? 3 : orderIndex % 3 == 0 ? 2 : 1;
        var result = new List<Product>(lineCount);
        var used = new HashSet<Guid>();
        for (var line = 0; line < lineCount; line++)
        {
            var start = (int)(StableNumber($"order-product:{seed}:{orderIndex}:{line}") % (ulong)products.Count);
            for (var offset = 0; offset < products.Count; offset++)
            {
                var product = products[(start + offset) % products.Count];
                if (used.Add(product.Id))
                {
                    result.Add(product);
                    break;
                }
            }
        }

        return result;
    }

    private static GeneratedPostDraft BuildArtifactPost(
