    {
        var name = artifact.Name.Trim();
        var category = artifact.Category.Name.Trim();
        var era = string.IsNullOrWhiteSpace(artifact.EraTextOriginal)
            ? artifact.EraBucket.Name.Trim()
            : artifact.EraTextOriginal.Trim();
        var size = string.IsNullOrWhiteSpace(artifact.SizeText) ? "官方資料未提供" : artifact.SizeText.Trim();
        var description = string.IsNullOrWhiteSpace(artifact.Description)
            ? "目前圖鑑沒有提供較長的原始說明。"
            : Trim(NormalizeWhitespace(artifact.Description), 260);
        var variant = (int)(StableNumber($"post-variant:{seed}:{index}") % 5);
