                _ => $"我如何把{name}的大小寫進觀察筆記"
            },
            "紋飾細節" => variant switch
            {
                0 => $"放大{name}後，我先看到哪一段紋樣",
                1 => $"{name}的紋飾在轉角處有什麼變化",
                2 => $"不要只記住顏色：{name}的表面細節",
