                1 => $"{name}的資料如何保留版本與查閱日期",
                2 => $"我把{name}的觀察和原文說明分開",
                3 => $"{name}的查證紀錄不要只剩一句摘要",
                _ => $"從{name}開始練習可回查的文物筆記"
            },
            "近看心得" => variant switch
            {
                0 => $"靠近看{name}後，印象改變最多的地方",
                1 => $"{name}不是只靠第一眼就能看完",
                2 => $"我在{name}上停留最久的細節",
                3 => $"看{name}的時候，哪個局部最值得放大",
                _ => $"{name}讓我重新調整觀看距離"
            },
            "展陳想像" => variant switch
            {
                0 => $"如果把{name}放進展示櫃，我會怎麼安排光線",
                1 => $"{name}適合從正面還是側面開始看",
                2 => $"從展示角度想像{name}的觀看動線",
                3 => $"{name}的背景留白會影響什麼",
                _ => $"我會怎麼向第一次看到{name}的人介紹"
            },
            "光線影響" => variant switch
            {
                0 => $"不同光線讓{name}出現哪些差異",
                1 => $"看{name}的照片時如何避開反光誤導",
                2 => $"{name}的明暗變化不一定是材質變化",
                3 => $"把{name}的影像條件也放進筆記",
                _ => $"我想用另一個角度重新拍{name}"
            },
            "第一次認識" => variant switch
            {
                0 => $"第一次認識{name}，可以先看這四個欄位",
                1 => $"如果只用一句話介紹{name}，我會怎麼說",
                2 => $"{name}適合拿來練習哪一種觀察",
                3 => $"我給第一次看{name}的人一個閱讀順序",
                _ => $"從{name}開始建立文物閱讀習慣"
            },
            "閱讀心得" => variant switch
            {
                0 => $"讀完{name}的資料後，我改變了哪個想法",
                1 => $"{name}的說明文字和影像如何互相補足",
                2 => $"我在{name}的資料裡找到的一個小轉折",
                3 => $"{name}提醒我不要忽略哪些普通欄位",
                _ => $"把{name}讀慢一點，反而看見更多"
            },
            _ => variant switch
            {
                0 => $"{name}的收藏脈絡可以從哪裡開始",
