        var content = topic.Label switch
        {
            "資料判讀" or "同類比較" or "用途想像" or "年代範圍" =>
                $"整理「{name}」時，我先把目前能直接從圖像與圖鑑欄位確認的內容分開記下來，再標出仍需要來源或同類作品才能確認的部分。這樣做的好處是，討論不會因為一句過度肯定的描述而失去可以修正的空間。\n\n目前資料記載：分類為「{category}」，年代原文為「{era}」，尺寸為「{size}」。原始說明提到：{description}\n\n我想請大家一起看的，是「{topic.Label}」這個角度。若有不同解讀，也希望能指出對應的影像位置、欄位或參考來源，讓後續比較可以回到同一份資料。",
            "整理方法" or "查證筆記" =>
                $"我把「{name}」的整理分成三層：先留下影像中確定看見的細節，再保留來源提供的原始文字，最後才補上自己的問題與待查方向。這個順序可以避免摘要寫得太順，卻把原本的不確定性藏掉。\n\n這件文物目前的分類是「{category}」，年代欄位保留為「{era}」，尺寸欄位為「{size}」。原始說明摘要如下：{description}\n\n之後如果找到新的研究資料，我會直接回到相對應的欄位更新，不把新的推測覆蓋掉原本的來源紀錄。也歡迎大家分享自己整理文物時會保留的欄位。",
            "近看心得" or "展陳想像" or "光線影響" or "觀看順序" =>
                $"第一次看到「{name}」時，我的注意力先被整體輪廓吸引，後來才把視線移到邊緣、表面與容易被縮圖省略的細節。這種先看整體、再回到局部的順序，讓我比較不會把一個拍攝角度當成作品的完整樣貌。\n\n圖鑑資料顯示它屬於「{category}」，年代原文為「{era}」，尺寸是「{size}」。原始說明中可以直接回查的內容是：{description}\n\n如果要把這件作品放在展示或討論情境裡，我會把目前能確認的資料和自己的觀看感受分開標示；這樣既保留第一印象，也不會把感想誤當成考證結果。",
            _ =>
                $"這次整理「{name}」時，我先從「{topic.Label}」切入，再回頭對照完整影像、尺寸和來源欄位。單看一個醒目的紋樣或顏色，很容易把局部印象放大；把不同資訊放在一起，才比較看得出哪些是穩定線索，哪些只是拍攝或保存造成的效果。\n\n目前圖鑑記載：分類「{category}」、年代「{era}」、尺寸「{size}」。原始說明提到：{description}\n\n我把這篇當成可以繼續補充的觀察筆記，不急著替作品下最後結論。若大家有相近作品或不同角度的資料，歡迎直接對照討論。"
        };

        return new GeneratedPostDraft(
            topic.BoardCode,
            "POST",
            "COMMUNITY",
            topic.Label == "整理方法" || topic.Label == "查證筆記" ? "TEMPLATE" : "CUSTOM",
            topic.Label,
            title,
            content);
    }

    private static GeneratedPostDraft BuildGamePost(
        IReadOnlyList<GameRound> gameRounds,
        Artifact? artifact,
        int index,
        int seed)
    {
        var round = gameRounds.Count == 0
            ? null
            : gameRounds[(int)(StableNumber($"game-round:{seed}:{index}") % (ulong)gameRounds.Count)];
        var roomCode = round?.Room?.RoomCode ?? "鑑定交流房";
        var roundState = round?.Status switch
        {
            "ANSWERING" => "作答階段",
            "VOTING" => "投票階段",
            "REVEALED" => "揭曉階段",
            _ => "歷史回合"
        };
        var roundLabel = round is null ? "這段遊戲紀錄" : $"第 {round.RoundNumber} 回合";
        var startedAt = round is null
            ? "時間未記錄"
            : round.StartedAt.ToLocalTime().ToString("yyyy/MM/dd HH:mm", CultureInfo.InvariantCulture);
        var artifactName = artifact?.Name.Trim();
        var variant = (int)(StableNumber($"game-post-variant:{seed}:{index}") % 6);
        var title = variant switch
        {
            0 => $"從{roomCode}的一回合看提示怎麼安排",
            1 => "玩家在鑑定遊戲裡最容易忽略的線索",
            2 => "回合結束後，我會怎麼檢查自己的判斷",
            3 => "讓新手也能參與的遊戲提示應該多明確",
            4 => "同一個答案，為什麼玩家會有不同路徑",
            _ => "把遊戲紀錄整理成下一次的學習筆記"
        };
        var titleContext = round is null
            ? $"遊戲回顧第 {index} 篇"
            : $"{roomCode}｜{startedAt}｜第 {index} 篇回顧";
        title = $"{titleContext}：{title}";
        var learningFocus = variant switch
        {
            0 => "我會先把題目提供的線索分成影像、文字與比較方向，再決定哪些資訊足以支持目前的猜測。",
            1 => "如果玩家只看到一個醒目的顏色或紋樣就急著作答，很容易忽略器形、尺寸與影像角度帶來的限制。",
            2 => "回合結束後，最值得回看的不只是答對或答錯，而是自己在什麼時候改變判斷，以及改變的理由是否留得下來。",
            3 => "對第一次參加的人來說，提示需要能讓人逐步靠近答案，卻不能直接把答案寫在提示裡，這個平衡比增加題數更重要。",
            4 => "不同玩家從同一張圖得到不同假設並不奇怪；只要能說明觀察位置與資料依據，差異就能變成很好的討論起點。",
            _ => "把一場遊戲留下的作答、投票和揭曉結果放在一起，才能看出下一次要複習的是知識、閱讀順序，還是時間分配。"
        };
        var nextStep = variant switch
        {
            0 => "下一次我想測試先給完整圖像、後補文字提示，看看玩家是否能更自然地說明自己的觀察。",
            1 => "如果有其他玩家一起回顧，我會請大家指出各自最早注意到的線索，再比較哪些線索真的能回到圖鑑資料。",
            2 => "這樣的回顧也適合保留成個人學習紀錄，讓玩家看到自己長期在哪一類題目上容易過早下結論。",
            3 => "題目說明也可以補上作答規則與剩餘時間，讓玩家把注意力放在推理，而不是猜系統下一步會怎麼做。",
            4 => "若要讓討論延續到社群，我會把不同答案的理由整理出來，再連回對應的圖鑑欄位，而不是只公布一個結果。",
            _ => "這些資料不需要被包裝成正式研究結論，但可以作為下一次出題、調整提示和設計新手教學的實際依據。"
        };
        var content = artifact is null
            ? $"我想從「{roomCode}」的{roundLabel}整理玩家如何在有限時間內讀提示、比較選項，再決定要不要把想法寫成答案。這筆紀錄開始於 {startedAt}，目前狀態是「{roundState}」。這篇談的是遊戲流程，不把勝負結果當成文物研究的唯一依據。\n\n{learningFocus} 對新手來說，我覺得最重要的是先說明自己看見的線索，再補上仍不確定的地方，讓其他玩家可以針對推理過程回應。\n\n{nextStep}"
            : $"我想從「{roomCode}」的{roundLabel}整理玩家如何在有限時間內閱讀「{artifactName}」的圖像線索，再把觀察寫成可以被其他人理解的答案。這筆紀錄開始於 {startedAt}，目前回合狀態是「{roundState}」。這篇談的是遊戲中的判斷過程，不把勝負結果當成文物研究的唯一依據。\n\n對應的文物可以回到圖鑑查看分類、年代與來源；{learningFocus} 這樣玩家可以先在遊戲裡提出假設，結束後再用正式資料檢查哪些部分有根據、哪些只是當下的直覺。\n\n{nextStep}";

        return new GeneratedPostDraft(
            "GAME",
            "POST",
            "COMMUNITY",
            variant % 2 == 0 ? "TEMPLATE" : "CUSTOM",
            "鑑定遊戲",
            title,
            content);
    }

    private static GeneratedPostDraft BuildCommunityPost(
        CommunityStory story,
        Artifact? artifact,
        ShowcaseLocation? location)
    {
        var relationship = artifact is null
            ? string.Empty
            : $"文中提到的作品可以回到圖鑑「{artifact.Name.Trim()}」核對；分類是「{artifact.Category.Name.Trim()}」，年代資料則保留「{(string.IsNullOrWhiteSpace(artifact.EraTextOriginal) ? artifact.EraBucket.Name.Trim() : artifact.EraTextOriginal.Trim())}」的原始範圍。";
        var locationNote = location is null
            ? string.Empty
            : $"這次參觀地點記為「{location.Name}」；地圖適合確認相對位置，入口、樓層和交通仍以文字說明為準。";
        var content = string.Join(
            "\n\n",
            new[] { story.Content, relationship, locationNote }
                .Where(part => !string.IsNullOrWhiteSpace(part)));

        return new GeneratedPostDraft(
            story.BoardCode,
            "POST",
            "COMMUNITY",
            story.ContentMode,
            story.TopicLabel,
            story.Title,
            content);
    }

    private static bool CanLinkArtifact(CommunityStory story) =>
        !string.Equals(story.BoardCode, "EVENTS", StringComparison.Ordinal);

    private static bool CanLinkLocation(CommunityStory story) =>
        story.BoardCode is "EVENTS" or "GENERAL" or "GUIDE" or "CATALOG" or "DISCOVERY" or "QUESTION";

    private static GeneratedPostDraft BuildEventPost(Event eventData)
    {
        var eventType = eventData.EventType == "OFFICIAL" ? "官方活動" : "會員活動";
        var start = eventData.StartAt.ToLocalTime().ToString("yyyy/MM/dd HH:mm", CultureInfo.InvariantCulture);
        var location = string.IsNullOrWhiteSpace(eventData.Location) ? "線上活動" : eventData.Location.Trim();
        var content = $"這篇貼文對應活動資料「{eventData.Title}」，活動性質為{eventType}。活動時間是 {start}，地點為「{location}」。活動內容、審核與報名狀態仍以活動資料為準，貼文提供的是社群閱讀入口。\n\n{NormalizeWhitespace(eventData.Content)}\n\n有興趣的會員可以先查看活動時間、名額與報名截止日，再決定是否參加；管理者若要修改流程，請回到活動管理處理，避免只改貼文文字造成兩邊資訊不一致。";

        return new GeneratedPostDraft(
            "EVENTS",
            "EVENT",
            eventData.EventType == "OFFICIAL" ? "OFFICIAL" : "COMMUNITY",
            "TEMPLATE",
            "活動消息",
            eventData.Title,
            content);
    }

    private static GeneratedPostDraft BuildAnnouncement(int announcementIndex, int postCount, int seed)
    {
        var title = AnnouncementTitles[(announcementIndex - 1) % AnnouncementTitles.Count];
        var variant = (int)(StableNumber($"announcement:{seed}:{announcementIndex}") % 4);
        var content = variant switch
        {
            0 => $"為了讓圖鑑、社群、遊戲與商城的展示資料可以互相對照，近期整理時會優先保留文物的原始名稱、來源、年代文字與尺寸記錄。需要推測的內容請另外標示，不會把暫時假設直接改成確定答案。\n\n目前這批展示資料共安排 {postCount} 篇不同主題的內容，社群貼文會盡可能連回實際文物；商城訂單則只會使用與文物有直接關聯的縮小複製品商品。若發現欄位需要補充，請在貼文中說明可以回查的依據。",
1 => "閱讀文物時，建議先看完整影像與基本資料，再放大局部細節。來源網址、授權標示、外部編號與故宮編號各自有不同用途，請不要為了簡短而混成同一個欄位。\n\n社群貼文可以選擇討論分類，也可以連結特定文物；公告則是官方發布的特殊貼文類型。這樣前台日後能用同一套貼文流程呈現不同內容，不需要另外維護一個獨立公告頁。",
            2 => "這次展示資料會同時保留可讀的內容與可以追查的關聯：文物連到題庫，文物也可對應商城縮小複製品；會員、貼文、留言、訂單與活動則依實際外鍵互相連結。\n\n如果資料目前不足以支持單一年份、精確用途或材質判斷，會保留原始範圍並寫明待查原因。這是為了讓展示內容看起來完整時，仍然不超過來源能證明的程度。",
            _ => "社群討論歡迎從器形、材質、紋飾、保存、來源與觀看經驗切入。長文請用段落說明觀察順序，並在引用外部資料時留下出處；若只是個人推測，也請用容易辨識的語氣說明。\n\n後續前台可以沿用這些分類、文物關聯、地點欄位與官方發布狀態，讓使用者既能手動輸入內容，也能在需要時直接從地圖或文物資料開始建立貼文。"
        };
        content += $"\n\n本則公告聚焦「{title}」，方便之後從社群分類回看相關脈絡。";

        return new GeneratedPostDraft(
            variant % 2 == 0 ? "GENERAL" : "GUIDE",
            "ANNOUNCEMENT",
            "OFFICIAL",
            "TEMPLATE",
            "官方公告",
            title,
            content);
    }

    private static string BuildComment(GeneratedPost post, int index, int slot)
    {
        var name = post.Artifact?.Name.Trim();
        return post.Kind switch
        {
            GeneratedPostKind.Game => slot == 1
                ? $"這段遊戲經驗很適合回頭檢查自己的推理順序；如果我在同一回合，會先把看見的線索說出來，再決定要不要猜答案。"
                : slot == 2
                    ? "遊戲結束後再回到圖鑑核對，應該能分清楚哪些判斷有資料支持，哪些只是當下的直覺。"
                    : "我會把這回合最早注意到的線索和最後採用的理由都記下來，下一次遇到相近題型時比較能看出自己真正需要練習的是觀察還是時間分配。",
            GeneratedPostKind.Event => slot == 1
                ? $"活動資訊整理得很完整，先看到時間與地點，再回到活動頁確認名額和報名狀態，參加前比較不容易漏掉重要條件。"
                : slot == 2
                    ? "如果之後有地圖選點，我會希望文字地址仍然保留，這樣在不同裝置或地圖載入較慢時也能看懂集合位置。"
                    : "若是第一次到場，我還會先確認入口、樓層和報到方式；這些細節不一定適合塞進標題，但對真正要參加的人很重要。",
            GeneratedPostKind.Community => slot switch
            {
                1 => $"我也很有共鳴，尤其是「{Trim(post.Post.Title, 36)}」這個細節；讀完會想起自己在展場或整理照片時遇到的類似情況。",
                2 => name is null
                    ? "你把看見的地方和還沒有把握的部分分開寫，讀起來很舒服，也讓人知道可以從哪裡接著聊。"
                    : $"你提到「{name}」時沒有只留一句好看，而是把觀看的條件和自己的想法說出來，這樣比較容易一起核對。",
                _ => "我下次遇到相近的作品或情況，會先照你寫的順序看一次；如果找到不同資料，再回來補充自己看到的差異。"
            },
            GeneratedPostKind.Announcement => slot == 1
                ? "這則公告把資料整理的原則交代得很清楚，尤其是來源、推測和平台資料要分開保存，後續查閱會安心很多。"
                : slot == 2
                    ? "如果前台之後提供更多互動，我希望仍然可以直接回到對應的文物、活動或訂單脈絡，而不是只看到一段沒有來源的文字。"
                    : "這種原則也能幫忙檢查展示資料是否過度延伸；看起來豐富的內容，仍然要讓人知道哪些是原始記錄、哪些是社群整理。",
            _ => slot == 1
                ? (index % 4) switch
                {
                    0 => $"我也會先看{name}的完整輪廓，再回頭確認這篇提到的細節。把資料欄位和照片放在一起看，確實比較不容易被單一印象帶走。",
                    1 => "這個整理方式很清楚，尤其是把能直接確認的部分和待查問題分開。之後如果找到新的來源，應該也比較容易知道要補在哪裡。",
                    2 => "我剛好在另一件相近作品上遇到類似情況，表面看起來很像，但器底與尺寸比例其實差不少。這篇提供了一個很好的比較起點。",
                    _ => $"讀完後我會想再找不同角度的影像來對照。{name}這類作品如果只看縮圖，真的很容易漏掉邊緣與接合處的線索。"
                }
                : slot == 2
                    ? (index % 4) switch
                    {
                        0 => "如果要繼續查證，我會先找同類作品的尺寸與來源資料，再回頭確認這裡的觀察是否能成立。",
                        1 => "我喜歡這篇保留不確定性的寫法，讀者可以清楚知道哪些是紀錄，哪些是作者目前的理解。",
                        2 => "這個角度也很適合拿來做遊戲題目，但題幹應該保留足夠的影像或來源提示，才不會變成猜答案。",
                        _ => "補充一個小想法：如果之後加入更多照片，可以把拍攝角度和光線條件一起記下來，會更方便比較。"
                    }
                    : "如果能再補一個可以回查的來源、比較作品或觀看角度，這段討論就不會停在第一印象，也更方便下一位會員接著整理。"
        };
    }

    private static int GetCommentCount(int postIndex) => postIndex % 3 == 0 ? 3 : 2;

    private static string NormalizeWhitespace(string value) =>
        string.Join(' ', value.Replace('\r', ' ').Replace('\n', ' ').Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries));

    private static string Trim(string value, int maxLength) =>
        value.Length <= maxLength ? value : value[..Math.Max(0, maxLength - 1)] + "…";

    private static Guid StableGuid(string value)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(value));
        bytes[6] = (byte)((bytes[6] & 0x0f) | 0x50);
        bytes[8] = (byte)((bytes[8] & 0x3f) | 0x80);
        return new Guid(bytes.AsSpan(0, 16));
    }

    private static ulong StableNumber(string value)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(value));
        ulong result = 0;
        for (var index = 0; index < 8; index++)
            result = (result << 8) | bytes[index];
        return result;
    }

    private sealed record ShowcaseUser(Guid Id, string DisplayName, string Email);

    private sealed record PostTopic(string BoardCode, string Label);

    private sealed record CommunityStory(
        string BoardCode,
        string TopicLabel,
        string ContentMode,
        string Title,
        string Content);

    private sealed record ShowcaseLocation(string Name, decimal? Latitude, decimal? Longitude);

    private sealed record DeliveryAddress(string PostalCode, string City, string District, string AddressLine);

    private sealed record GeneratedPostDraft(
        string BoardCode,
        string PostType,
        string PublisherType,
        string ContentMode,
        string TopicLabel,
        string Title,
        string Content);

    private enum GeneratedPostKind
    {
        Artifact,
        Game,
        Community,
        Event,
        Announcement
    }

    private sealed record GeneratedPost(
        int Index,
        SocialPost Post,
        Artifact? Artifact,
        Event? Event,
        GeneratedPostKind Kind,
        string TopicLabel);

    private sealed record PostGenerationResult(
        IReadOnlyList<GeneratedPost> Posts,
        int ArtifactPostCount,
        int GamePostCount,
        int CommunityPostCount,
        int EventPostCount,
        int OfficialAnnouncementCount,
        int ArtifactLinkedCount)
    {
        public int Count => Posts.Count;
    }

    private sealed record OrderGenerationResult(int Count, int DetailCount, int MiniatureOrderCount);
}
